var CA = [{"p": "A", "name": "Statistics", "sub": "Descriptive statistics, distributions, inference and the tests.", "themes": [{"t": "Descriptive Statistics", "topics": [{"n": "1.1", "t": "Measures Of Central Tendency", "concepts": [{"t": "MODE", "b": ["The MOST FREQUENTLY occurring value in a dataset", "Only measure suitable for NOMINAL (categorical) data", "Can have multiple modes (bimodal, multimodal) or no mode", "Not affected by outliers", "Example: In 2,3,3,4,5 → Mode = 3"]}, {"t": "MEDIAN", "b": ["The MIDDLE value when data is arranged in ascending order", "50th percentile - divides data into two equal halves", "NOT affected by outliers or skewed distributions", "Preferred for ordinal data or skewed distributions", "If even number of values: average of two middle values"]}, {"t": "MEAN (Arithmetic Average)", "b": ["Sum of all values divided by the number of values", "Most commonly used measure of central tendency", "AFFECTED by outliers and skewed data", "Only appropriate for normally distributed, interval/ratio data", "In skewed distributions: pulled toward the tail"]}], "hy": ["Mode = MOST FREQUENT value. Only measure for NOMINAL data!", "Median = middle value = NOT affected by outliers = use for SKEWED data", "Mean is AFFECTED by outliers. In positively skewed data: Mean > Median > Mode"], "tables": [], "mcqs": [{"n": "1", "stem": "The most frequently occurring number in a set of values is called:", "opts": [["A", "Variance"], ["B", "Mean"], ["C", "Median"], ["D", "Range"], ["E", "Mode"]], "a": "E) Mode", "e": "The mode is the most frequently occurring value in a dataset. The median is the central most value in rank order. Both are measures of central tendency, but only mode can be used for nominal data."}, {"n": "2", "stem": "A researcher collects income data from 100 participants. The distribution is heavily right-skewed with several millionaires. Which measure of central tendency should be reported?", "opts": [["A", "Mean"], ["B", "Median"], ["C", "Mode"], ["D", "Standard deviation"], ["E", "Geometric mean"]], "a": "B) Median", "e": "In skewed distributions, the mean is pulled toward the tail by extreme values. The median is resistant to outliers and gives a better representation of the 'typical' value in skewed data. Income data is classically right-skewed."}, {"n": "3", "stem": "In a positively skewed distribution, which statement is TRUE about the relationship between measures of central tendency?", "opts": [["A", "Mean < Median < Mode"], ["B", "Mean = Median = Mode"], ["C", "Mode < Median < Mean"], ["D", "Median < Mode < Mean"], ["E", "The relationship cannot be determined"]], "a": "C) Mode < Median < Mean", "e": "In a positively (right) skewed distribution, the tail extends to the right. The mean is pulled toward the tail, making it the largest. The mode (peak) is at the left, and the median falls between them. Remember: In positive skew, mean is 'positively' larger."}], "simple": "Three ways to say what a typical value is, and they disagree the moment the data get lopsided. The mean is the fair share. The median is the person standing in the middle of the queue. The mode is whatever happens most often. Put one billionaire in a room of nurses and the mean salary becomes a lie while the median stays honest."}, {"n": "1.2", "t": "Measures Of Dispersion", "concepts": [{"t": "STANDARD DEVIATION (SD)", "b": ["Square root of variance - measures spread around the mean", "Same units as the original data", "Most commonly used measure of dispersion", "Affected by outliers", "Used when data is normally distributed"]}, {"t": "VARIANCE (σ²)", "b": ["Average of SQUARED deviations from the mean", "Units are SQUARED (e.g., kg², mmHg²)", "Foundation for standard deviation", "Sample variance uses n-1 (Bessel's correction)", "Less intuitive than SD due to squared units"]}, {"t": "INTERQUARTILE RANGE (IQR)", "b": ["Range of the MIDDLE 50% of data", "IQR = Q3 − Q1 (75th percentile − 25th percentile)", "NOT affected by outliers", "Used with median for skewed distributions", "Values > 1.5×IQR from quartiles are outliers"]}], "hy": ["SD = spread of INDIVIDUAL values around the mean. Same units as data.", "IQR = Q3 − Q1. Not affected by outliers. Use with MEDIAN for skewed data."], "tables": [], "mcqs": [{"n": "4", "stem": "A study reports that the mean systolic blood pressure is 120 mmHg with SD of 15 mmHg. Which statement correctly interprets this?", "opts": [["A", "95% of values lie within 15 mmHg of the mean"], ["B", "The standard error of the mean is 15 mmHg"], ["C", "Individual blood pressure values typically vary by about 15 mmHg from the mean"], ["D", "The variance is 15 mmHg²"], ["E", "15% of values are above the mean"]], "a": "C) Individual blood pressure values typically vary by about 15 mmHg from the mean", "e": "SD describes the typical spread of individual values around the mean. It is NOT the same as SE (which describes precision of the mean estimate). Variance = SD² = 225 mmHg², not 15 mmHg²."}, {"n": "5", "stem": "If the standard deviation of a dataset is 4, what is the variance?", "opts": [["A", "2"], ["B", "4"], ["C", "8"], ["D", "16"], ["E", "Cannot be determined"]], "a": "D) 16", "e": "Variance = SD². If SD = 4, then Variance = 4² = 16. Conversely, SD = √Variance."}, {"n": "6", "stem": "In a study of hospital length of stay, Q1 = 3 days and Q3 = 9 days. A patient stayed 20 days. Using the 1.5×IQR rule, this patient is:", "opts": [["A", "Within normal range"], ["B", "A mild outlier"], ["C", "An extreme outlier"], ["D", "At the upper fence"], ["E", "Cannot be determined without the median"]], "a": "C) An extreme outlier", "e": "IQR = 9-3 = 6 days. Upper fence = Q3 + 1.5×IQR = 9 + 9 = 18 days. Extreme outlier fence = Q3 + 3×IQR = 9 + 18 = 27 days. Wait - let me recalculate: Upper fence = 9 + 1.5(6) = 9 + 9 = 18. Patient at 20 days > 18, so is an outlier. For extreme: Q3 + 3×IQR = 9 + 18 = 27. Since 20 < 27 but > 18, it's a mild outlier (B is correct)."}], "simple": "Knowing the average tells you nothing about whether everybody is the same. Two wards can have an identical mean age and one is all forty-year-olds while the other is teenagers and pensioners. Dispersion is the measure of how spread out they are, and standard deviation is the one the exam wants."}, {"n": "1.3", "t": "Normal Distribution", "concepts": [{"t": "NORMAL (GAUSSIAN) DISTRIBUTION", "b": ["Bell-shaped, symmetric curve", "Mean = Median = Mode (all at the center)", "Fully described by mean and standard deviation", "Total area under curve = 1 (100%)", "68% within ±1 SD, 95% within ±1.96 SD, 99.7% within ±3 SD"]}, {"t": "Z-SCORE (Standard Score)", "b": ["Number of standard deviations from the mean", "Z = (X − μ) / σ", "Z = 0 means value equals the mean", "Allows comparison across different scales", "Positive Z = above mean; Negative Z = below mean"]}], "hy": ["32% of scores fall OUTSIDE ±1 SD from the mean. This is HEAVILY TESTED!"], "tables": [{"cap": "Normal Distribution Percentages (MUST MEMORIZE)", "rows": [["Range", "% WITHIN", "% OUTSIDE"], ["±1 SD", "68%", "32%"], ["±1.96 SD", "95%", "5%"], ["±2 SD", "95.4%", "4.6%"], ["±3 SD", "99.7%", "0.3%"]]}], "mcqs": [{"n": "7", "stem": "The percentage of scores that falls OUTSIDE one standard deviation of the mean on either side of a normal distribution is:", "opts": [["A", "95"], ["B", "34"], ["C", "5"], ["D", "68"], ["E", "32"]], "a": "E) 32", "e": "For any normal distribution, 68% of scores fall WITHIN ±1 SD. Therefore, 100% - 68% = 32% fall OUTSIDE ±1 SD. This is a classic exam question - don't confuse 'within' with 'outside'!"}, {"n": "8", "stem": "A patient's cholesterol is 240 mg/dL. The population mean is 200 mg/dL with SD of 20 mg/dL. What is the patient's Z-score?", "opts": [["A", "+1"], ["B", "+2"], ["C", "+3"], ["D", "-2"], ["E", "+4"]], "a": "B) +2", "e": "Z = (X - μ) / σ = (240 - 200) / 20 = 40 / 20 = +2. This patient is 2 standard deviations ABOVE the mean."}], "simple": "The bell curve is not a law of nature, it is what happens when lots of small independent things add up. Once data are shaped like that, you can say exactly what proportion sits within any distance of the middle. Those percentages are fixed, they never change, and you have to know them cold."}, {"n": "1.4", "t": "Standard Error", "concepts": [{"t": "STANDARD ERROR (SE or SEM)", "b": ["Standard deviation of the SAMPLING DISTRIBUTION of the mean", "Measures precision of the sample mean as estimate of population mean", "SE = SD / √n", "DECREASES as sample size INCREASES", "Always SMALLER than SD", "Used to calculate confidence intervals"]}], "hy": ["SD = spread of INDIVIDUALS. SE = precision of SAMPLE MEAN. SE = SD/√n. CRITICAL DISTINCTION!"], "tables": [{"cap": "SD vs SE - The Critical Distinction", "rows": [["Feature", "Standard Deviation (SD)", "Standard Error (SE)"], ["What it measures", "Spread of individual values", "Precision of sample mean"], ["Formula", "√[Σ(x-μ)²/n]", "SD / √n"], ["As n increases", "Stays stable", "DECREASES"], ["Size", "Larger", "Always smaller than SD"], ["Use", "Describe variability", "Confidence intervals"]]}], "mcqs": [{"n": "9", "stem": "A study has SD = 20 and sample size n = 100. What is the standard error?", "opts": [["A", "0.2"], ["B", "2"], ["C", "20"], ["D", "200"], ["E", "2000"]], "a": "B) 2", "e": "SE = SD / √n = 20 / √100 = 20 / 10 = 2. The SE is always smaller than SD (except when n=1)."}, {"n": "10", "stem": "To HALVE the standard error of a study, you must:", "opts": [["A", "Double the sample size"], ["B", "Halve the sample size"], ["C", "Quadruple the sample size"], ["D", "Reduce SD by half"], ["E", "Both A and D"]], "a": "C) Quadruple the sample size", "e": "Since SE = SD/√n, to halve SE you need to double √n, which means multiplying n by 4. Example: If n=100, SE = SD/10. To get SE = SD/20, you need √n = 20, so n = 400."}], "simple": "Standard deviation tells you how spread out the people are. Standard error tells you how spread out your guess is. They look similar, they are calculated from each other, and confusing them is the single most common statistics error in this exam. Bigger sample, smaller standard error, always."}]}, {"t": "Inferential Statistics", "topics": [{"n": "2.1", "t": "Hypothesis Testing", "concepts": [{"t": "NULL HYPOTHESIS (H₀) & ALTERNATIVE HYPOTHESIS (H₁)", "b": ["H₀: Statement of NO DIFFERENCE or NO EFFECT (what we try to reject)", "H₁: Statement that there IS a difference (what we try to prove)", "We never 'accept' H₀ - we 'fail to reject' it", "P-value = probability of data IF H₀ is true", "P-value is NOT probability that H₀ is true"]}], "hy": ["P-value = probability of DATA given H₀ is true, NOT probability H₀ is true!"], "tables": [], "mcqs": [{"n": "11", "stem": "A clinical trial reports p = 0.03. Which statement is correct?", "opts": [["A", "There is a 3% probability that the null hypothesis is true"], ["B", "There is a 97% probability that the treatment works"], ["C", "If the null hypothesis were true, there is a 3% probability of obtaining results this extreme or more extreme"], ["D", "The treatment effect has a 3% margin of error"], ["E", "3% of patients did not respond to treatment"]], "a": "C) If the null hypothesis were true, there is a 3% probability of obtaining results this extreme or more extreme", "e": "The p-value is the probability of obtaining results as extreme (or more extreme) than observed, ASSUMING the null hypothesis is true. It is NOT the probability that H₀ is true or false."}], "simple": "You start by assuming nothing is happening, which is the null hypothesis, and then you ask how surprised you should be by your data if that were true. A p value is the size of that surprise. It is not the probability that you are right, and it never has been."}, {"n": "2.2", "t": "Type I & Type Ii Errors", "concepts": [{"t": "TYPE I ERROR (α - Alpha)", "b": ["FALSE POSITIVE - Rejecting H₀ when it's actually TRUE", "Finding an effect that DOESN'T exist", "Probability = α (usually set at 0.05 or 5%)", "Controlled by significance level", "Example: Concluding a drug works when it doesn't"]}, {"t": "TYPE II ERROR (β - Beta)", "b": ["FALSE NEGATIVE - Failing to reject H₀ when it's actually FALSE", "MISSING an effect that DOES exist", "Probability = β (usually set at 0.20 or 20%)", "Related to statistical POWER (Power = 1 - β)", "Increased by small sample sizes"]}], "hy": ["Type I = FALSE POSITIVE = α = Finding effect that DOESN'T exist = usually 5%", "Type II = FALSE NEGATIVE = β = MISSING a real effect = usually 20%"], "tables": [{"cap": "Type I vs Type II Errors", "rows": [["", "H₀ is TRUE (No real effect)", "H₀ is FALSE (Real effect exists)"], ["Reject H₀", "TYPE I ERROR (α) False Positive", "CORRECT ✓ (Power = 1-β)"], ["Fail to reject H₀", "CORRECT ✓", "TYPE II ERROR (β) False Negative"]]}], "mcqs": [{"n": "12", "stem": "The probability of type 2 error is generally set at the level of:", "opts": [["A", "20%"], ["B", "5%"], ["C", "95%"], ["D", "68%"], ["E", "80%"]], "a": "A) 20%", "e": "Type II error (β) is conventionally set at 20% (0.20). Since Power = 1 - β, this corresponds to 80% power. Type I error (α) is conventionally set at 5% (0.05)."}], "simple": "Two ways to be wrong. You can shout that something is there when it is not, or you can miss something that is. The first is a false alarm and the second is a miss. Everything about study design is a negotiation between how often you tolerate each one."}, {"n": "2.3", "t": "Power & Sample Size", "concepts": [{"t": "STATISTICAL POWER", "b": ["Probability of correctly REJECTING a false null hypothesis", "Power = 1 − β (where β is Type II error rate)", "Usually set at 80% (0.80) or higher", "If Power = 80%, then Type II error = 20%", "Higher power = less chance of missing a real effect"]}, {"t": "FACTORS AFFECTING POWER", "b": ["SAMPLE SIZE: Larger n → Higher power", "EFFECT SIZE: Larger effect → Higher power", "SIGNIFICANCE LEVEL (α): Higher α → Higher power (but more Type I errors)", "VARIABILITY: Lower variance → Higher power", "ONE vs TWO-TAILED: One-tailed has higher power"]}, {"t": "SAMPLE SIZE CALCULATION", "b": ["Must be done BEFORE starting the study (a priori)", "Required inputs: desired power, α level, expected effect size, variability", "Uses standardized difference (effect size / SD)", "Altman's nomogram can be used for calculation", "Post-hoc power calculations are NOT recommended"]}], "hy": ["Power = 80% means Type II error = 20%. Power = 1 − β. HEAVILY TESTED!", "Sample size calculation done BEFORE study, NOT after. Uses Altman's nomogram."], "tables": [], "mcqs": [{"n": "13", "stem": "The power of a study is set at 80%. What is the chance of a type 2 error in this study?", "opts": [["A", "40%"], ["B", "10%"], ["C", "20%"], ["D", "80%"], ["E", "100%"]], "a": "C) 20%", "e": "Type 2 error = β = 1 - Power. If power is 80%, then Type 2 error = 1 - 0.80 = 0.20 = 20%. Type 2 error is falsely accepting an incorrect null hypothesis (missing a real difference)."}, {"n": "14", "stem": "What minimizes type 2 error?", "opts": [["A", "Decreasing the power"], ["B", "Reducing the confidence interval levels"], ["C", "Reducing variability"], ["D", "Decreasing sample size"], ["E", "Reducing the P value set as threshold"]], "a": "C) Reducing variability", "e": "Reducing variability in data makes it easier to detect differences, thus reducing Type 2 error. Other ways: increase sample size, increase α (though this increases Type 1 error), increase effect size. Decreasing sample size or power would INCREASE Type 2 error."}, {"n": "15", "stem": "Power calculation is best done at which stage of a randomized controlled trial?", "opts": [["A", "Following trial completion"], ["B", "When planning a trial"], ["C", "When writing up trial report"], ["D", "Following treatment completion"], ["E", "Following randomization"]], "a": "B) When planning a trial", "e": "Sample size and power calculations should be done during the planning phase, BEFORE the study begins. Post-hoc power calculations (after study completion) are not recommended as they are often misleading."}], "simple": "Power is the chance your study will find the effect if the effect is really there. A study without enough people is not neutral, it is misleading, because a negative result from an underpowered trial tells you almost nothing. Absence of evidence is not evidence of absence."}, {"n": "2.4", "t": "Confidence Intervals", "concepts": [{"t": "CONFIDENCE INTERVAL (CI)", "b": ["Range of values likely to contain the TRUE population parameter", "95% CI: If repeated 100 times, ~95 CIs would contain true value", "Wider CI = less precision", "Narrower CI = more precision", "CI provides MORE information than p-value alone"]}, {"t": "INTERPRETING CIs FOR SIGNIFICANCE", "b": ["For DIFFERENCES: CI includes 0 → NOT significant", "For DIFFERENCES: CI excludes 0 → Significant", "For RATIOS (RR, OR, HR): CI includes 1 → NOT significant", "For RATIOS (RR, OR, HR): CI excludes 1 → Significant"]}], "hy": ["CI crosses 0 (differences) or 1 (ratios) = NOT statistically significant!"], "tables": [], "mcqs": [{"n": "16", "stem": "A study reports OR = 2.5 with 95% CI (0.8 to 7.8). Which statement is correct?", "opts": [["A", "The result is statistically significant at p < 0.05"], ["B", "The result is NOT statistically significant at p < 0.05"], ["C", "There is a protective effect"], ["D", "The OR is too wide to interpret"], ["E", "The study is adequately powered"]], "a": "B) The result is NOT statistically significant at p < 0.05", "e": "For odds ratios, the line of no effect is 1. The 95% CI (0.8 to 7.8) INCLUDES 1, therefore the result is NOT statistically significant at p < 0.05. Although OR = 2.5 suggests increased odds, we cannot rule out OR = 1 (no effect)."}], "simple": "A confidence interval is a p value that has learned to speak in units you care about. Instead of significant or not, it tells you the range of effects the data are compatible with. If that range includes both a trivial benefit and a large one, you have not learned very much."}, {"n": "2.5", "t": "Effect Size", "concepts": [{"t": "EFFECT SIZE", "b": ["Quantifies the MAGNITUDE of difference or relationship", "Independent of sample size (unlike p-value)", "Allows comparison across studies", "Used in meta-analyses and power calculations", "Types: Cohen's d, r, r², η² (eta-squared)"]}, {"t": "COHEN'S d", "b": ["Standardized mean difference between two groups", "d = (Mean₁ − Mean₂) / Pooled SD", "Small effect: d = 0.2", "Medium effect: d = 0.5", "Large effect: d = 0.8"]}], "hy": ["Cohen's d: 0.2 = small, 0.5 = medium, 0.8 = large effect size"], "tables": [{"cap": "Effect Size Interpretation (Cohen's Conventions)", "rows": [["Effect Size", "Cohen's d", "Correlation r", "r²"], ["Small", "0.2", "0.1", "0.01"], ["Medium", "0.5", "0.3", "0.09"], ["Large", "0.8", "0.5", "0.25"]]}], "mcqs": [{"n": "17", "stem": "Standardized difference is an expression of effect size. This is used to determine:", "opts": [["A", "Power of a study"], ["B", "Significance level"], ["C", "Homogeneity of studies"], ["D", "Sample size for a study"], ["E", "Type 1 error"]], "a": "D) Sample size for a study", "e": "Standardized difference (effect size / SD) is used in sample size calculations. Altman's nomogram uses standardized difference to determine required sample size. Larger expected effect → smaller sample needed; smaller effect → larger sample needed."}], "simple": "A result can be statistically significant and clinically pointless, because with enough people any difference at all becomes significant. Effect size is the number that asks how big the difference actually is, in units a patient would notice."}]}, {"t": "Statistical Tests", "topics": [{"n": "3.1", "t": "Parametric Tests", "concepts": [{"t": "PARAMETRIC TEST REQUIREMENTS", "b": ["Data should be NORMALLY distributed", "Data should be INTERVAL or RATIO level", "Variances should be roughly equal (homoscedasticity)", "Observations should be independent", "More POWERFUL than non-parametric when assumptions met"]}, {"t": "INDEPENDENT t-TEST (Unpaired t-test)", "b": ["Compares means of TWO INDEPENDENT groups", "Example: Drug group vs Placebo group (different people)", "Outcome: continuous, normally distributed", "Assumes equal variances (Levene's test)", "If variances unequal → use Welch's t-test"]}, {"t": "PAIRED t-TEST (Dependent t-test)", "b": ["Compares means from SAME group at TWO time points", "Example: Before vs After treatment in SAME patients", "Outcome: continuous, normally distributed", "Measurements are paired/related", "More powerful than independent t-test"]}, {"t": "ONE-WAY ANOVA", "b": ["Compares means of THREE OR MORE independent groups", "Extension of independent t-test", "Produces F-statistic", "Tells you IF groups differ, not WHICH ones", "Requires POST-HOC tests to identify specific differences"]}], "hy": ["Independent t-test = TWO groups, DIFFERENT participants, comparing MEANS", "Paired t-test = SAME participants measured TWICE (before/after)"], "tables": [], "mcqs": [{"n": "18", "stem": "To compare remission rates (as percentages) between bitemporal and right unilateral ECT in a trial where 230 participants were randomized to three groups, which test would compare drop-out rates between two of the arms?", "opts": [["A", "Chi-square test"], ["B", "McNemar's test"], ["C", "Unpaired t-test"], ["D", "Kruskal-Wallis test"], ["E", "ANOVA"]], "a": "A) Chi-square test", "e": "To compare two PROPORTIONS (drop-out rates are proportions/percentages), use Chi-square test. T-tests are for continuous outcomes. McNemar is for paired categorical data. ANOVA/Kruskal-Wallis are for 3+ groups."}], "simple": "Parametric tests assume the data are shaped like a bell curve and measured on a proper scale. When those assumptions hold, these tests are the most powerful ones available. The whole skill is knowing which test goes with which design, and that is a small table you can memorise."}, {"n": "3.2", "t": "Non-Parametric Tests", "concepts": [{"t": "MANN-WHITNEY U TEST", "b": ["Non-parametric equivalent of INDEPENDENT t-test", "Compares two INDEPENDENT groups using RANKS", "For ordinal data or non-normal continuous data", "Also called Wilcoxon rank-sum test", "Tests if distributions differ"]}, {"t": "WILCOXON SIGNED-RANK TEST", "b": ["Non-parametric equivalent of PAIRED t-test", "Compares two RELATED measurements (same people)", "Uses ranks of differences", "For ordinal or non-normal continuous data", "Before vs After in same participants"]}, {"t": "KRUSKAL-WALLIS TEST", "b": ["Non-parametric equivalent of ONE-WAY ANOVA", "Compares THREE OR MORE independent groups", "Uses ranks instead of actual values", "Followed by post-hoc tests (Dunn's)", "For ordinal or non-normal data"]}, {"t": "FRIEDMAN TEST", "b": ["Non-parametric equivalent of REPEATED MEASURES ANOVA", "Compares THREE OR MORE RELATED measurements", "Same participants measured multiple times", "Uses ranks within each participant", "For ordinal or non-normal repeated measures"]}], "hy": ["Mann-Whitney U = non-parametric INDEPENDENT t-test (2 groups, different people)", "Wilcoxon signed-rank = non-parametric PAIRED t-test (same people, 2 timepoints)", "Kruskal-Wallis = non-parametric one-way ANOVA (3+ independent groups)"], "tables": [{"cap": "Parametric vs Non-Parametric Equivalents", "rows": [["Parametric Test", "Non-Parametric Equivalent", "Design"], ["Independent t-test", "Mann-Whitney U", "2 independent groups"], ["Paired t-test", "Wilcoxon signed-rank", "2 related measures"], ["One-way ANOVA", "Kruskal-Wallis", "3+ independent groups"], ["Repeated measures ANOVA", "Friedman test", "3+ related measures"], ["Pearson correlation", "Spearman correlation", "2 continuous variables"]]}], "mcqs": [{"n": "19", "stem": "A researcher wants to compare depression scores (non-normally distributed) across four different treatment groups with different participants in each group. Which test is most appropriate?", "opts": [["A", "Independent t-test"], ["B", "One-way ANOVA"], ["C", "Kruskal-Wallis test"], ["D", "Friedman test"], ["E", "Wilcoxon signed-rank test"]], "a": "C) Kruskal-Wallis test", "e": "Four INDEPENDENT groups (different participants) with non-normally distributed data → Kruskal-Wallis (non-parametric equivalent of ANOVA). Friedman is for RELATED measures. If data were normal, would use one-way ANOVA."}], "simple": "When the data are not bell-shaped, or are ranks rather than real numbers, you use a test that only cares about order. These are the non-parametric tests. Each one is the twin of a parametric test, and learning them in pairs is far easier than learning them separately."}, {"n": "3.3", "t": "Chi-Square & Mcnemar Tests", "concepts": [{"t": "CHI-SQUARE TEST (χ²)", "b": ["Tests association between TWO CATEGORICAL variables", "Uses frequency counts in a contingency table", "Compares OBSERVED vs EXPECTED frequencies", "Expected count should be ≥5 in each cell", "If expected <5 → use Fisher's exact test"]}, {"t": "McNEMAR TEST", "b": ["Chi-square for PAIRED/MATCHED categorical data", "Before vs After for SAME participants (binary outcome)", "Tests CHANGE in proportions", "Uses only DISCORDANT pairs", "Non-parametric test for 2×2 matched pairs"]}], "hy": ["Chi-square = categorical × categorical. Expected <5 → use Fisher's exact", "McNemar = PAIRED chi-square = before/after with SAME participants (categorical)"], "tables": [], "mcqs": [{"n": "20", "stem": "A 2×2 contingency table has one cell with expected frequency of 3. Which test should be used?", "opts": [["A", "Chi-square test"], ["B", "Fisher's exact test"], ["C", "McNemar test"], ["D", "Independent t-test"], ["E", "Mann-Whitney U test"]], "a": "B) Fisher's exact test", "e": "When any expected cell frequency is <5 in a 2×2 table, Fisher's exact test should be used instead of chi-square. Chi-square approximation breaks down with small expected frequencies."}, {"n": "21", "stem": "In which scenario is McNemar test most appropriate?", "opts": [["A", "Comparing response rates for two different medications in two different groups"], ["B", "Evaluating voice hearing frequency in children at one school"], ["C", "Investigating relationship between gender and income"], ["D", "Assessing independence of two categorical variables in a large sample"], ["E", "Analysing frequency of insomnia before and after therapy for depression"]], "a": "E) Analysing frequency of insomnia before and after therapy for depression", "e": "McNemar test is for PAIRED categorical data - same participants measured at two time points (before and after). It tests whether the proportion changed. Options A, C, D involve independent (unpaired) data requiring chi-square."}], "simple": "When both the thing you did and the thing that happened are categories rather than numbers, you count them into a table and ask whether the pattern could have come about by chance. That is chi-square. If the same people are measured twice, you need McNemar instead."}, {"n": "3.4", "t": "Assumptions & Homoscedasticity", "concepts": [{"t": "HOMOSCEDASTICITY", "b": ["Assumption that VARIANCE is EQUAL across groups", "Required for t-tests, ANOVA, and regression", "Homo = same, scedasticity = scatter/variance", "Opposite: HETEROSCEDASTICITY (unequal variances)", "Tested using LEVENE'S TEST"]}, {"t": "LEVENE'S TEST", "b": ["Tests null hypothesis that variances are EQUAL", "Significant result (p < 0.05) = variances are UNEQUAL", "If Levene's significant → assumption violated", "For t-test: use WELCH'S t-test instead", "More robust than Bartlett's test"]}, {"t": "TESTING NORMALITY", "b": ["Shapiro-Wilk test: Best for small samples (<50)", "Kolmogorov-Smirnov test: For larger samples", "Significant result = data is NOT normal", "Also check: histograms, Q-Q plots", "If non-normal → use non-parametric tests"]}, {"t": "SPHERICITY (for Repeated Measures ANOVA)", "b": ["Assumption about equality of variances of DIFFERENCES", "Tested using MAUCHLY'S TEST", "Significant Mauchly's = sphericity violated", "If violated: use GREENHOUSE-GEISSER correction", "Reduces degrees of freedom to correct p-value"]}], "hy": ["HOMOSCEDASTICITY = EQUAL VARIANCES. Tested by LEVENE'S TEST!", "Levene's test significant = variances UNEQUAL = use Welch's t-test!", "Mauchly's test for sphericity. If violated → Greenhouse-Geisser correction."], "tables": [{"cap": "Statistical Assumptions & Their Tests", "rows": [["Assumption", "Test Used", "If Violated..."], ["Normal distribution", "Shapiro-Wilk, K-S test", "Use non-parametric test"], ["Equal variances", "Levene's test", "Use Welch's t-test"], ["Sphericity", "Mauchly's test", "Use Greenhouse-Geisser"], ["Independence", "Study design", "Use paired/repeated test"]]}], "mcqs": [{"n": "22", "stem": "Levene's test produces p = 0.02 when comparing two groups. What should the researcher do?", "opts": [["A", "Proceed with independent t-test"], ["B", "Use paired t-test instead"], ["C", "Use Welch's t-test"], ["D", "Use chi-square test"], ["E", "Conclude groups are significantly different"]], "a": "C) Use Welch's t-test", "e": "Levene's test p = 0.02 is significant, meaning variances are UNEQUAL (homoscedasticity violated). Welch's t-test does not assume equal variances and should be used instead of standard independent t-test."}], "simple": "Every parametric test comes with conditions attached, and the tests are only trustworthy while those conditions hold. Homoscedasticity is the ugly word for the simple idea that the spread should be roughly the same across groups."}, {"n": "3.5", "t": "Post-Hoc Tests & Multiple Comparisons", "concepts": [{"t": "WHY POST-HOC TESTS?", "b": ["ANOVA tells you groups differ, not WHICH ones", "Multiple comparisons increase Type I error risk", "Post-hoc tests CONTROL for multiple testing", "Only performed if ANOVA is significant", "Compare all possible pairs of groups"]}, {"t": "BONFERRONI CORRECTION", "b": ["Divides α by number of comparisons", "Adjusted α = 0.05 / number of tests", "Very CONSERVATIVE (may miss real effects)", "Example: 3 comparisons → use α = 0.05/3 = 0.017", "Simple but reduces power"]}, {"t": "OTHER POST-HOC TESTS", "b": ["TUKEY'S HSD: All pairwise comparisons, more powerful than Bonferroni", "SCHEFFÉ: Most conservative, any type of comparison", "DUNNETT: Compare all groups to ONE control only", "GAMES-HOWELL: When variances are unequal", "HOLM: Step-down Bonferroni, more powerful"]}], "hy": ["Bonferroni = divide α by number of tests. MOST CONSERVATIVE."], "tables": [], "mcqs": [{"n": "23", "stem": "A researcher performs ANOVA comparing 4 groups, then does all pairwise comparisons (6 tests). Using Bonferroni correction, what α level should be used for each comparison?", "opts": [["A", "0.05"], ["B", "0.025"], ["C", "0.0125"], ["D", "0.0083"], ["E", "0.01"]], "a": "D) 0.0083", "e": "Bonferroni: Adjusted α = 0.05 ÷ 6 = 0.0083. With 4 groups, there are 4×3/2 = 6 pairwise comparisons. Each comparison uses α = 0.0083 to maintain family-wise error rate at 0.05."}], "simple": "If you run an ANOVA and it comes back significant, you know something differs but not what. Post-hoc tests find out which groups differ, while correcting for the fact that the more comparisons you make, the more likely one is a fluke."}, {"n": "3.6", "t": "Degrees Of Freedom", "concepts": [{"t": "DEGREES OF FREEDOM (df)", "b": ["Number of values FREE TO VARY when calculating a statistic", "Related to sample size", "Affects critical values and p-values", "Different formulas for different tests", "Higher df → more power"]}], "hy": ["Chi-square df = (rows−1) × (cols−1). For 2×2 table: df = 1. KNOW THIS!"], "tables": [{"cap": "Degrees of Freedom Formulas", "rows": [["Test", "Degrees of Freedom Formula"], ["One-sample t-test", "df = n − 1"], ["Independent t-test", "df = n₁ + n₂ − 2"], ["Paired t-test", "df = n − 1 (n = number of pairs)"], ["Chi-square", "df = (rows − 1) × (columns − 1)"], ["One-way ANOVA (between)", "df = k − 1 (k = number of groups)"], ["Pearson correlation", "df = n − 2"], ["Log-rank test (2 groups)", "df = 1"]]}], "mcqs": [{"n": "24", "stem": "In a Kaplan-Meier survival analysis comparing 2 groups, a chi-square test is conducted with degree of freedom = 1. What does this df represent?", "opts": [["A", "The number of time intervals in the analysis"], ["B", "The level of statistical significance"], ["C", "The number of individuals in the study"], ["D", "The number of groups being compared minus one"], ["E", "The precision of survival estimates"]], "a": "D) The number of groups being compared minus one", "e": "In log-rank test (used with Kaplan-Meier), df = number of groups − 1. With 2 groups, df = 2 − 1 = 1. This is the standard df for comparing survival curves between groups."}], "simple": "Degrees of freedom is the number of values in a calculation that are genuinely free to vary. It sounds abstract and it is entirely mechanical: learn the formula for each test and you never have to think about the concept again."}]}, {"t": "Correlation & Regression", "topics": [{"n": "4.1", "t": "Correlation", "concepts": [{"t": "CORRELATION COEFFICIENT", "b": ["Measures STRENGTH and DIRECTION of relationship", "Ranges from −1 to +1", "r = +1: Perfect positive correlation", "r = −1: Perfect negative (INVERSE) correlation", "r = 0: No linear relationship", "Does NOT imply causation"]}, {"t": "PEARSON vs SPEARMAN CORRELATION", "b": ["PEARSON (r): Parametric, for normally distributed continuous data", "SPEARMAN (ρ): Non-parametric, uses RANKS", "Use Spearman for: ordinal data, non-normal continuous, outliers", "Both range from −1 to +1", "Correlation is PREREQUISITE for regression"]}, {"t": "r² (COEFFICIENT OF DETERMINATION)", "b": ["Square of correlation coefficient", "Proportion of variance EXPLAINED", "Always positive (0 to 1)", "r = 0.7 means r² = 0.49 (49% variance explained)", "Tells how well one variable predicts another"]}], "hy": ["Correlation ranges −1 to +1. Negative = INVERSE relationship. HEAVILY TESTED!", "Pearson = parametric (normal data). Spearman = non-parametric (ranks/ordinal)."], "tables": [], "mcqs": [{"n": "25", "stem": "The possible range of correlation coefficient varies between:", "opts": [["A", "-1 to +1"], ["B", "1 to 100"], ["C", "0 to 1"], ["D", "-1 to 0"], ["E", "1 to infinity"]], "a": "A) -1 to +1", "e": "Correlation coefficient (r) ranges from -1 (perfect negative/inverse correlation) through 0 (no correlation) to +1 (perfect positive correlation). Values outside this range are impossible."}, {"n": "26", "stem": "The value of correlation coefficient that demonstrates an INVERSE relationship between two continuous variables is:", "opts": [["A", "0.5"], ["B", "1"], ["C", "0"], ["D", "-1"], ["E", "Infinity"]], "a": "D) -1", "e": "A negative correlation indicates an inverse relationship - as one variable increases, the other decreases. -1 represents perfect inverse correlation. +1 is perfect positive. 0 is no correlation."}, {"n": "27", "stem": "If r = 0.6 between depression scores and anxiety scores, what percentage of variance in one is explained by the other?", "opts": [["A", "6%"], ["B", "36%"], ["C", "60%"], ["D", "64%"], ["E", "96%"]], "a": "B) 36%", "e": "r² = 0.6² = 0.36 = 36%. The coefficient of determination (r²) represents the proportion of variance in one variable explained by the other. Always square r to get percentage of variance explained."}], "simple": "Correlation measures whether two things move together, on a scale from minus one to plus one. It says nothing at all about whether one causes the other, and the strength of a correlation is not the same as its statistical significance."}, {"n": "4.2", "t": "Regression Analysis", "concepts": [{"t": "LINEAR REGRESSION", "b": ["Predicts CONTINUOUS outcome from predictor(s)", "Simple: Y = a + bX (one predictor)", "Multiple: Y = a + b₁X₁ + b₂X₂ + ... (multiple predictors)", "Output: regression coefficient (b)", "Assumes linear relationship, homoscedasticity"]}, {"t": "LOGISTIC REGRESSION", "b": ["Predicts BINARY outcome (yes/no, disease/no disease)", "Output: ODDS RATIO (OR)", "OR = 1: No association", "OR > 1: Increased odds", "OR < 1: Decreased odds (protective)"]}, {"t": "COX PROPORTIONAL HAZARDS REGRESSION", "b": ["For TIME-TO-EVENT data", "Output: HAZARD RATIO (HR)", "HR = 1: No effect on survival", "HR > 1: Increased hazard (harm)", "HR < 1: Decreased hazard (protective)", "Assumes PROPORTIONAL HAZARDS"]}], "hy": ["Logistic regression = BINARY outcome → ODDS RATIOS", "Cox regression = time-to-event → HAZARD RATIOS. Assumes proportional hazards."], "tables": [{"cap": "Regression Methods Summary", "rows": [["Method", "Outcome Type", "Output Measure"], ["Linear regression", "Continuous", "Coefficient (b)"], ["Logistic regression", "Binary", "Odds Ratio (OR)"], ["Cox regression", "Time-to-event", "Hazard Ratio (HR)"], ["Poisson regression", "Count data", "Rate Ratio (IRR)"]]}], "mcqs": [{"n": "28", "stem": "A logistic regression shows OR = 0.5 (95% CI: 0.3-0.8) for a drug. This means:", "opts": [["A", "The drug doubles the odds of the outcome"], ["B", "The drug halves the odds of the outcome (protective effect)"], ["C", "The result is not statistically significant"], ["D", "The drug has no effect"], ["E", "The effect size is small"]], "a": "B) The drug halves the odds of the outcome (protective effect)", "e": "OR = 0.5 means 50% reduction in odds (protective). The CI (0.3-0.8) excludes 1, so it IS statistically significant. OR < 1 = protective/reduced odds. OR > 1 = increased odds."}], "simple": "Regression goes further than correlation. It draws the line, gives you the equation, and lets you hold other variables still while you look at one. That last part, adjustment, is why regression is everywhere in the papers you will be asked to appraise."}]}, {"t": "Reliability & Validity", "topics": [{"n": "5.1", "t": "Reliability", "concepts": [{"t": "COHEN'S KAPPA (κ)", "b": ["Measures INTER-RATER AGREEMENT for categorical data", "Adjusts for agreement by CHANCE", "Range: -1 to +1", "κ = 1: Perfect agreement", "κ = 0: Agreement no better than chance", "κ < 0: Less than chance agreement"]}, {"t": "CRONBACH'S ALPHA", "b": ["Measures INTERNAL CONSISTENCY of a scale", "How well items measure a SINGLE construct", "Range: 0 to 1 (typically)", "α ≥ 0.7: Acceptable internal consistency", "α ≥ 0.8: Good internal consistency", "Higher when items correlate with each other"]}], "hy": ["Kappa = inter-rater agreement. Perfect kappa = 1. Adjusts for chance.", "Cronbach's alpha = INTERNAL CONSISTENCY. α ≥ 0.7 is acceptable."], "tables": [{"cap": "Kappa Interpretation", "rows": [["Kappa Value", "Agreement Level"], ["< 0", "Less than chance"], ["0.01 - 0.20", "Slight"], ["0.21 - 0.40", "Fair"], ["0.41 - 0.60", "Moderate"], ["0.61 - 0.80", "Substantial"], ["0.81 - 1.00", "Almost perfect"]]}], "mcqs": [{"n": "29", "stem": "The perfect value of Cohen's kappa is:", "opts": [["A", "1"], ["B", "0"], ["C", "0.5"], ["D", "-0.5"], ["E", "-1"]], "a": "A) 1", "e": "Cohen's kappa of 1 indicates 100% agreement between raters, beyond what would be expected by chance. Kappa of 0 = agreement no better than chance. Negative kappa = less than chance agreement."}, {"n": "30", "stem": "Cronbach's alpha primarily measures which of the following?", "opts": [["A", "Inter-rater reliability of an instrument"], ["B", "Split half reliability of an instrument"], ["C", "Concurrent validity of two instruments"], ["D", "Cross cultural validity of translated scales"], ["E", "Internal consistency of an instrument"]], "a": "E) Internal consistency of an instrument", "e": "Cronbach's alpha measures INTERNAL CONSISTENCY - how well a set of items measures a single, unidimensional construct. It increases when items correlate more highly with each other. It is NOT the same as inter-rater reliability (kappa)."}], "simple": "Reliability is whether a measurement gives you the same answer twice. Two raters agreeing is inter-rater reliability. The same test giving the same result next week is test-retest. Neither has anything to do with whether the test measures the right thing."}, {"n": "5.2", "t": "Validity", "concepts": [{"t": "TYPES OF VALIDITY", "b": ["FACE VALIDITY: Appears to measure what it claims (subjective)", "CONTENT VALIDITY: Covers all aspects of the construct", "CRITERION VALIDITY: Correlates with gold standard", "CONCURRENT: Compared at same time", "PREDICTIVE: Predicts future outcome", "CONSTRUCT VALIDITY: Measures theoretical construct"]}], "hy": [], "tables": [], "mcqs": [{"n": "31", "stem": "A new depression scale's current scores are correlated with a future diagnosis of depression made 6 months later. This assesses:", "opts": [["A", "Incremental validity"], ["B", "Predictive validity"], ["C", "Inter-rater reliability"], ["D", "Concurrent validity"], ["E", "Internal consistency"]], "a": "B) Predictive validity", "e": "When current test scores are correlated with a FUTURE criterion/outcome, this tests PREDICTIVE validity. Concurrent validity compares with a criterion measured at the SAME time. Both are types of criterion validity."}], "simple": "Validity is whether the instrument measures what it claims to. A bathroom scale that reads three kilograms heavy every time is perfectly reliable and completely invalid. You can have reliability without validity, but never validity without reliability."}, {"n": "5.3", "t": "Bias & Validity Relationship", "concepts": [{"t": "SYSTEMATIC ERROR (BIAS)", "b": ["Systematic deviation from true value", "Affects VALIDITY (not reliability)", "A biased study can still be reproducible", "Direction is consistent (always over or under)", "Cannot be reduced by increasing sample size"]}], "hy": ["Power = 1 − β = 80%. Type II = β = 20%. 32% outside ±1 SD. These are EXAM FAVOURITES!"], "tables": [{"cap": "Complete Test Selection Matrix", "rows": [["Data Type", "2 Independent", "2 Paired", "3+ Independent", "3+ Paired"], ["Continuous (normal)", "Independent t", "Paired t", "ANOVA", "RM-ANOVA"], ["Continuous (non-normal)", "Mann-Whitney U", "Wilcoxon SR", "Kruskal-Wallis", "Friedman"], ["Categorical", "Chi-square", "McNemar", "Chi-square", "Cochran's Q"]]}, {"cap": "Key Numbers to MEMORIZE", "rows": [["Concept", "Value"], ["Type I error (α)", "5% (0.05)"], ["Type II error (β)", "20% (0.20)"], ["Power", "80% (1 - β)"], ["% OUTSIDE ±1 SD", "32%"], ["% OUTSIDE ±2 SD", "5%"], ["Cohen's d small", "0.2"], ["Cohen's d medium", "0.5"], ["Cohen's d large", "0.8"], ["Chi-square 2×2 df", "1"], ["Perfect kappa", "1"], ["Acceptable Cronbach's α", "≥ 0.7"]]}], "mcqs": [{"n": "32", "stem": "Systematic error or bias is associated with which of the following?", "opts": [["A", "It affects reliability more than validity"], ["B", "A biased study becomes less valid but could be reproduced"], ["C", "It does not change the direction of results"], ["D", "It does not affect reliability or validity"], ["E", "It always reduces both reliability and validity equally"]], "a": "B) A biased study becomes less valid but could be reproduced", "e": "Bias affects VALIDITY (accuracy) not reliability (reproducibility). A biased study gives consistently wrong results - it can be perfectly reproducible but still invalid. Bias changes results in a consistent DIRECTION."}], "simple": "Bias is a systematic push in one direction, and no amount of extra participants will fix it. Random error scatters your results around the truth; bias moves the truth itself. Internal validity is whether the answer is right for the people studied, external validity whether it applies to anybody else."}]}]}, {"p": "B", "name": "Research Methods", "sub": "Study designs, bias, confounding, validity and appraisal checklists.", "themes": [{"t": "Study Designs", "topics": [{"n": "1.1", "t": "Observational Studies", "concepts": [{"t": "CASE-CONTROL STUDY", "b": ["Starts with OUTCOME (cases vs controls), looks BACK for exposure", "RETROSPECTIVE design", "Best for RARE OUTCOMES/DISEASES", "Calculates ODDS RATIO (OR) - cannot calculate RR directly", "Quick and inexpensive", "Prone to RECALL BIAS"]}, {"t": "COHORT STUDY", "b": ["Starts with EXPOSURE, follows forward to see OUTCOME", "Can be PROSPECTIVE or RETROSPECTIVE", "Best for RARE EXPOSURES", "Can calculate RELATIVE RISK (RR) directly", "Can study MULTIPLE OUTCOMES from one exposure", "Temporal sequence is clear (exposure → outcome)"]}, {"t": "CROSS-SECTIONAL STUDY", "b": ["Measures exposure AND outcome at the SAME TIME", "Provides a 'SNAPSHOT' of the population", "Measures PREVALENCE (not incidence)", "Cannot establish TEMPORAL relationship", "Quick and inexpensive", "Good for health service planning"]}, {"t": "ECOLOGICAL STUDY", "b": ["Uses AGGREGATE (group-level) data, not individual data", "Compares populations, not individuals", "Generates hypotheses, cannot prove causation", "Subject to ECOLOGICAL FALLACY", "Example: Countries with higher fat intake have higher heart disease rates"]}], "hy": ["Case-control = starts with OUTCOME, looks back. Best for RARE DISEASES. Gives ODDS RATIO.", "Cohort = starts with EXPOSURE, follows forward. Best for RARE EXPOSURES. Gives RELATIVE RISK.", "Cross-sectional = snapshot at ONE time point. Measures PREVALENCE. Cannot show causation.", "Ecological fallacy = assuming group-level associations apply to individuals."], "tables": [{"cap": "Observational Study Comparison", "rows": [["Feature", "Case-Control", "Cohort", "Cross-Sectional"], ["Direction", "Backward (retrospective)", "Forward", "Snapshot"], ["Starts with", "Outcome (disease)", "Exposure", "Neither"], ["Best for", "Rare OUTCOMES", "Rare EXPOSURES", "Prevalence"], ["Measure", "Odds Ratio", "Relative Risk", "Prevalence ratio"], ["Temporal sequence", "Unclear", "Clear", "Cannot establish"], ["Time/Cost", "Quick, cheap", "Long, expensive", "Quick, cheap"]]}], "mcqs": [{"n": "1", "stem": "In general, the strength of case-control study design when compared to cohort studies is that:", "opts": [["A", "Multiple outcomes can be studied"], ["B", "Temporal association is clearer"], ["C", "Rare exposures can be examined"], ["D", "Rare outcomes can be examined"], ["E", "Blinded assignment is possible"]], "a": "D) Rare outcomes can be examined", "e": "Case-control studies start by selecting cases (those with the outcome) and controls (those without). This makes them ideal for studying RARE OUTCOMES - you don't need to follow thousands of people to find enough cases. Cohort studies are better for rare EXPOSURES and multiple outcomes."}, {"n": "2", "stem": "A researcher wants to study whether a rare occupational chemical exposure causes cancer. Which study design is most appropriate?", "opts": [["A", "Case-control study"], ["B", "Cross-sectional study"], ["C", "Cohort study"], ["D", "Randomized controlled trial"], ["E", "Ecological study"]], "a": "C) Cohort study", "e": "For RARE EXPOSURES, cohort studies are ideal. You identify people with and without the exposure and follow them. Case-control would require finding enough cancer cases first, which is harder for a rare exposure. You can also study multiple outcomes from the exposure."}, {"n": "3", "stem": "A study surveys 1000 adults on one day to determine how many currently have depression and how many smoke. This is:", "opts": [["A", "Cohort study"], ["B", "Case-control study"], ["C", "Cross-sectional study"], ["D", "Randomized controlled trial"], ["E", "Longitudinal study"]], "a": "C) Cross-sectional study", "e": "Both exposure (smoking) and outcome (depression) are measured at the SAME TIME - this is the defining feature of cross-sectional studies. It provides prevalence data but cannot establish which came first (temporal relationship)."}, {"n": "4", "stem": "A study finds that countries with higher chocolate consumption have more Nobel Prize winners. Concluding that eating chocolate makes individuals smarter is an example of:", "opts": [["A", "Confounding"], ["B", "Selection bias"], ["C", "Ecological fallacy"], ["D", "Recall bias"], ["E", "Publication bias"]], "a": "C) Ecological fallacy", "e": "Ecological fallacy occurs when conclusions about INDIVIDUALS are drawn from GROUP-level data. The correlation at country level does not mean individual chocolate eaters are more likely to win Nobel Prizes. There may be confounders (e.g., wealth, education systems)."}], "simple": "Three ways to watch without interfering. A snapshot of everybody at one moment is cross-sectional. Following a group forward through time is a cohort. Starting with the people who already have the disease and looking backwards is case-control. Which one you choose is decided entirely by how rare the disease is and how long it takes to appear."}, {"n": "1.2", "t": "Experimental Studies (Rcts)", "concepts": [{"t": "RANDOMISED CONTROLLED TRIAL (RCT)", "b": ["Gold standard for testing interventions", "Random allocation minimizes confounding", "Can establish CAUSATION", "Prospective design", "Highest level of evidence (after systematic reviews)", "Reported using CONSORT guidelines"]}, {"t": "TYPES OF RANDOMISATION", "b": ["SIMPLE: Like flipping a coin for each participant", "BLOCK: Ensures equal numbers in each group at regular intervals", "STRATIFIED: Randomises within subgroups (e.g., by age, sex)", "CLUSTER: Randomises groups (e.g., hospitals, schools)", "MINIMISATION: Balances important prognostic factors"]}, {"t": "PRAGMATIC vs EXPLANATORY RCTs", "b": ["EXPLANATORY (Efficacy): Does it work under IDEAL conditions?", "Strict inclusion/exclusion criteria", "Highly controlled setting", "Tests biological effect", "PRAGMATIC (Effectiveness): Does it work in REAL WORLD?", "Broad inclusion criteria", "Usual clinical settings", "Tests practical usefulness"]}, {"t": "NON-INFERIORITY & EQUIVALENCE TRIALS", "b": ["NON-INFERIORITY: New treatment is 'not worse' than standard", "One-sided hypothesis", "Uses non-inferiority margin (delta)", "EQUIVALENCE: Treatments are therapeutically equivalent", "Two-sided hypothesis", "New treatment neither better nor worse", "Both require larger samples than superiority trials"]}, {"t": "FACTORIAL DESIGN", "b": ["Tests TWO OR MORE interventions simultaneously", "Participants randomised to combinations", "Example: 2×2 factorial - Drug A, Drug B, Both, Neither", "Efficient: tests multiple questions in one trial", "Can detect INTERACTIONS between treatments"]}, {"t": "CROSSOVER DESIGN", "b": ["Same participants receive BOTH treatments sequentially", "Each participant is their own control", "Requires WASHOUT PERIOD between treatments", "More powerful (smaller sample needed)", "Risk of CARRY-OVER and PERIOD effects"]}], "hy": ["RCT = gold standard for interventions. Random allocation controls confounding.", "Pragmatic RCT = real-world effectiveness. Explanatory RCT = ideal conditions efficacy.", "Crossover = same person gets both treatments. Needs WASHOUT period. Watch for carry-over effects."], "tables": [], "mcqs": [{"n": "5", "stem": "In a trial comparing ECT electrode placements, 230 people were assigned using block randomization. This ensures:", "opts": [["A", "Participants are blinded to allocation"], ["B", "Equal numbers in groups at regular intervals"], ["C", "Allocation is based on prognostic factors"], ["D", "Whole hospitals are randomised together"], ["E", "Simple random allocation occurs"]], "a": "B) Equal numbers in groups at regular intervals", "e": "Block randomisation ensures that after every 'block' of participants, the groups are balanced. For example, in blocks of 6, after every 6 participants, there will be 3 in each group. This prevents imbalance if the trial stops early."}, {"n": "6", "stem": "Real world estimate of intervention effectiveness is studied using:", "opts": [["A", "Non-inferiority RCTs"], ["B", "Factorial RCTs"], ["C", "Equivalence trials"], ["D", "Pragmatic RCTs"], ["E", "Strictly controlled RCTs"]], "a": "D) Pragmatic RCTs", "e": "Pragmatic RCTs study natural practice EFFECTIVENESS using less strict inclusion/exclusion criteria, allowing absence of blinding or placebo control, and including patient preference. They answer: 'Does this work in the real world?'"}, {"n": "7", "stem": "In a crossover trial, a washout period is needed to:", "opts": [["A", "Blind participants to allocation"], ["B", "Prevent carry-over effects from the first treatment"], ["C", "Increase the sample size"], ["D", "Reduce attrition bias"], ["E", "Ensure random allocation"]], "a": "B) Prevent carry-over effects from the first treatment", "e": "The washout period allows the first treatment's effects to dissipate before starting the second treatment. Without adequate washout, residual effects from Treatment A could affect outcomes measured during Treatment B (carry-over effect)."}], "simple": "A randomised trial exists to answer one question: was it the treatment, or would this have happened anyway? Randomisation is the only method that balances the things you thought of and the things you did not. Everything else in the design is there to stop you fooling yourself afterwards."}]}, {"t": "Bias In Research", "topics": [{"n": "2.1", "t": "Selection & Sampling Bias", "concepts": [{"t": "SELECTION BIAS", "b": ["Systematic difference in how participants are SELECTED", "Affects EXTERNAL validity (generalisability)", "Occurs before study begins", "Example: Recruiting only from tertiary hospitals", "Reduced by: random sampling, clear inclusion criteria"]}, {"t": "RESPONSE BIAS (Volunteer Bias)", "b": ["Systematic difference between those who PARTICIPATE and those who REFUSE", "Volunteers may differ from non-volunteers", "Volunteers often healthier, more educated, more motivated", "Affects generalisability of results", "Reduced by: high response rates, incentives"]}, {"t": "ATTRITION BIAS", "b": ["Occurs due to LOSS TO FOLLOW-UP", "Participants who drop out may differ from those who remain", "Threat to INTERNAL validity", "More problematic if dropout related to outcome", "Reduced by: ITT analysis, minimising dropouts"]}], "hy": ["Selection bias = systematic errors in how study population is IDENTIFIED/SELECTED.", "Attrition bias = loss to follow-up. Use INTENTION-TO-TREAT analysis to address."], "tables": [], "mcqs": [{"n": "8", "stem": "Systematic errors that arise from the initial identification of the study population describes:", "opts": [["A", "Recall bias"], ["B", "Selection bias"], ["C", "Information bias"], ["D", "Response bias"], ["E", "Attrition bias"]], "a": "B) Selection bias", "e": "Selection bias refers to systematic differences in how cases and controls (or exposed/unexposed) are SELECTED from the population. It occurs at the initial identification stage, before data collection begins."}, {"n": "9", "stem": "A systematic difference between those accepting to participate in a study and those who refuse is called:", "opts": [["A", "Selection bias"], ["B", "Recall bias"], ["C", "Response bias"], ["D", "Information bias"], ["E", "Attrition bias"]], "a": "C) Response bias", "e": "Response bias (or volunteer bias) occurs when those who agree to participate systematically differ from those who decline. This can affect the representativeness of the sample and limit generalisability."}, {"n": "10", "stem": "This occurs due to the loss to follow-up of subjects in a study:", "opts": [["A", "Selection bias"], ["B", "Recall bias"], ["C", "Information bias"], ["D", "Response bias"], ["E", "Attrition bias"]], "a": "E) Attrition bias", "e": "Attrition bias occurs when participants are LOST during the study (after recruitment). If those lost differ systematically from those remaining (e.g., sicker patients drop out), results may be biased."}], "simple": "Selection bias is deciding who gets into your study in a way that is related to the answer. It happens before anyone is measured, it cannot be fixed by analysis afterwards, and it is the reason volunteers make such treacherous research subjects."}, {"n": "2.2", "t": "Information & Measurement Bias", "concepts": [{"t": "INFORMATION BIAS (Observation Bias)", "b": ["Systematic difference in how data is COLLECTED or MEASURED", "Affects accuracy of exposure or outcome measurement", "Can occur in any study design", "Types: recall bias, observer bias, interviewer bias", "Reduced by: blinding, standardised measures"]}, {"t": "RECALL BIAS", "b": ["Individuals with disease may REMEMBER exposures differently", "Cases often search their memory more thoroughly", "Common in CASE-CONTROL studies", "Example: Mothers of children with birth defects recall pregnancy exposures more", "Reduced by: blinding, objective records, prospective design"]}, {"t": "OBSERVER BIAS (Ascertainment Bias)", "b": ["Researcher assesses outcomes differently between groups", "Knowledge of exposure affects outcome assessment", "Can occur consciously or unconsciously", "Example: Looking harder for side effects in drug group", "Reduced by: BLINDING of outcome assessors"]}, {"t": "HAWTHORNE EFFECT", "b": ["Participants change behaviour because they know they're being OBSERVED", "Not due to intervention itself", "Can affect both intervention and control groups", "Named after Western Electric Hawthorne factory studies", "Reduced by: blinding, longer observation periods"]}], "hy": ["Recall bias = cases remember exposures differently from controls. Problem in CASE-CONTROL studies.", "Hawthorne effect = behaviour changes because of being OBSERVED, not the intervention."], "tables": [], "mcqs": [{"n": "11", "stem": "A systematic difference in the way information on exposure or outcome is obtained from subjects describes:", "opts": [["A", "Selection bias"], ["B", "Recall bias"], ["C", "Information bias"], ["D", "Response bias"], ["E", "Attrition bias"]], "a": "C) Information bias", "e": "Information bias (observation bias) is a systematic difference in how information is COLLECTED from study groups. It includes problems with measurement accuracy, data recording, or data collection methods."}, {"n": "12", "stem": "Individuals who are unwell may report suspected exposures differently from healthy cohorts. This describes:", "opts": [["A", "Selection bias"], ["B", "Recall bias"], ["C", "Information bias"], ["D", "Response bias"], ["E", "Attrition bias"]], "a": "B) Recall bias", "e": "Recall bias occurs when cases (diseased) remember or report past exposures differently from controls. Often cases search their memory more thoroughly for possible causes, leading to differential recall between groups."}, {"n": "13", "stem": "In a study of hand hygiene, infection rates dropped in all wards being observed, regardless of intervention. This is best explained by:", "opts": [["A", "Regression to mean"], ["B", "Confounding"], ["C", "Selection bias"], ["D", "Hawthorne effect"], ["E", "Information bias"]], "a": "D) Hawthorne effect", "e": "The Hawthorne effect occurs when participants modify behaviour simply because they are being observed. Here, staff improved hand hygiene because they knew they were being watched, not because of any specific intervention."}], "simple": "Once people are in the study, the second family of errors is about how you measure them. If you remember your own past differently because you are ill, that is recall bias. If the researcher knows who got the drug and looks harder for improvement, that is observer bias."}, {"n": "2.3", "t": "Other Important Biases", "concepts": [{"t": "PUBLICATION BIAS", "b": ["Studies with POSITIVE/significant results more likely published", "Negative studies often remain in 'file drawer'", "Leads to overestimation of treatment effects in meta-analyses", "Detected using FUNNEL PLOT (asymmetry suggests bias)", "Reduced by: trial registries, searching grey literature"]}, {"t": "CONFOUNDING", "b": ["Third variable associated with BOTH exposure AND outcome", "Creates spurious association or masks true association", "Must be associated with exposure (but not caused by it)", "Must be independent risk factor for outcome", "Controlled by: randomisation, matching, stratification, regression"]}], "hy": ["Publication bias = positive results published more. Detected by FUNNEL PLOT asymmetry.", "Confounder = associated with BOTH exposure AND outcome. Control by randomisation or adjustment."], "tables": [{"cap": "Summary of Major Biases", "rows": [["Bias Type", "Definition", "When It Occurs"], ["Selection", "Systematic error in choosing participants", "Recruitment"], ["Response", "Difference between participants and refusers", "Recruitment"], ["Attrition", "Loss to follow-up", "During study"], ["Information", "Error in data collection", "Data collection"], ["Recall", "Differential memory of exposures", "Case-control studies"], ["Observer", "Assessor influenced by knowledge", "Outcome assessment"], ["Hawthorne", "Behaviour change from being observed", "Any observation"], ["Publication", "Positive results published more", "After study"]]}], "mcqs": [{"n": "14", "stem": "Which method is most useful to assess publication bias in a meta-analysis?", "opts": [["A", "Chi-square test"], ["B", "Forest plot"], ["C", "Funnel plot"], ["D", "Kaplan-Meier curve"], ["E", "ROC curve"]], "a": "C) Funnel plot", "e": "A funnel plot graphs effect size against study precision (often SE). Small studies should scatter widely at the bottom, large studies cluster at the top. Asymmetry suggests publication bias - small negative studies are 'missing'."}, {"n": "15", "stem": "A study finds coffee drinking is associated with lung cancer. However, coffee drinkers are more likely to smoke. In this case, smoking is a:", "opts": [["A", "Mediator"], ["B", "Effect modifier"], ["C", "Confounder"], ["D", "Collider"], ["E", "Instrumental variable"]], "a": "C) Confounder", "e": "Smoking is a confounder because it is associated with BOTH coffee drinking (exposure) AND lung cancer (outcome). It creates a spurious association between coffee and cancer. Adjusting for smoking would remove this confounding."}], "simple": "A handful of biases have names because they turn up constantly and because they explain results that otherwise look like miracles. Lead-time bias makes screening look life-saving when it has only moved the diagnosis earlier. Berkson's bias explains why everything looks associated with everything else in hospital data."}]}, {"t": "Qualitative Research", "topics": [{"n": "3.1", "t": "Qualitative Methods", "concepts": [{"t": "WHEN TO USE QUALITATIVE RESEARCH", "b": ["Exploring EXPERIENCES, FEELINGS, and PERCEPTIONS", "Understanding the 'WHY' and 'HOW'", "Generating hypotheses (not testing them)", "Studying complex social phenomena", "When numerical data cannot capture the concept"]}, {"t": "GROUNDED THEORY", "b": ["Theory EMERGES from the data (not preconceived)", "Constant comparison of data during collection", "ITERATIVE process: collect, analyse, collect more", "Categories and concepts generated inductively", "Developed by Glaser and Strauss"]}, {"t": "THEORETICAL SATURATION", "b": ["Point when NO NEW THEMES emerge from data", "Determines when to STOP data collection", "Not about sample size, but information completeness", "New data adds nothing new to emerging theory", "Key concept in grounded theory and thematic analysis"]}], "hy": ["Grounded theory = theory derived FROM THE DATA, not prior theory. Iterative analysis.", "Theoretical saturation = no new themes emerge. This determines when to STOP collecting data."], "tables": [], "mcqs": [{"n": "16", "stem": "Which of the following is BEST suited for qualitative research?", "opts": [["A", "A study to measure incidence of schizophrenia"], ["B", "A study to measure quality of life in Alzheimer's disease"], ["C", "A study to assess attitudes of people with BPD to their diagnosis"], ["D", "A study to measure psychiatric symptoms after head injury"], ["E", "A study to compare two antidepressants"]], "a": "C) A study to assess attitudes of people with BPD to their diagnosis", "e": "Qualitative research explores feelings, values, perceptions, and experiences. Assessing 'attitudes' requires understanding subjective experiences - perfect for qualitative methods. Measuring incidence, symptoms, or comparing treatments needs quantitative approaches."}, {"n": "17", "stem": "The principle of deriving explanations or theories from the dataset itself rather than from a researcher's prior theoretical viewpoint is called:", "opts": [["A", "Multiple coding"], ["B", "Purposive sampling"], ["C", "Grounded Theory"], ["D", "Triangulation"], ["E", "Respondent validation"]], "a": "C) Grounded Theory", "e": "Grounded theory uses empirical data WITHOUT preconceived theories. The researcher collects data, analyses it, and allows theory to EMERGE from patterns in the data. It involves constant comparison and iterative analysis alongside data collection."}, {"n": "18", "stem": "In qualitative research, thematic analysis continues until data saturation is reached. This means:", "opts": [["A", "Data was coded and sent back to participants"], ["B", "All the data was used to inform results"], ["C", "Data collected until number of themes needed was reached"], ["D", "Data was coded by more than one researcher"], ["E", "Data was collected until no further themes were generated"]], "a": "E) Data was collected until no further themes were generated", "e": "Theoretical saturation is reached when additional data collection yields NO NEW THEMES or categories. It's the point of 'information redundancy' - you keep hearing the same things. This, not a predetermined number, determines sample size."}], "simple": "Numbers tell you how many and how much. They cannot tell you why a person stopped taking their tablets. Qualitative research answers that question, and it has its own rules, its own vocabulary and its own quality standards, which is exactly why it is examined."}, {"n": "3.2", "t": "Sampling In Qualitative Research", "concepts": [{"t": "PURPOSIVE SAMPLING", "b": ["Participants selected according to SPECIFIC CRITERIA", "NOT random - deliberately chosen for characteristics", "Seeks diversity of perspectives or specific experiences", "Sample size determined by saturation, not statistics", "Common in qualitative research"]}, {"t": "OTHER SAMPLING METHODS", "b": ["CONVENIENCE: Easiest to access (prone to bias)", "SNOWBALL: Participants recruit other participants", "QUOTA: Fill predetermined categories", "THEORETICAL: Guided by emerging theory (grounded theory)"]}, {"t": "SAMPLING HIERARCHY (Terms)", "b": ["TARGET POPULATION: Who results apply to", "SAMPLING FRAME: List of all eligible participants", "STUDY SAMPLE: Actual participants in study", "SAMPLING UNIT: The basic unit (e.g., one person)", "SAMPLE STRATUM: Subgroup within sampling frame"]}], "hy": ["Purposive sampling = deliberate selection based on criteria relevant to research question."], "tables": [], "mcqs": [{"n": "19", "stem": "A researcher studying experiences of first-episode psychosis selects participants to include different ages, genders, and treatment settings. This is:", "opts": [["A", "Random sampling"], ["B", "Convenience sampling"], ["C", "Purposive sampling"], ["D", "Snowball sampling"], ["E", "Stratified sampling"]], "a": "C) Purposive sampling", "e": "The researcher is DELIBERATELY selecting participants based on specific criteria (age, gender, setting) to achieve diversity. This is purposive sampling - selecting cases that will provide relevant and diverse perspectives on the research question."}, {"n": "20", "stem": "In a clinical study, all patients who visited a clinic on certain days were recruited. This is:", "opts": [["A", "Random sampling"], ["B", "Systematic sampling"], ["C", "Convenience sampling"], ["D", "Purposive sampling"], ["E", "Stratified sampling"]], "a": "C) Convenience sampling", "e": "Convenience sampling selects participants based on ease of access - whoever is available. Recruiting all patients on certain clinic days is convenient but may not be representative. It's prone to selection bias."}, {"n": "21", "stem": "In terms of size, the smallest unit when considering research sampling is:", "opts": [["A", "Sampling frame"], ["B", "Sample stratum"], ["C", "Study sample"], ["D", "Target population"], ["E", "Sampling unit"]], "a": "E) Sampling unit", "e": "The sampling unit is the BASIC unit (e.g., an individual person). It's the smallest unit. In order of size: Sampling unit < Study sample < Sample stratum < Sampling frame < Target population."}], "simple": "Qualitative sampling is not trying to be representative, so counting participants misses the point. You choose people deliberately because they have something to say, and you stop when new interviews stop telling you anything new. That stopping point has a name: saturation."}, {"n": "3.3", "t": "Ensuring Quality In Qualitative Research", "concepts": [{"t": "TRIANGULATION", "b": ["Using TWO OR MORE methods/sources to cross-check findings", "Increases CREDIBILITY and VALIDITY", "Types: data, investigator, method, theory triangulation", "Example: interviews + focus groups + documents", "Convergence of findings strengthens conclusions"]}, {"t": "MULTIPLE CODING", "b": ["Same data coded by MORE THAN ONE researcher", "Addresses INTER-RATER RELIABILITY in qualitative research", "Reduces subjectivity in interpretation", "Discrepancies discussed and resolved", "Equivalent to inter-rater reliability in quantitative research"]}, {"t": "RESPONDENT VALIDATION (Member Checking)", "b": ["Returning findings to PARTICIPANTS for verification", "Participants confirm accuracy of interpretation", "Increases credibility of findings", "May reveal misunderstandings or new insights", "Also called 'member checking'"]}, {"t": "REFLEXIVITY", "b": ["Researcher awareness of their own influence", "Acknowledging biases, assumptions, and position", "Documented in reflexive journal/diary", "Important in qualitative research", "Addresses subjectivity of interpretation"]}], "hy": ["Triangulation = using multiple methods/sources to verify findings. Increases VALIDITY.", "Multiple coding = >1 researcher codes data. Qualitative equivalent of inter-rater reliability."], "tables": [], "mcqs": [{"n": "22", "stem": "In qualitative research, the issue of internal validity is addressed by using two or more methods of data collection. This process is called:", "opts": [["A", "Triangulation"], ["B", "Multiple coding"], ["C", "Grounded Theory"], ["D", "Respondent validation"], ["E", "Purposive sampling"]], "a": "A) Triangulation", "e": "Triangulation uses multiple methods, data sources, or investigators to cross-verify findings. It increases credibility and validity by showing that conclusions are not an artifact of one particular method."}, {"n": "23", "stem": "Multiple coding can be used in qualitative research to address the issue of:", "opts": [["A", "Test-retest reliability"], ["B", "External validity"], ["C", "Inter-rater reliability"], ["D", "Internal validity"], ["E", "Type 1 error"]], "a": "C) Inter-rater reliability", "e": "Multiple coding involves independent researchers coding the same data. It addresses the qualitative equivalent of 'inter-rater reliability' - ensuring that coding and interpretation is not overly subjective or dependent on one researcher's perspective."}], "simple": "Qualitative work is not exempt from rigour, it just uses different words for it. Triangulation, member checking, reflexivity and an audit trail are the qualitative equivalents of the things a trial does to stop the researcher from finding what they hoped to find."}, {"n": "3.4", "t": "Qualitative Data Analysis Methods", "concepts": [{"t": "THEMATIC ANALYSIS", "b": ["Identifying THEMES and PATTERNS in data", "Most common qualitative analysis method", "Can be inductive (data-driven) or deductive (theory-driven)", "Flexible approach applicable to various questions", "Themes developed through coding process"]}, {"t": "CONTENT ANALYSIS", "b": ["Systematic analysis of TEXT or MEDIA content", "Can be quantitative (counting) or qualitative", "Categories determined before or during analysis", "Often used for documents, media, communications", "Example: Analysing newspaper articles about mental health"]}, {"t": "RECURSIVE ABSTRACTION", "b": ["Summarising datasets REPEATEDLY", "Initial summaries are further summarised", "Progressive distillation of data", "End result: compact, distilled summary", "Risk: final conclusions far removed from original data"]}, {"t": "FOCUS GROUPS", "b": ["Group interview exploring shared experiences/views", "Typically 6-12 participants", "Facilitator guides discussion", "Participants may build on each other's ideas", "Groups often kept HOMOGENEOUS for free expression"]}], "hy": [], "tables": [], "mcqs": [{"n": "24", "stem": "A researcher collects published news from British tabloids containing 'mental health' and analyses patterns of reporting. This is:", "opts": [["A", "Content Analysis"], ["B", "Discourse Analysis"], ["C", "Textual Scrutiny"], ["D", "Information Scrutiny"], ["E", "Lexical Examination"]], "a": "A) Content Analysis", "e": "Content analysis systematically examines textual or visual data to uncover patterns and themes. Collecting and analysing media articles for specific content (mental health reporting patterns) is a classic content analysis approach."}, {"n": "25", "stem": "In qualitative research, the term recursive abstraction relates to:", "opts": [["A", "Iterative generation of theories"], ["B", "Criticising the summarized results"], ["C", "Researcher being aware of their role"], ["D", "Summarising datasets repeatedly"], ["E", "Validating using a third data type"]], "a": "D) Summarising datasets repeatedly", "e": "Recursive abstraction involves repeatedly summarising data - the initial summaries are then summarised again, creating progressively more distilled and compact summaries. A disadvantage is that final conclusions may be far removed from original data."}, {"n": "26", "stem": "In a study of dementia night-time care, focus groups for care staff and family carers were conducted separately. The most likely reason is:", "opts": [["A", "To complete the study within time"], ["B", "To allow thematic analysis"], ["C", "To avoid conflicts among participants"], ["D", "To reduce interview costs"], ["E", "To allow participants to freely express themselves"]], "a": "E) To allow participants to freely express themselves", "e": "Focus groups work best when participants feel comfortable expressing views. Separating staff and family carers creates homogeneous groups where participants share similar perspectives and can speak freely without concern about how 'the other side' might react."}], "simple": "Once you have hours of transcript, something has to turn it into findings. Different analytic methods make different promises: content analysis counts, thematic analysis patterns, grounded theory builds a theory from the ground up."}]}, {"t": "Trial Methodology", "topics": [{"n": "4.1", "t": "Blinding", "concepts": [{"t": "LEVELS OF BLINDING", "b": ["SINGLE-BLIND: Participants don't know allocation", "DOUBLE-BLIND: Participants AND researchers don't know", "TRIPLE-BLIND: Participants, researchers, AND analysts don't know", "OPEN-LABEL: Everyone knows allocation", "Blinding reduces performance and detection bias"]}], "hy": ["Double-blind = participants AND researchers blinded. Reduces bias in assessment."], "tables": [], "mcqs": [{"n": "27", "stem": "In a trial of psychotherapy vs medication, blinding of participants is:", "opts": [["A", "Essential for validity"], ["B", "Easily achieved with placebos"], ["C", "Often impossible due to nature of intervention"], ["D", "Not relevant in behavioural trials"], ["E", "Required by ethics committees"]], "a": "C) Often impossible due to nature of intervention", "e": "Blinding is often impossible in trials of psychotherapy, surgery, or other complex interventions where participants obviously know what they're receiving. This is a limitation that should be acknowledged, and outcome assessors should be blinded where possible."}], "simple": "Blinding stops expectation from becoming a result. It protects against the patient feeling better because they know, the clinician managing them differently because they know, and the assessor reading the outcome generously because they know. Three different people, three different protections."}, {"n": "4.2", "t": "Intention-To-Treat Analysis", "concepts": [{"t": "INTENTION-TO-TREAT (ITT) ANALYSIS", "b": ["Analyse participants in ORIGINALLY ASSIGNED groups", "Includes ALL randomised participants regardless of compliance", "Preserves benefits of randomisation", "Reduces attrition bias", "More CONSERVATIVE estimate of treatment effect", "Reflects real-world effectiveness"]}, {"t": "PER-PROTOCOL ANALYSIS", "b": ["Analyses only those who COMPLETED treatment as planned", "Excludes non-compliant, crossovers, dropouts", "May overestimate treatment effect", "Useful for understanding efficacy (ideal conditions)", "Loses benefits of randomisation"]}], "hy": ["ITT = analyse as RANDOMISED, regardless of what they actually received. Preserves randomisation.", "Per-protocol = only those who completed as planned. May OVERESTIMATE effect."], "tables": [], "mcqs": [{"n": "28", "stem": "A patient randomised to drug treatment stops taking the drug but remains in the study. In ITT analysis, they are analysed in:", "opts": [["A", "The placebo group"], ["B", "A separate 'non-compliant' group"], ["C", "The drug group (as originally randomised)"], ["D", "Neither group - they are excluded"], ["E", "Depends on why they stopped"]], "a": "C) The drug group (as originally randomised)", "e": "ITT analysis keeps participants in their ORIGINALLY ASSIGNED groups regardless of compliance, crossover, or dropout. This preserves the benefits of randomisation and provides a conservative, real-world estimate of effectiveness."}, {"n": "29", "stem": "Compared to intention-to-treat analysis, per-protocol analysis:", "opts": [["A", "Is more conservative"], ["B", "Preserves randomisation better"], ["C", "May overestimate treatment effect"], ["D", "Includes all randomised participants"], ["E", "Is preferred in superiority trials"]], "a": "C) May overestimate treatment effect", "e": "Per-protocol analysis excludes non-compliant participants, who often have poorer outcomes. This can make the treatment look MORE effective than it really is (overestimation). ITT is more conservative and realistic."}], "simple": "Intention to treat means you analyse people in the group they were randomised to, whatever they actually did. It feels wrong and it is right, because the moment you start excluding people who did not comply, you have thrown away the randomisation you built the whole trial on."}, {"n": "4.3", "t": "Handling Missing Data", "concepts": [{"t": "LAST OBSERVATION CARRIED FORWARD (LOCF)", "b": ["Uses last available measurement for missing data", "Assumes no change after dropout", "Simple but often BIASED", "May underestimate treatment effect if improving", "May overestimate if deteriorating", "Largely REPLACED by multiple imputation"]}, {"t": "MULTIPLE IMPUTATION", "b": ["Creates several PLAUSIBLE values for missing data", "Based on other observed variables", "Analyses repeated with each imputed dataset", "Results pooled using Rubin's rules", "Preferred method for handling missing data"]}], "hy": ["LOCF = carry last value forward. Simple but BIASED. Multiple imputation preferred."], "tables": [], "mcqs": [], "simple": "Somebody always drops out. What you do about their missing data can change the answer entirely, and the different methods make different assumptions about why they left. Carrying the last value forward is the crudest and is now discouraged."}, {"n": "4.4", "t": "Reporting Guidelines", "concepts": [{"t": "REPORTING GUIDELINES", "b": ["CONSORT: Randomised Controlled Trials", "STROBE: Observational Studies (cohort, case-control, cross-sectional)", "PRISMA: Systematic Reviews and Meta-analyses", "COREQ: Qualitative Research", "STARD: Diagnostic Accuracy Studies"]}], "hy": ["CONSORT = RCTs. STROBE = observational. PRISMA = systematic reviews. COREQ = qualitative."], "tables": [], "mcqs": [{"n": "30", "stem": "The flow diagram showing participant progression through a trial (enrollment, allocation, follow-up, analysis) is part of which guideline?", "opts": [["A", "STROBE"], ["B", "PRISMA"], ["C", "CONSORT"], ["D", "COREQ"], ["E", "STARD"]], "a": "C) CONSORT", "e": "The CONSORT flow diagram is essential for reporting RCTs. It shows how participants moved through the trial: enrollment, allocation to groups, follow-up, and final analysis. It helps assess risk of bias and generalisability."}, {"n": "31", "stem": "In what type of study would you normally use this flow diagram? [Showing enrollment → randomisation → allocation → follow-up → analysis]", "opts": [["A", "Systematic review"], ["B", "Randomised controlled trial"], ["C", "Meta-analysis"], ["D", "Qualitative study"], ["E", "Uncontrolled trial"]], "a": "B) Randomised controlled trial", "e": "The CONSORT flow diagram showing enrollment, randomisation, allocation, follow-up, and analysis is the standard for reporting RCTs. It is essential to assess generalisability and validity of results."}], "simple": "Reporting guidelines exist because studies were being described so badly that readers could not judge them. CONSORT for trials, PRISMA for systematic reviews, STROBE for observational studies, STARD for diagnostic accuracy. Learn which letter goes with which design."}]}, {"t": "Evidence Hierarchy & Causation", "topics": [{"n": "5.1", "t": "Hierarchy Of Evidence", "concepts": [{"t": "LEVELS OF EVIDENCE (Oxford Centre)", "b": ["Level I: Systematic review of RCTs", "Level II: Individual RCT", "Level III-1: Pseudo-randomised controlled trial", "Level III-2: Cohort studies, case-control studies", "Level III-3: Comparative studies with historical control", "Level IV: Case series", "Level V: Expert opinion"]}], "hy": ["Systematic review of RCTs = Level I (highest). Expert opinion = Level V (lowest)."], "tables": [], "mcqs": [{"n": "32", "stem": "In the traditional hierarchy of evidence in EBM, which can surpass RCTs?", "opts": [["A", "None of the above"], ["B", "Prospective cohort studies"], ["C", "Case-control studies"], ["D", "Animal experiments"], ["E", "Systematic review supported by meta-analysis"]], "a": "E) Systematic review supported by meta-analysis", "e": "Systematic reviews with meta-analysis form the HIGHEST level of evidence, above single RCTs. They synthesise multiple RCTs, increasing power and generalisability, and reduce random error through pooling."}, {"n": "33", "stem": "The grade conferred to expert consensus statements in the hierarchy of evidence is:", "opts": [["A", "Grade I"], ["B", "Grade III"], ["C", "Grade V"], ["D", "Grade II"], ["E", "Grade IV"]], "a": "C) Grade V", "e": "Expert opinion (without critical appraisal or based on physiology/bench research) is Grade V - the LOWEST level of evidence. It's still useful when higher levels are unavailable, but should be interpreted cautiously."}], "simple": "The hierarchy of evidence ranks designs by how well they protect you from being fooled. It is genuinely useful and frequently misused: a bad randomised trial is worse than a good cohort study, and the right design depends on the question being asked."}, {"n": "5.2", "t": "Causation", "concepts": [{"t": "BRADFORD HILL CRITERIA FOR CAUSATION", "b": ["STRENGTH: Strong associations more likely causal", "CONSISTENCY: Repeated in different settings/populations", "SPECIFICITY: Specific exposure → specific outcome", "TEMPORALITY: Cause MUST precede effect (only essential criterion)", "BIOLOGICAL GRADIENT: Dose-response relationship", "PLAUSIBILITY: Biologically plausible mechanism", "COHERENCE: Consistent with known facts", "EXPERIMENT: Removal of cause reduces outcome", "ANALOGY: Similar exposures cause similar outcomes"]}], "hy": ["TEMPORALITY is the ONLY essential criterion - cause must come before effect."], "tables": [], "mcqs": [{"n": "34", "stem": "Of the Bradford Hill criteria, which is the ONLY essential criterion for causation?", "opts": [["A", "Strength of association"], ["B", "Biological plausibility"], ["C", "Temporality"], ["D", "Consistency"], ["E", "Dose-response relationship"]], "a": "C) Temporality", "e": "Temporality - that the cause PRECEDES the effect - is the ONLY essential (necessary) criterion. Without temporal sequence, causation is impossible. Other criteria support causality but are not absolutely required."}], "simple": "Association is two things happening together. Causation is one making the other happen. Bradford Hill set out the considerations that let you argue from the first to the second, and they are considerations rather than criteria, which is a distinction worth keeping."}, {"n": "5.3", "t": "Association Vs Causation", "concepts": [{"t": "WHY ASSOCIATION ≠ CAUSATION", "b": ["CONFOUNDING: Third variable causes both", "REVERSE CAUSATION: Outcome causes exposure", "CHANCE: Random statistical fluctuation", "BIAS: Systematic error in study", "Only RCTs can establish causation (experimental manipulation)"]}], "hy": ["Case-control = rare OUTCOMES (OR). Cohort = rare EXPOSURES (RR). Cross-sectional = PREVALENCE."], "tables": [{"cap": "Study Design Selection", "rows": [["Research Question", "Best Study Design"], ["Does treatment work?", "RCT (experimental)"], ["Rare disease risk factors?", "Case-control"], ["Rare exposure outcomes?", "Cohort"], ["Disease prevalence?", "Cross-sectional"], ["Patient experiences?", "Qualitative"], ["Summarise all evidence?", "Systematic review"]]}, {"cap": "Bias Recognition Quick Guide", "rows": [["Clue in Question", "Likely Bias"], ["'Participants who dropped out...'", "Attrition bias"], ["'Cases remembered exposures...'", "Recall bias"], ["'Those who agreed to participate...'", "Response bias"], ["'How participants were selected...'", "Selection bias"], ["'Researchers knew allocation...'", "Observer bias"], ["'Behaviour changed when observed...'", "Hawthorne effect"], ["'Positive studies more likely published...'", "Publication bias"]]}, {"cap": "Qualitative Methods Summary", "rows": [["Term", "Meaning"], ["Grounded theory", "Theory emerges FROM data"], ["Theoretical saturation", "No NEW themes emerging"], ["Purposive sampling", "Deliberate selection by criteria"], ["Triangulation", "Multiple methods verify findings"], ["Multiple coding", ">1 researcher codes data"], ["Respondent validation", "Return findings to participants"], ["Reflexivity", "Researcher self-awareness"]]}], "mcqs": [{"n": "35", "stem": "A cross-sectional observation with no randomisation cannot establish causality because:", "opts": [["A", "It lacks sufficient power"], ["B", "Biological investigations haven't been conducted"], ["C", "Data is heterogeneous"], ["D", "It is not prospective so temporal association cannot be made"], ["E", "Confounders are not controlled"]], "a": "D) It is not prospective so temporal association cannot be made", "e": "Cross-sectional studies measure exposure and outcome at the SAME TIME. Without prospective follow-up, you cannot establish which came first (temporal sequence), making causation impossible to determine. Temporality is essential for causation."}], "simple": "Before concluding that A caused B, three impostors have to be excluded: chance, bias and confounding. A confounder is a third thing causing both. Coffee looks like it causes lung cancer until you notice that coffee drinkers smoke."}]}]}, {"p": "C", "name": "Evidence-Based Medicine", "sub": "Diagnostic accuracy, treatment effect, screening and the 2x2 table.", "themes": [{"t": "Disease Frequency", "topics": [{"n": "1.1", "t": "Incidence & Prevalence", "concepts": [{"t": "INCIDENCE", "b": ["Number of NEW cases in a defined TIME PERIOD", "Measures RISK of developing disease", "Requires FOLLOW-UP of disease-free population", "Usually expressed per 1000 or 100,000 per year", "Incidence Rate = New cases / Person-time at risk"]}, {"t": "PREVALENCE", "b": ["Number of EXISTING cases at a specific time", "Measures BURDEN of disease", "POINT prevalence: at one moment", "PERIOD prevalence: during a time period", "LIFETIME prevalence: ever had the condition", "Prevalence = Incidence × Duration"]}], "hy": ["Incidence = NEW cases over TIME. Measures RISK. Requires follow-up.", "Prevalence = EXISTING cases. Affected by INCIDENCE and DURATION of disease."], "tables": [{"cap": "Incidence vs Prevalence", "rows": [["Feature", "Incidence", "Prevalence"], ["What it measures", "NEW cases", "EXISTING cases"], ["Time element", "Over a period", "At a point/period"], ["Concept", "Risk", "Burden"], ["Numerator", "New cases only", "All cases (new + old)"], ["Affected by", "Risk factors", "Incidence × Duration"]]}], "mcqs": [{"n": "1", "stem": "The number of new cases during a given time interval, usually one year, is called:", "opts": [["A", "Lifetime prevalence"], ["B", "Attack rate"], ["C", "Incidence"], ["D", "Period prevalence"], ["E", "Point prevalence"]], "a": "C) Incidence", "e": "Incidence refers to NEW cases occurring during a specified time period. It measures the rate at which new cases develop. Prevalence measures existing cases at a point or period in time."}, {"n": "2", "stem": "Point prevalence refers to:", "opts": [["A", "Cases developing during a month"], ["B", "Cases existing at a specific point in time"], ["C", "Cases over a lifetime"], ["D", "New cases each year"], ["E", "Cases in a defined geographic area"]], "a": "B) Cases existing at a specific point in time", "e": "Point prevalence is the proportion of people who HAVE a disease at a specific point in time (a 'snapshot'). It includes both new and pre-existing cases alive at that moment."}, {"n": "3", "stem": "Which of the following INCREASES prevalence?", "opts": [["A", "Shorter disease duration"], ["B", "Higher mortality rate"], ["C", "Better treatment leading to longer survival"], ["D", "Lower incidence"], ["E", "Higher cure rate"]], "a": "C) Better treatment leading to longer survival", "e": "Prevalence = Incidence × Duration. Better treatment increases survival (duration) without necessarily reducing incidence, thus INCREASING prevalence. Higher mortality, shorter duration, and cures all DECREASE prevalence."}], "simple": "Incidence is how fast new cases are arriving. Prevalence is how many people are living with it right now. A treatment that keeps people alive without curing them raises prevalence and leaves incidence untouched, and that is not a failure."}]}, {"t": "Diagnostic Test Accuracy", "topics": [{"n": "2.1", "t": "The 2×2 Table", "concepts": [{"t": "KEY DEFINITIONS FROM 2×2 TABLE", "b": ["TP (True Positive): Test +, Disease + (correctly identified)", "FP (False Positive): Test +, Disease − (false alarm)", "FN (False Negative): Test −, Disease + (missed case)", "TN (True Negative): Test −, Disease − (correctly excluded)"]}], "hy": ["TP and TN are CORRECT. FP and FN are ERRORS. FN = missed disease (dangerous!)."], "tables": [{"cap": "THE 2×2 DIAGNOSTIC TABLE", "rows": [["", "", "DISEASE (Gold Standard)", "DISEASE (Gold Standard)"], ["", "", "Present (+)", "Absent (−)"], ["TEST", "Positive (+)", "TP (a)", "FP (b)"], ["TEST", "Negative (−)", "FN (c)", "TN (d)"]]}], "mcqs": [], "simple": "Almost every number in diagnostic testing comes out of one small table with four boxes in it. Learn to draw that table from memory, put the disease across the top and the test down the side, and you can derive everything else in the exam without memorising a single formula."}, {"n": "2.2", "t": "Sensitivity & Specificity", "concepts": [{"t": "SENSITIVITY (True Positive Rate)", "b": ["Proportion of DISEASED correctly identified as positive", "Sensitivity = TP / (TP + FN) = TP / All Diseased", "Answers: 'If disease present, will test detect it?'", "High sensitivity = few FALSE NEGATIVES (misses)", "Good for RULING OUT disease (SnNOut)", "Use when missing disease is dangerous"]}, {"t": "SPECIFICITY (True Negative Rate)", "b": ["Proportion of NON-DISEASED correctly identified as negative", "Specificity = TN / (TN + FP) = TN / All Non-Diseased", "Answers: 'If disease absent, will test be negative?'", "High specificity = few FALSE POSITIVES", "Good for RULING IN disease (SpPIn)", "Use when false positives are harmful"]}], "hy": ["Sensitivity = TP/(TP+FN). High Sens = few FN. SnNOut = Sensitive test, Negative result rules OUT.", "Specificity = TN/(TN+FP). High Spec = few FP. SpPIn = Specific test, Positive result rules IN."], "tables": [{"cap": "Sensitivity vs Specificity", "rows": [["Property", "Sensitivity", "Specificity"], ["What it measures", "Detection of disease", "Exclusion of disease"], ["Formula", "TP / (TP + FN)", "TN / (TN + FP)"], ["High value means", "Few false negatives", "Few false positives"], ["Clinical use", "Screening (rule OUT)", "Confirmation (rule IN)"], ["Mnemonic", "SnNOut", "SpPIn"], ["Affected by prevalence?", "NO", "NO"]]}], "mcqs": [{"n": "4", "stem": "A screening test has sensitivity of 95%. This means:", "opts": [["A", "95% of test positives truly have the disease"], ["B", "95% of people with disease will test positive"], ["C", "95% of people without disease will test negative"], ["D", "5% of test negatives are false negatives"], ["E", "The test is positive in 95% of all people tested"]], "a": "B) 95% of people with disease will test positive", "e": "Sensitivity is the proportion of people WITH disease who test POSITIVE. 95% sensitivity means 95 out of 100 diseased people will be correctly identified. The remaining 5% are false negatives (missed)."}, {"n": "5", "stem": "A confirmatory test for HIV has specificity of 99.9%. This means:", "opts": [["A", "99.9% of positive results are true positives"], ["B", "99.9% of people tested will be negative"], ["C", "99.9% of people WITHOUT HIV will test negative"], ["D", "Only 0.1% of people have HIV"], ["E", "The test detects 99.9% of HIV cases"]], "a": "C) 99.9% of people WITHOUT HIV will test negative", "e": "Specificity is the proportion of people WITHOUT disease who test NEGATIVE. 99.9% specificity means 999 out of 1000 non-HIV people will correctly test negative. Only 0.1% will be false positives."}, {"n": "6", "stem": "SnNOut means:", "opts": [["A", "Specific test with positive result rules out disease"], ["B", "Sensitive test with negative result rules out disease"], ["C", "Sensitive test with positive result rules in disease"], ["D", "Specific test with negative result rules in disease"], ["E", "High sensitivity increases positive predictive value"]], "a": "B) Sensitive test with negative result rules out disease", "e": "SnNOut = Sensitivity, Negative, rules OUT. A highly SENSITIVE test has few false negatives, so a NEGATIVE result reliably excludes disease. SpPIn = Specific test, Positive result rules IN disease."}], "simple": "Sensitivity and specificity are properties of the test. Sensitivity is how good it is at catching the people who have the disease. Specificity is how good it is at clearing the people who do not. A highly sensitive test, when negative, rules out; a highly specific test, when positive, rules in."}, {"n": "2.3", "t": "Predictive Values", "concepts": [{"t": "POSITIVE PREDICTIVE VALUE (PPV)", "b": ["Probability of DISEASE given a POSITIVE test", "PPV = TP / (TP + FP) = TP / All Test Positives", "Answers: 'If test positive, do I have disease?'", "INCREASES with higher PREVALENCE", "Clinically most relevant for patient counseling"]}, {"t": "NEGATIVE PREDICTIVE VALUE (NPV)", "b": ["Probability of NO DISEASE given a NEGATIVE test", "NPV = TN / (TN + FN) = TN / All Test Negatives", "Answers: 'If test negative, can I be sure I'm disease-free?'", "DECREASES with higher PREVALENCE", "Important for reassuring patients with negative results"]}], "hy": ["PPV = probability of disease IF test is positive. INCREASES with prevalence.", "NPV = probability of NO disease IF test negative. DECREASES with higher prevalence."], "tables": [{"cap": "Effect of Prevalence on Predictive Values", "rows": [["Prevalence", "PPV", "NPV", "Clinical Implication"], ["Low (1%)", "LOW", "HIGH", "Many false positives, negatives reassuring"], ["Medium (10%)", "Moderate", "Moderate", "Balanced interpretation"], ["High (50%)", "HIGH", "LOW", "Positives reliable, negatives may miss disease"]]}], "mcqs": [{"n": "7", "stem": "A test with 90% sensitivity and 90% specificity is used in two populations. Population A has 50% prevalence, Population B has 1% prevalence. The PPV will be:", "opts": [["A", "Higher in Population B"], ["B", "Higher in Population A"], ["C", "The same in both populations"], ["D", "90% in both populations"], ["E", "Cannot be determined"]], "a": "B) Higher in Population A", "e": "PPV increases with prevalence. In Population A (50% prevalence), most positive tests are true positives. In Population B (1% prevalence), most positive tests are false positives despite high specificity. This is why screening in low prevalence populations yields many false positives."}, {"n": "8", "stem": "Which statement about predictive values is TRUE?", "opts": [["A", "PPV and NPV are independent of prevalence"], ["B", "PPV increases and NPV decreases as prevalence increases"], ["C", "PPV decreases and NPV increases as prevalence increases"], ["D", "Both PPV and NPV increase with prevalence"], ["E", "PPV depends only on sensitivity"]], "a": "B) PPV increases and NPV decreases as prevalence increases", "e": "As prevalence increases: more true positives → higher PPV; more false negatives → lower NPV. In rare diseases (low prevalence), even specific tests give many false positives (low PPV), but negative results are very reliable (high NPV)."}], "simple": "Sensitivity answers a question the patient never asked. What they want to know is: my test is positive, do I have it? That is predictive value, and unlike sensitivity it depends entirely on how common the disease is in the population being tested."}]}, {"t": "Likelihood Ratios", "topics": [{"n": "3.1", "t": "Likelihood Ratios", "concepts": [{"t": "POSITIVE LIKELIHOOD RATIO (LR+)", "b": ["How much MORE likely is a positive result in diseased vs non-diseased?", "LR+ = Sensitivity / (1 − Specificity)", "LR+ = True positive rate / False positive rate", "LR+ > 10: Large increase in probability of disease", "LR+ > 1: Positive test increases disease probability", "NOT affected by prevalence"]}, {"t": "NEGATIVE LIKELIHOOD RATIO (LR−)", "b": ["How much LESS likely is a negative result in diseased vs non-diseased?", "LR− = (1 − Sensitivity) / Specificity", "LR− = False negative rate / True negative rate", "LR− < 0.1: Large decrease in probability of disease", "LR− < 1: Negative test decreases disease probability", "NOT affected by prevalence"]}], "hy": ["LR+ = Sens / (1-Spec). Higher LR+ = positive test more useful for ruling IN disease.", "LR− = (1-Sens) / Spec. Lower LR− = negative test more useful for ruling OUT disease."], "tables": [{"cap": "Likelihood Ratio Interpretation", "rows": [["LR+ Value", "LR− Value", "Effect on Probability"], ["> 10", "< 0.1", "Large change (conclusive)"], ["5 - 10", "0.1 - 0.2", "Moderate change"], ["2 - 5", "0.2 - 0.5", "Small change"], ["1 - 2", "0.5 - 1", "Minimal change"], ["= 1", "= 1", "No change (useless test)"]]}], "mcqs": [{"n": "9", "stem": "A test has sensitivity 80% and specificity 80%. Calculate the positive likelihood ratio:", "opts": [["A", "1"], ["B", "2"], ["C", "4"], ["D", "8"], ["E", "16"]], "a": "C) 4", "e": "LR+ = Sensitivity / (1 - Specificity) = 0.80 / (1 - 0.80) = 0.80 / 0.20 = 4. A positive test makes disease 4 times more likely."}, {"n": "10", "stem": "A test has sensitivity 90% and specificity 80%. Calculate the negative likelihood ratio:", "opts": [["A", "0.125"], ["B", "0.25"], ["C", "0.5"], ["D", "0.9"], ["E", "1.125"]], "a": "A) 0.125", "e": "LR− = (1 - Sensitivity) / Specificity = (1 - 0.90) / 0.80 = 0.10 / 0.80 = 0.125. A negative test makes disease 8 times less likely (or reduces odds to 12.5% of what it was)."}], "simple": "Likelihood ratios are the most useful numbers in diagnostics and the least used. They tell you how much a test result should shift your belief, they do not change with prevalence, and one number covers both the positive and negative case."}, {"n": "3.2", "t": "Fagan'S Nomogram", "concepts": [{"t": "FAGAN'S NOMOGRAM", "b": ["Visual tool to calculate POST-TEST PROBABILITY", "Three parallel scales: Pre-test probability, LR, Post-test probability", "Draw line from pre-test probability through LR to get post-test probability", "Converts between probability and ODDS", "HEAVILY TESTED in MRCPsych exams"]}, {"t": "PRE-TEST AND POST-TEST PROBABILITY", "b": ["PRE-TEST PROBABILITY: Probability of disease BEFORE test (often = prevalence)", "POST-TEST PROBABILITY: Probability of disease AFTER test result known", "Positive test → probability INCREASES (use LR+)", "Negative test → probability DECREASES (use LR−)", "Calculation requires converting probability to ODDS"]}, {"t": "CONVERTING PROBABILITY TO ODDS", "b": ["ODDS = Probability / (1 − Probability)", "If probability = 20% = 0.20: Odds = 0.20 / 0.80 = 0.25 or 1:4", "If probability = 50%: Odds = 0.50 / 0.50 = 1 or 1:1", "If probability = 80%: Odds = 0.80 / 0.20 = 4 or 4:1", "PROBABILITY = Odds / (1 + Odds)"]}, {"t": "POST-TEST ODDS CALCULATION", "b": ["Post-test Odds = Pre-test Odds × Likelihood Ratio", "If test POSITIVE: use LR+", "If test NEGATIVE: use LR−", "Then convert back to probability if needed", "This is the mathematical basis of Fagan's nomogram"]}], "hy": ["Fagan's nomogram: Pre-test prob → LR → Post-test prob. Uses ODDS calculations. KNOW THIS!"], "tables": [], "mcqs": [{"n": "11", "stem": "The pre-test probability of a condition is 20%. What are the pre-test ODDS?", "opts": [["A", "1:1"], ["B", "1:4"], ["C", "1:5"], ["D", "4:1"], ["E", "5:1"]], "a": "B) 1:4", "e": "Odds = P / (1-P) = 0.20 / 0.80 = 0.25 = 1/4 = 1:4. This means for every 1 person with disease, there are 4 without. Alternatively: 20% have it, 80% don't, ratio is 20:80 = 1:4."}, {"n": "12", "stem": "Pre-test probability is 10% (odds = 1/9). A positive test has LR+ = 9. What are the post-test odds?", "opts": [["A", "1/81"], ["B", "1/9"], ["C", "1:1"], ["D", "9:1"], ["E", "81:1"]], "a": "C) 1:1", "e": "Post-test odds = Pre-test odds × LR+ = (1/9) × 9 = 1 = 1:1. This means 50% probability of disease after a positive test. The test dramatically increased probability from 10% to 50%."}, {"n": "13", "stem": "Using Fagan's nomogram, if pre-test probability is 40% and LR+ is approximately 1.1, the post-test probability is closest to:", "opts": [["A", "35%"], ["B", "40%"], ["C", "45%"], ["D", "50%"], ["E", "60%"]], "a": "C) 45%", "e": "LR+ of 1.1 means the test barely changes probability. Pre-test odds = 0.40/0.60 = 0.67. Post-test odds = 0.67 × 1.1 = 0.73. Post-test probability = 0.73/1.73 ≈ 42-45%. A test with LR close to 1 is nearly useless."}, {"n": "14", "stem": "A screening questionnaire has LR+ of 4 and LR− of 0.2. The pre-test probability is 20%. After a POSITIVE test, the post-test probability is approximately:", "opts": [["A", "20%"], ["B", "40%"], ["C", "50%"], ["D", "60%"], ["E", "80%"]], "a": "C) 50%", "e": "Pre-test odds = 0.20/0.80 = 0.25 (or 1:4). Post-test odds = 0.25 × 4 = 1.0 (or 1:1). Post-test probability = 1/(1+1) = 0.50 = 50%. The positive test increased probability from 20% to 50%."}], "simple": "The nomogram is a ruler for Bayes' theorem. You put a line through your starting probability and the likelihood ratio, and it tells you where you have ended up. It exists because doing the arithmetic by hand is slow and doing it in your head is impossible."}]}, {"t": "Treatment Effects", "topics": [{"n": "4.1", "t": "Absolute & Relative Measures", "concepts": [{"t": "ABSOLUTE RISK REDUCTION (ARR)", "b": ["Difference in event rates between groups", "ARR = Control Event Rate − Treatment Event Rate", "ARR = CER − EER", "Expressed as percentage points", "Example: 20% in control, 15% in treatment → ARR = 5%", "More clinically meaningful than relative measures"]}, {"t": "RELATIVE RISK REDUCTION (RRR)", "b": ["Proportional reduction in risk", "RRR = ARR / CER = (CER − EER) / CER", "Expressed as a percentage", "Often sounds more impressive than ARR", "Can be misleading if baseline risk is low", "Example: ARR = 5%, CER = 20% → RRR = 25%"]}], "hy": ["ARR = CER − EER. Absolute difference in risk. More clinically meaningful."], "tables": [], "mcqs": [{"n": "15", "stem": "In a trial, 30% of placebo patients had events vs 20% on active drug. The ARR is:", "opts": [["A", "50%"], ["B", "33%"], ["C", "20%"], ["D", "10%"], ["E", "0.67"]], "a": "D) 10%", "e": "ARR = CER - EER = 30% - 20% = 10 percentage points. This means treatment reduces the absolute risk by 10 percentage points compared to placebo."}, {"n": "16", "stem": "Using the same data (30% control, 20% treatment), the RRR is:", "opts": [["A", "10%"], ["B", "20%"], ["C", "33%"], ["D", "50%"], ["E", "67%"]], "a": "C) 33%", "e": "RRR = ARR / CER = 10% / 30% = 0.33 = 33%. The treatment reduces risk by one-third (33%) relative to baseline. Note how 'reduces risk by 33%' sounds more impressive than 'reduces risk by 10 percentage points'."}], "simple": "The same result can be described in two ways, and one of them always sounds more impressive. A drop from two per cent to one per cent is a fifty per cent relative reduction and a one per cent absolute reduction. Both are true. Only one is honest in a headline."}, {"n": "4.2", "t": "Number Needed To Treat (Nnt)", "concepts": [{"t": "NUMBER NEEDED TO TREAT (NNT)", "b": ["Number of patients to treat to PREVENT one bad outcome", "NNT = 1 / ARR (expressed as decimal)", "Lower NNT = more effective treatment", "NNT = 1 is perfect (every patient benefits)", "NNT = 100 means treat 100 to prevent 1 event", "Always ROUND UP to whole number"]}, {"t": "NUMBER NEEDED TO HARM (NNH)", "b": ["Number of patients treated for one to experience harm", "NNH = 1 / ARI (Absolute Risk Increase)", "Higher NNH = safer treatment", "Used for adverse effects", "Compare NNT and NNH for risk-benefit"]}, {"t": "RELATIVE RISK (RR) & ODDS RATIO (OR)", "b": ["RR = Risk in exposed / Risk in unexposed = EER / CER", "RR = 1: No association", "RR > 1: Increased risk (harm)", "RR < 1: Decreased risk (protective)", "OR approximates RR when outcome is RARE (<10%)", "OR overestimates RR for common outcomes"]}], "hy": ["NNT = 1/ARR. Lower is better. ROUND UP to whole number. NNT = 10 means treat 10 to prevent 1 event.", "RR = EER/CER. RR=1 means no effect. OR ≈ RR only when outcome is RARE."], "tables": [], "mcqs": [{"n": "17", "stem": "If ARR is 10% (0.10), what is the NNT?", "opts": [["A", "1"], ["B", "5"], ["C", "10"], ["D", "20"], ["E", "100"]], "a": "C) 10", "e": "NNT = 1 / ARR = 1 / 0.10 = 10. You need to treat 10 patients to prevent one bad outcome. This is the reciprocal of absolute risk reduction."}, {"n": "18", "stem": "A drug reduces stroke risk from 8% to 6%. The NNT is:", "opts": [["A", "2"], ["B", "13"], ["C", "25"], ["D", "50"], ["E", "100"]], "a": "D) 50", "e": "ARR = 8% - 6% = 2% = 0.02. NNT = 1/0.02 = 50. You need to treat 50 patients to prevent one stroke."}, {"n": "19", "stem": "When does odds ratio closely approximate relative risk?", "opts": [["A", "When the outcome is common"], ["B", "When the outcome is rare"], ["C", "In cohort studies only"], ["D", "In case-control studies only"], ["E", "When RR is greater than 2"]], "a": "B) When the outcome is rare", "e": "OR approximates RR when the outcome is RARE (typically <10%). As outcomes become more common, OR increasingly overestimates RR (for RR>1) or underestimates it (for RR<1)."}], "simple": "Number needed to treat is the translation of statistics into a sentence a patient can use. How many people like me have to take this for one of us to benefit? It is one divided by the absolute risk reduction, and it is the single most useful number you can quote in a consultation."}]}, {"t": "Meta-Analysis & Forest Plots", "topics": [{"n": "5.1", "t": "Forest Plots", "concepts": [{"t": "FOREST PLOT COMPONENTS", "b": ["Each study shown as SQUARE on horizontal line", "SQUARE SIZE = sample size/weight of study", "HORIZONTAL LINE = 95% confidence interval", "VERTICAL LINE = line of no effect (1 for ratios, 0 for differences)", "DIAMOND = pooled (overall) estimate from meta-analysis", "DIAMOND WIDTH = confidence interval of pooled estimate"]}], "hy": ["Square = individual study (size = weight). Diamond = pooled estimate. Vertical line = no effect."], "tables": [], "mcqs": [{"n": "20", "stem": "In a forest plot, the overall combined estimate from all individual trials is shown as:", "opts": [["A", "Diamond"], ["B", "Polygon"], ["C", "Rectangle"], ["D", "Square"], ["E", "Triangle"]], "a": "A) Diamond", "e": "The diamond represents the POOLED (overall) estimate from the meta-analysis. Its center is the point estimate, and its width represents the 95% CI. Individual studies are shown as squares."}, {"n": "21", "stem": "In a forest plot, the size of the square representing each study indicates:", "opts": [["A", "The effect size of that study"], ["B", "The confidence interval width"], ["C", "The statistical significance"], ["D", "The sample size or weight of the study"], ["E", "The quality of the study"]], "a": "D) The sample size or weight of the study", "e": "Larger squares indicate studies with larger sample sizes or greater weight in the meta-analysis. These studies contribute more to the pooled estimate. Larger studies are more precise and thus weighted more heavily."}, {"n": "22", "stem": "In a forest plot of odds ratios, if a study's confidence interval crosses the vertical line at 1, this means:", "opts": [["A", "The study shows a significant protective effect"], ["B", "The study shows a significant harmful effect"], ["C", "The result is NOT statistically significant"], ["D", "The study should be excluded from meta-analysis"], ["E", "The effect size is very large"]], "a": "C) The result is NOT statistically significant", "e": "The vertical line at 1 (for ratios) or 0 (for differences) represents NO EFFECT. If a CI crosses this line, the result is not statistically significant at p<0.05 - we cannot exclude the possibility of no effect."}, {"n": "23", "stem": "In a forest plot, a longer horizontal line through the square indicates:", "opts": [["A", "Greater effect size"], ["B", "Greater precision"], ["C", "Greater weight in meta-analysis"], ["D", "Less precision (wider confidence interval)"], ["E", "Statistical significance"]], "a": "D) Less precision (wider confidence interval)", "e": "The horizontal line represents the 95% CI. A LONGER line means a WIDER CI, indicating LESS precision. Smaller studies typically have longer lines (less precise estimates)."}], "simple": "A forest plot is a whole literature on one page. Each line is a study, its width is its uncertainty, its size is its weight, and the diamond at the bottom is what you get when you add them up. Learn to read one at a glance and you have most of meta-analysis."}, {"n": "5.2", "t": "Heterogeneity", "concepts": [{"t": "HETEROGENEITY", "b": ["Variability in results BETWEEN studies", "More than expected by chance alone", "Clinical heterogeneity: different populations, interventions", "Methodological heterogeneity: different study designs", "Statistical heterogeneity: measured by I² and Q test", "High heterogeneity may make pooling inappropriate"]}, {"t": "I² STATISTIC", "b": ["Percentage of variability due to heterogeneity (not chance)", "I² = 0%: No heterogeneity", "I² = 25%: Low heterogeneity", "I² = 50%: Moderate heterogeneity", "I² = 75%: High heterogeneity", "Does NOT indicate direction, only magnitude"]}, {"t": "COCHRAN'S Q TEST (Chi-square test for heterogeneity)", "b": ["Tests whether heterogeneity is statistically significant", "Null hypothesis: all studies share same true effect", "Significant Q (p < 0.05 or 0.10): heterogeneity present", "Low power with few studies - may miss heterogeneity", "Used alongside I², not instead of it"]}], "hy": ["Heterogeneity = variability between studies. Measured by I² and Cochran's Q. May contraindicate pooling.", "I² = % variability due to heterogeneity. 25% low, 50% moderate, 75% high."], "tables": [], "mcqs": [{"n": "24", "stem": "In a meta-analysis, I² = 80% suggests:", "opts": [["A", "80% of studies agree with pooled estimate"], ["B", "Studies are highly homogeneous"], ["C", "High statistical heterogeneity between studies"], ["D", "80% power to detect differences"], ["E", "The pooled estimate is 80% accurate"]], "a": "C) High statistical heterogeneity between studies", "e": "I² = 80% indicates that 80% of the variability between studies is due to TRUE heterogeneity rather than chance. This is HIGH heterogeneity, and the researcher should explore reasons for this variability."}, {"n": "25", "stem": "Cochrane's Q (chi-square) test for heterogeneity examines whether:", "opts": [["A", "The pooled estimate is statistically significant"], ["B", "There is unexplained variability between individual study results"], ["C", "The funnel plot shows asymmetry"], ["D", "Individual studies are biased"], ["E", "The effect is clinically meaningful"]], "a": "B) There is unexplained variability between individual study results", "e": "Cochran's Q tests whether variability between studies exceeds what would be expected by chance. A significant Q (p<0.10 typically) indicates heterogeneity is present. However, with few studies, Q has low power."}], "simple": "Heterogeneity is the question of whether the studies you are pooling are even asking the same question. If they are not, the average is meaningless, no matter how narrow its confidence interval. I-squared is the number that tells you how bad it is."}, {"n": "5.3", "t": "Fixed Vs Random Effects", "concepts": [{"t": "FIXED EFFECTS MODEL", "b": ["Assumes ONE TRUE effect size across all studies", "Differences between studies are due to CHANCE only", "Weights studies by precision (inverse variance)", "Use when heterogeneity is LOW", "Gives narrower confidence intervals"]}, {"t": "RANDOM EFFECTS MODEL", "b": ["Assumes TRUE effect VARIES between studies", "Studies sample from a DISTRIBUTION of true effects", "Accounts for between-study variance", "Use when heterogeneity is MODERATE to HIGH", "Gives WIDER confidence intervals", "Weights small and large studies more equally"]}], "hy": ["Low heterogeneity → Fixed effects. High heterogeneity → Random effects (wider CI)."], "tables": [], "mcqs": [{"n": "26", "stem": "A random effects model in meta-analysis is preferred when:", "opts": [["A", "All studies show identical results"], ["B", "There is significant heterogeneity between studies"], ["C", "Sample sizes are equal across studies"], ["D", "Only two studies are included"], ["E", "The outcome is binary"]], "a": "B) There is significant heterogeneity between studies", "e": "Random effects models account for between-study variation in true effect sizes. They are preferred when heterogeneity is moderate to high (I² > 40-50%). Fixed effects assumes one true effect and is used when heterogeneity is low."}], "simple": "Fixed effects assumes there is one true answer and the studies differ only by chance. Random effects assumes the true answer differs between studies. The choice changes the weights, widens the interval and, occasionally, changes the conclusion."}]}, {"t": "Roc Curves & Screening", "topics": [{"n": "6.1", "t": "Roc Curves", "concepts": [{"t": "ROC CURVE (Receiver Operating Characteristic)", "b": ["Graph of SENSITIVITY (y-axis) vs 1-SPECIFICITY (x-axis)", "Shows trade-off between sensitivity and specificity", "Each point = different cut-off threshold", "DIAGONAL LINE = useless test (AUC = 0.5)", "TOP-LEFT CORNER = perfect test", "Curve closer to top-left = better discrimination"]}, {"t": "AREA UNDER THE CURVE (AUC)", "b": ["Measures overall DISCRIMINATIVE ability of test", "AUC = 0.5: No discrimination (useless, like flipping coin)", "AUC = 0.7-0.8: Acceptable discrimination", "AUC = 0.8-0.9: Excellent discrimination", "AUC = 1.0: Perfect discrimination", "Probability that randomly chosen diseased person has higher test value than non-diseased"]}], "hy": ["ROC: Y-axis = Sensitivity, X-axis = 1-Specificity (False positive rate). AUC measures discrimination.", "AUC = 0.5 is useless (diagonal). AUC = 1.0 is perfect. Higher AUC = better test."], "tables": [], "mcqs": [{"n": "27", "stem": "In an ROC curve, the Y-axis represents:", "opts": [["A", "Specificity"], ["B", "1 - Specificity"], ["C", "Sensitivity"], ["D", "Positive predictive value"], ["E", "Prevalence"]], "a": "C) Sensitivity", "e": "The ROC curve plots Sensitivity (true positive rate) on the Y-axis against 1-Specificity (false positive rate) on the X-axis. Moving up increases sensitivity; moving right increases false positives."}, {"n": "28", "stem": "Two screening tests are compared. Test A has AUC = 0.85, Test B has AUC = 0.65. This indicates:", "opts": [["A", "Test B has higher sensitivity"], ["B", "Test A has higher specificity"], ["C", "Test A has better overall discriminative ability"], ["D", "Tests are equally good at different cut-offs"], ["E", "Test B should be used for screening"]], "a": "C) Test A has better overall discriminative ability", "e": "AUC measures overall ability to distinguish between diseased and non-diseased across all possible cut-offs. Higher AUC = better discrimination. Test A (0.85) has excellent discrimination vs Test B (0.65) which is only fair."}], "simple": "An ROC curve is what you get when you plot a test's sensitivity against its false alarms at every possible cut-off. The area underneath is a single number for how good the test is overall, where 0.5 is a coin toss and 1.0 is perfect."}, {"n": "6.2", "t": "Choosing Cut-Off Thresholds", "concepts": [{"t": "CHANGING THE CUT-OFF THRESHOLD", "b": ["LOWERING cut-off: More positive results", "→ INCREASES sensitivity (catches more disease)", "→ DECREASES specificity (more false positives)", "RAISING cut-off: Fewer positive results", "→ DECREASES sensitivity (misses more disease)", "→ INCREASES specificity (fewer false positives)", "There is always a TRADE-OFF"]}], "hy": ["Lower cut-off → higher Sens, lower Spec. Higher cut-off → lower Sens, higher Spec."], "tables": [], "mcqs": [{"n": "29", "stem": "The CAGE questionnaire at cut-off ≥2 has sensitivity 70% and specificity 85%. At cut-off ≥3:", "opts": [["A", "Sensitivity and specificity both increase"], ["B", "Sensitivity increases, specificity decreases"], ["C", "Sensitivity decreases, specificity increases"], ["D", "Sensitivity and specificity both decrease"], ["E", "No change in test characteristics"]], "a": "C) Sensitivity decreases, specificity increases", "e": "Raising the cut-off (from ≥2 to ≥3) makes the test more stringent. Fewer people test positive, so sensitivity falls (more false negatives), but specificity rises (fewer false positives). This is the fundamental trade-off."}, {"n": "30", "stem": "A new depression screening tool is evaluated. At which cut-off would you expect HIGHEST sensitivity?", "opts": [["A", "Score ≥ 15"], ["B", "Score ≥ 12"], ["C", "Score ≥ 10"], ["D", "Score ≥ 8"], ["E", "Score ≥ 5"]], "a": "E) Score ≥ 5", "e": "The LOWEST cut-off (≥5) would classify the most people as positive, giving the HIGHEST sensitivity. More cases are captured, but at the cost of more false positives (lower specificity)."}], "simple": "Where you put the cut-off is not a statistical decision, it is a clinical one. Move it to catch more cases and you generate more false alarms. What you should do depends on what happens to the people you miss and what happens to the people you wrongly worry."}]}, {"t": "Survival Analysis", "topics": [{"n": "7.1", "t": "Kaplan-Meier Curves", "concepts": [{"t": "KAPLAN-MEIER SURVIVAL CURVES", "b": ["Shows SURVIVAL PROBABILITY over time", "Y-axis: Survival probability (0 to 1 or 0-100%)", "X-axis: Time", "STEP-DOWN pattern when events occur", "CENSORED observations marked with ticks/crosses", "Compares survival between groups visually"]}, {"t": "READING KAPLAN-MEIER CURVES", "b": ["Find time on X-axis, read across to curve, then down to Y-axis for survival", "Example: At 40 months, if curve is at 0.75 → 75% survival", "MEDIAN SURVIVAL: Time when curve crosses 50% (0.5)", "Curves that SEPARATE show different survival between groups", "Lower curve = worse survival"]}], "hy": ["Kaplan-Meier: Y = survival probability, X = time. Steps down at each event. Ticks = censored."], "tables": [], "mcqs": [{"n": "31", "stem": "In a Kaplan-Meier curve, the step-down pattern indicates:", "opts": [["A", "Patients being censored"], ["B", "Events (deaths/outcomes) occurring"], ["C", "New patients entering the study"], ["D", "Treatment being administered"], ["E", "Loss to follow-up"]], "a": "B) Events (deaths/outcomes) occurring", "e": "The survival curve STEPS DOWN each time an event occurs (death, relapse, etc.). The size of the step depends on how many were at risk at that time. Censoring is usually shown as tick marks, not steps."}, {"n": "32", "stem": "In a Kaplan-Meier curve, a tick mark or cross on the curve represents:", "opts": [["A", "A death or event"], ["B", "A censored observation (lost to follow-up or study end)"], ["C", "The median survival time"], ["D", "A change in treatment"], ["E", "A significant p-value"]], "a": "B) A censored observation (lost to follow-up or study end)", "e": "Tick marks indicate CENSORED observations - patients who left the study alive (lost to follow-up, study ended, or withdrew). We know they survived to that point but don't know what happened after."}, {"n": "33", "stem": "A Kaplan-Meier curve shows survival of 75% at 40 months. This means:", "opts": [["A", "75% of patients died by 40 months"], ["B", "75% of patients were alive at 40 months"], ["C", "The median survival was 40 months"], ["D", "25% were lost to follow-up"], ["E", "The study lasted 40 months"]], "a": "B) 75% of patients were alive at 40 months", "e": "The Y-axis shows SURVIVAL probability. 75% survival at 40 months means 75% of patients were still alive (had not experienced the event) at that time point. Therefore, 25% had the event (died/relapsed)."}], "simple": "When the outcome is not just whether something happened but when, you need survival analysis. A Kaplan-Meier curve is a staircase where every step down is an event, and the crosses along the way are people you stopped being able to follow."}, {"n": "7.2", "t": "Log-Rank Test & Hazard Ratios", "concepts": [{"t": "LOG-RANK TEST", "b": ["Compares survival curves between groups", "Tests null hypothesis: no difference in survival", "Non-parametric test", "Uses chi-square distribution", "df = number of groups − 1", "Significant p-value = survival differs between groups"]}, {"t": "HAZARD RATIO (HR)", "b": ["From Cox proportional hazards regression", "HR = 1: No difference in hazard between groups", "HR > 1: Increased hazard (harm/higher risk)", "HR < 1: Decreased hazard (protective)", "Example: HR = 2 means twice the hazard of event", "Assumes PROPORTIONAL hazards over time"]}], "hy": ["HR = 1 means no difference. HR > 1 = more hazard. HR < 1 = less hazard (protective)."], "tables": [], "mcqs": [{"n": "34", "stem": "The log-rank test is used to:", "opts": [["A", "Calculate median survival"], ["B", "Compare survival curves between groups"], ["C", "Estimate hazard ratios"], ["D", "Adjust for confounders"], ["E", "Test for proportional hazards"]], "a": "B) Compare survival curves between groups", "e": "The log-rank test compares Kaplan-Meier survival curves between two or more groups. It tests whether the survival experience differs significantly. Cox regression is used for hazard ratios and adjusting confounders."}, {"n": "35", "stem": "A study reports HR = 0.6 (95% CI: 0.4-0.8) for death with treatment vs placebo. This means:", "opts": [["A", "Treatment increases risk of death by 60%"], ["B", "Treatment reduces hazard of death by 40%"], ["C", "60% of treated patients died"], ["D", "The result is not statistically significant"], ["E", "Treatment has no effect on survival"]], "a": "B) Treatment reduces hazard of death by 40%", "e": "HR = 0.6 means the treatment group has 60% of the hazard (risk) of the control group, or a 40% reduction in hazard. CI excludes 1, so it IS statistically significant. This is a protective effect."}], "simple": "The log-rank test asks whether two survival curves differ. The hazard ratio says by how much, at any given instant. It is a relative risk that applies continuously through time rather than at one endpoint."}]}, {"t": "Systematic Reviews", "topics": [{"n": "8.1", "t": "Systematic Review Methodology", "concepts": [{"t": "SYSTEMATIC REVIEW", "b": ["Comprehensive search and synthesis of ALL relevant studies", "Pre-defined protocol and research question", "Explicit inclusion/exclusion criteria", "Systematic search of multiple databases", "Quality assessment of included studies", "May or may not include meta-analysis"]}, {"t": "META-ANALYSIS", "b": ["STATISTICAL combination of results from multiple studies", "Increases statistical power", "Provides more precise estimate", "Only appropriate if studies are sufficiently similar", "A systematic review CAN exist without meta-analysis", "But meta-analysis REQUIRES systematic search"]}], "hy": ["Systematic review = comprehensive search. Meta-analysis = statistical pooling. Can have review without meta-analysis."], "tables": [], "mcqs": [{"n": "36", "stem": "Which statement about systematic reviews and meta-analyses is TRUE?", "opts": [["A", "All systematic reviews include meta-analysis"], ["B", "Meta-analysis can be performed without systematic review"], ["C", "Systematic review can be performed without meta-analysis"], ["D", "Both are identical terms"], ["E", "Neither involves quality assessment"]], "a": "C) Systematic review can be performed without meta-analysis", "e": "Systematic review is the process of comprehensively searching and appraising evidence. Meta-analysis is the statistical pooling. If studies are too heterogeneous to pool, you can have a systematic review WITHOUT meta-analysis (narrative synthesis instead)."}], "simple": "A systematic review is a study whose subjects are other studies, and like any study it can be done well or badly. What makes it systematic is that the question, the search and the inclusion rules were all written down before anybody looked at the results."}, {"n": "8.2", "t": "Publication Bias", "concepts": [{"t": "PUBLICATION BIAS", "b": ["Studies with POSITIVE results more likely to be published", "Leads to OVERESTIMATION of treatment effects", "Detected using FUNNEL PLOT", "Asymmetric funnel plot suggests bias", "Small studies with negative results 'missing'", "Reduced by: trial registries, searching grey literature"]}], "hy": ["Fagan's nomogram: Pre-test odds × LR = Post-test odds. Sens/Spec NOT affected by prevalence. PPV/NPV ARE affected."], "tables": [{"cap": "2×2 Table Formulas", "rows": [["Measure", "Formula", "Mnemonic"], ["Sensitivity", "TP / (TP + FN)", "SnNOut"], ["Specificity", "TN / (TN + FP)", "SpPIn"], ["PPV", "TP / (TP + FP)", "Prob disease if +"], ["NPV", "TN / (TN + FN)", "Prob no disease if −"], ["LR+", "Sens / (1 − Spec)", "How much + increases odds"], ["LR−", "(1 − Sens) / Spec", "How much − decreases odds"]]}, {"cap": "Treatment Effect Formulas", "rows": [["Measure", "Formula"], ["ARR", "CER − EER"], ["RRR", "ARR / CER = (CER−EER) / CER"], ["NNT", "1 / ARR"], ["RR", "EER / CER"], ["OR", "(a×d) / (b×c) in 2×2 table"]]}, {"cap": "Key Concepts Summary", "rows": [["Concept", "Key Point"], ["Sensitivity", "Detect disease when PRESENT"], ["Specificity", "Exclude disease when ABSENT"], ["PPV", "INCREASES with prevalence"], ["NPV", "DECREASES with prevalence"], ["LR+ > 10", "Strong evidence to rule IN"], ["LR− < 0.1", "Strong evidence to rule OUT"], ["I² > 75%", "High heterogeneity"], ["AUC = 0.5", "Useless test"], ["HR < 1", "Protective effect"]]}], "mcqs": [{"n": "37", "stem": "In a funnel plot assessing publication bias, asymmetry typically indicates:", "opts": [["A", "High statistical power"], ["B", "Homogeneous study results"], ["C", "Missing small studies with negative results"], ["D", "Large effect size"], ["E", "Low heterogeneity"]], "a": "C) Missing small studies with negative results", "e": "Funnel plot asymmetry suggests publication bias - typically small studies with negative/null results are 'missing' from the bottom left of the plot. They weren't published, so the meta-analysis overestimates the true effect."}, {"n": "38", "stem": "The funnel plot in meta-analysis derives its name from:", "opts": [["A", "Its shape when no publication bias exists"], ["B", "The shape of the forest plot"], ["C", "The Q statistic distribution"], ["D", "The I-squared calculation"], ["E", "The diamond shape of pooled estimates"]], "a": "A) Its shape when no publication bias exists", "e": "When there is NO publication bias, the plot should look like an inverted funnel - large studies cluster at the top near the pooled estimate, while smaller studies scatter more widely at the bottom, creating a symmetrical funnel shape."}], "simple": "A meta-analysis is only as good as what was allowed into it. If small negative studies never got published, pooling the survivors gives you a very confident wrong answer with a very narrow confidence interval. A funnel plot is how you look for the missing ones."}]}]}, {"p": "D", "name": "Calculations", "sub": "Every calculation you can be asked to do, worked step by step.", "themes": [{"t": "Calculations", "topics": [{"n": "1.1", "t": "Converting Probability To Odds", "concepts": [{"t": "📝 WORKED EXAMPLE: Convert 20% probability to odds", "b": ["Step 1: Write probability as decimal: P = 20% = 0.20", "Step 2: Calculate (1 − P): 1 − 0.20 = 0.80", "Step 3: Apply formula: Odds = 0.20 ÷ 0.80 = 0.25", "Step 4: Express as ratio: 0.25 = 1/4 = 1:4", "Step 5: ANSWER: Odds = 1:4 (or 0.25)"]}], "hy": ["Quick trick: If P = 1/n, then Odds = 1:(n-1). Example: P = 1/5 → Odds = 1:4"], "tables": [{"cap": "Common Probability to Odds Conversions (MEMORIZE)", "rows": [["Probability", "Decimal", "Odds", "Expressed as"], ["10%", "0.10", "0.10/0.90 = 0.111", "1:9"], ["20%", "0.20", "0.20/0.80 = 0.25", "1:4"], ["25%", "0.25", "0.25/0.75 = 0.33", "1:3"], ["33%", "0.33", "0.33/0.67 = 0.50", "1:2"], ["50%", "0.50", "0.50/0.50 = 1.0", "1:1"], ["67%", "0.67", "0.67/0.33 = 2.0", "2:1"], ["75%", "0.75", "0.75/0.25 = 3.0", "3:1"], ["80%", "0.80", "0.80/0.20 = 4.0", "4:1"], ["90%", "0.90", "0.90/0.10 = 9.0", "9:1"]]}], "mcqs": [{"n": "1", "stem": "The pre-test probability of depression is 12.5% (1/8). What are the pre-test ODDS?", "opts": [["A", "1:8"], ["B", "1:7"], ["C", "1:9"], ["D", "7:1"], ["E", "8:1"]], "a": "B) 1:7", "e": "WORKING:\nP = 12.5% = 1/8 = 0.125\n(1 − P) = 1 − 0.125 = 0.875 = 7/8\nOdds = P / (1−P) = (1/8) / (7/8) = 1/8 × 8/7 = 1/7\nOR: If 1 in 8 have disease, then 7 in 8 don't\nOdds = those with : those without = 1:7"}], "simple": "Probability and odds are two ways of describing the same chance, and switching between them trips people constantly. Probability is the winners divided by everybody. Odds is the winners divided by the losers. One divides by the whole, the other by the rest."}, {"n": "1.2", "t": "Converting Odds To Probability", "concepts": [{"t": "📝 WORKED EXAMPLE: Convert odds of 4:1 to probability", "b": ["Step 1: Express odds as decimal: 4:1 = 4/1 = 4", "Step 2: Calculate (1 + Odds): 1 + 4 = 5", "Step 3: Apply formula: P = 4 ÷ 5 = 0.80", "Step 4: Express as percentage: 0.80 × 100 = 80%", "Step 5: ANSWER: Probability = 80%"]}], "hy": [], "tables": [], "mcqs": [{"n": "2", "stem": "After a positive test, post-test odds are 3:1. What is the post-test PROBABILITY?", "opts": [["A", "30%"], ["B", "33%"], ["C", "67%"], ["D", "75%"], ["E", "300%"]], "a": "D) 75%", "e": "WORKING:\nOdds = 3:1 = 3\nP = Odds / (1 + Odds)\nP = 3 / (1 + 3) = 3/4 = 0.75\nConvert to percentage: 0.75 × 100 = 75%\nCheck: 3 with disease : 1 without = 3 out of 4 = 75% ✓"}], "simple": "Going the other way, from odds back to probability, is one formula and it is worth having automatic. When odds are small the two numbers are almost identical, which is exactly why odds ratios approximate relative risk in rare diseases."}, {"n": "2.1", "t": "Calculating Lr+", "concepts": [{"t": "📝 WORKED EXAMPLE: Test has Sensitivity 80%, Specificity 75%. Calculate LR+", "b": ["Step 1: Convert to decimals: Sens = 0.80, Spec = 0.75", "Step 2: Calculate (1 − Specificity): 1 − 0.75 = 0.25", "Step 3: Apply formula: LR+ = 0.80 ÷ 0.25", "Step 4: LR+ = 3.2", "Step 5: Interpretation: Positive test is 3.2× more likely in diseased than non-diseased"]}], "hy": [], "tables": [], "mcqs": [{"n": "3", "stem": "A screening test has sensitivity 90% and specificity 80%. What is the LR+?", "opts": [["A", "1.125"], ["B", "2.5"], ["C", "4.5"], ["D", "7.2"], ["E", "9.0"]], "a": "C) 4.5", "e": "WORKING:\nSensitivity = 90% = 0.90\nSpecificity = 80% = 0.80\n(1 − Specificity) = 1 − 0.80 = 0.20\nLR+ = Sens / (1 − Spec) = 0.90 / 0.20 = 4.5\nA positive result is 4.5× more likely if disease present"}], "simple": "The positive likelihood ratio asks how much more often a positive result happens in people who have the disease than in people who do not. It is sensitivity over one minus specificity, and it is the number that tells you what a positive result is worth."}, {"n": "2.2", "t": "Calculating Lr−", "concepts": [{"t": "📝 WORKED EXAMPLE: Test has Sensitivity 90%, Specificity 80%. Calculate LR−", "b": ["Step 1: Convert to decimals: Sens = 0.90, Spec = 0.80", "Step 2: Calculate (1 − Sensitivity): 1 − 0.90 = 0.10", "Step 3: Apply formula: LR− = 0.10 ÷ 0.80", "Step 4: LR− = 0.125", "Step 5: Interpretation: Negative test reduces odds of disease to 12.5% of pre-test odds"]}], "hy": [], "tables": [{"cap": "LR Interpretation Guide", "rows": [["LR+ Value", "Effect", "LR− Value", "Effect"], ["> 10", "Conclusive ↑↑↑", "< 0.1", "Conclusive ↓↓↓"], ["5 − 10", "Moderate ↑↑", "0.1 − 0.2", "Moderate ↓↓"], ["2 − 5", "Small ↑", "0.2 − 0.5", "Small ↓"], ["1 − 2", "Minimal", "0.5 − 1", "Minimal"], ["= 1", "Useless test", "= 1", "Useless test"]]}], "mcqs": [{"n": "4", "stem": "A test has sensitivity 95% and specificity 60%. What is the LR−?", "opts": [["A", "0.05"], ["B", "0.083"], ["C", "0.158"], ["D", "0.40"], ["E", "0.95"]], "a": "B) 0.083", "e": "WORKING:\nSensitivity = 95% = 0.95\nSpecificity = 60% = 0.60\n(1 − Sensitivity) = 1 − 0.95 = 0.05\nLR− = (1 − Sens) / Spec = 0.05 / 0.60 = 0.083\nLR− < 0.1 is excellent for ruling OUT disease"}], "simple": "The negative likelihood ratio does the same job for a negative result. It is one minus sensitivity over specificity, and a value below 0.1 means a negative result has substantially ruled the disease out."}, {"n": "3.1", "t": "The Core Calculation", "concepts": [{"t": "📝 WORKED EXAMPLE: Pre-test probability 20%, LR+ = 4. Find post-test probability after POSITIVE test.", "b": ["Step 1: Convert pre-test probability to odds: Odds = 0.20 / 0.80 = 0.25 (or 1:4)", "Step 2: Multiply by LR+ (since test is positive): Post-test Odds = 0.25 × 4 = 1.0", "Step 3: Convert back to probability: P = 1.0 / (1 + 1.0) = 0.50", "Step 4: Express as percentage: 50%", "Step 5: ANSWER: Post-test probability = 50%"]}], "hy": [], "tables": [], "mcqs": [{"n": "5", "stem": "Pre-test probability is 10%. A positive test has LR+ = 9. What is the post-test probability?", "opts": [["A", "19%"], ["B", "45%"], ["C", "50%"], ["D", "90%"], ["E", "99%"]], "a": "C) 50%", "e": "WORKING:\nPre-test probability = 10% = 0.10\nPre-test odds = 0.10 / 0.90 = 1/9\nPost-test odds = Pre-test odds × LR+ = (1/9) × 9 = 1\nPost-test probability = 1 / (1+1) = 0.50 = 50%\nThe positive test increased probability from 10% to 50%"}, {"n": "6", "stem": "Using Fagan's nomogram: Pre-test probability 40%, LR+ ≈ 1.1. Post-test probability is approximately:", "opts": [["A", "35%"], ["B", "40%"], ["C", "42%"], ["D", "45%"], ["E", "50%"]], "a": "D) 45%", "e": "WORKING:\nPre-test probability = 40% = 0.40\nPre-test odds = 0.40 / 0.60 = 0.667\nPost-test odds = 0.667 × 1.1 = 0.733\nPost-test probability = 0.733 / 1.733 = 0.42 ≈ 42-45%\nLR+ close to 1 means test barely changes probability (nearly useless)"}], "simple": "Bayes in three steps: turn your pre-test probability into odds, multiply by the likelihood ratio, turn the answer back into a probability. That is the entire calculation, and once you have done it four times it becomes mechanical."}, {"n": "3.2", "t": "Worked Examples - Positive Tests", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "7", "stem": "Prevalence of alcoholism is 8% (pre-test probability). CAGE questionnaire has LR+ = 5.0. After positive CAGE, probability of alcoholism is:", "opts": [["A", "13%"], ["B", "25%"], ["C", "30%"], ["D", "40%"], ["E", "50%"]], "a": "C) 30%", "e": "WORKING:\nPre-test probability = 8% = 0.08\nPre-test odds = 0.08 / 0.92 = 0.087 (approximately 1:11.5)\nPost-test odds = 0.087 × 5 = 0.435\nPost-test probability = 0.435 / 1.435 = 0.303 ≈ 30%\nPositive CAGE increases probability from 8% to 30%"}], "simple": "Working through positive results, step by step, with real numbers. The skill being drilled here is not understanding, it is speed and accuracy under exam conditions with no calculator you trust."}, {"n": "3.3", "t": "Worked Examples - Negative Tests", "concepts": [{"t": "📝 WORKED EXAMPLE: Pre-test probability 50%, LR− = 0.1. Find post-test probability after NEGATIVE test.", "b": ["Step 1: Convert pre-test probability to odds: Odds = 0.50 / 0.50 = 1.0 (1:1)", "Step 2: Multiply by LR− (since test is negative): Post-test Odds = 1.0 × 0.1 = 0.1", "Step 3: Convert back to probability: P = 0.1 / (1 + 0.1) = 0.1/1.1 = 0.091", "Step 4: Express as percentage: ≈ 9%", "Step 5: ANSWER: Post-test probability ≈ 9% (negative test dramatically reduced probability)"]}], "hy": [], "tables": [], "mcqs": [{"n": "8", "stem": "Pre-test probability is 25%. After negative test with LR− = 0.2, post-test probability is:", "opts": [["A", "5%"], ["B", "6.25%"], ["C", "10%"], ["D", "20%"], ["E", "25%"]], "a": "B) 6.25%", "e": "WORKING:\nPre-test probability = 25% = 0.25\nPre-test odds = 0.25 / 0.75 = 0.333 (or 1:3)\nPost-test odds = 0.333 × 0.2 = 0.0667\nPost-test probability = 0.0667 / 1.0667 = 0.0625 = 6.25%\nNegative test reduced probability from 25% to 6.25%"}], "simple": "The same three steps applied to a negative result. The only difference is which likelihood ratio you multiply by, and forgetting to switch is the commonest error in this whole section."}, {"n": "4.1", "t": "Sensitivity & Specificity From 2×2", "concepts": [{"t": "📝 WORKED EXAMPLE: Calculate Sensitivity, Specificity, PPV, NPV from table above", "b": ["Step 1: Sensitivity = TP / (TP + FN) = 80 / (80 + 10) = 80/90 = 0.889 = 88.9%", "Step 2: Specificity = TN / (TN + FP) = 90 / (90 + 20) = 90/110 = 0.818 = 81.8%", "Step 3: PPV = TP / (TP + FP) = 80 / (80 + 20) = 80/100 = 0.80 = 80%", "Step 4: NPV = TN / (TN + FN) = 90 / (90 + 10) = 90/100 = 0.90 = 90%"]}], "hy": ["Memory aid: Sensitivity uses DISEASE column (TP+FN). Specificity uses NO DISEASE column (TN+FP)."], "tables": [{"cap": "", "rows": [["", "", "DISEASE", "DISEASE"], ["", "", "Present (+)", "Absent (−)"], ["TEST", "Positive", "TP = 80", "FP = 20"], ["TEST", "Negative", "FN = 10", "TN = 90"]]}], "mcqs": [{"n": "9", "stem": "In the table above, the SENSITIVITY is:", "opts": [["A", "80%"], ["B", "81.8%"], ["C", "88.9%"], ["D", "90%"], ["E", "100%"]], "a": "C) 88.9%", "e": "WORKING:\nSensitivity = TP / (TP + FN)\nSensitivity = 80 / (80 + 10)\nSensitivity = 80 / 90 = 0.889\nConvert to percentage: 88.9%\nThis is the proportion of diseased who test positive"}], "simple": "Given a two by two table and nothing else, produce sensitivity, specificity and both predictive values. Draw the table, label the rows and columns before you calculate anything, and the formulas fall out of the layout."}, {"n": "4.2", "t": "Screening Tool Cut-Off Calculations", "concepts": [], "hy": [], "tables": [{"cap": "CAGE Screening Data", "rows": [["CAGE Score", "Alcoholics (n=50)", "Non-Alcoholics (n=100)"], ["≥ 1", "45", "40"], ["≥ 2", "40", "25"], ["≥ 3", "18", "8"], ["≥ 4", "10", "2"]]}], "mcqs": [{"n": "10", "stem": "Using the CAGE data above, what is the SENSITIVITY at cut-off ≥2?", "opts": [["A", "36%"], ["B", "40%"], ["C", "62%"], ["D", "75%"], ["E", "80%"]], "a": "E) 80%", "e": "WORKING:\nAt cut-off ≥2: 40 alcoholics screen positive out of 50 total alcoholics\nSensitivity = TP / (TP + FN) = True positives / All with disease\nSensitivity = 40 / 50 = 0.80 = 80%\nThis means 80% of alcoholics are detected at this cut-off"}, {"n": "11", "stem": "Using the CAGE data, what is the SPECIFICITY at cut-off ≥2?", "opts": [["A", "25%"], ["B", "60%"], ["C", "75%"], ["D", "80%"], ["E", "92%"]], "a": "C) 75%", "e": "WORKING:\nAt cut-off ≥2: 25 non-alcoholics screen positive (FP), 75 screen negative (TN)\nSpecificity = TN / (TN + FP) = True negatives / All without disease\nSpecificity = 75 / 100 = 0.75 = 75%\nThis means 75% of non-alcoholics correctly test negative"}, {"n": "12", "stem": "At cut-off ≥3, sensitivity is 36% (18/50) and specificity is 92% (92/100). Compared to cut-off ≥2:", "opts": [["A", "Both sensitivity and specificity increased"], ["B", "Both sensitivity and specificity decreased"], ["C", "Sensitivity increased, specificity decreased"], ["D", "Sensitivity decreased, specificity increased"], ["E", "No change in test characteristics"]], "a": "D) Sensitivity decreased, specificity increased", "e": "WORKING:\nAt ≥2: Sensitivity 80%, Specificity 75%\nAt ≥3: Sensitivity 36%, Specificity 92%\nRAISING the cut-off makes the test more STRINGENT\nFewer people test positive → misses more cases (↓ Sens) but fewer false positives (↑ Spec)\nThis is the fundamental sensitivity-specificity TRADE-OFF"}], "simple": "Screening tools have a cut-off, and moving it changes every number in the table. These calculations ask you to work out what happens to sensitivity, specificity and the predictive values when the threshold moves."}, {"n": "5.1", "t": "Arr And Nnt", "concepts": [{"t": "📝 WORKED EXAMPLE: Drug trial: 25% of placebo group had events vs 15% on drug. Calculate ARR and NNT.", "b": ["Step 1: CER (Control Event Rate) = 25% = 0.25", "Step 2: EER (Experimental Event Rate) = 15% = 0.15", "Step 3: ARR = CER − EER = 0.25 − 0.15 = 0.10 = 10%", "Step 4: NNT = 1 / ARR = 1 / 0.10 = 10", "Step 5: ANSWER: Need to treat 10 patients to prevent 1 event"]}], "hy": [], "tables": [], "mcqs": [{"n": "13", "stem": "In a stroke prevention trial: Placebo group 8% stroke rate, Treatment group 5% stroke rate. The NNT is:", "opts": [["A", "3"], ["B", "13"], ["C", "33"], ["D", "63"], ["E", "100"]], "a": "C) 33", "e": "WORKING:\nCER = 8% = 0.08\nEER = 5% = 0.05\nARR = 0.08 − 0.05 = 0.03 = 3%\nNNT = 1 / 0.03 = 33.3 → Round UP to 34\nNeed to treat 33-34 patients to prevent 1 stroke"}, {"n": "14", "stem": "A drug reduces mortality from 4% to 3%. The NNT is:", "opts": [["A", "1"], ["B", "10"], ["C", "25"], ["D", "100"], ["E", "400"]], "a": "D) 100", "e": "WORKING:\nCER = 4% = 0.04\nEER = 3% = 0.03\nARR = 0.04 − 0.03 = 0.01 = 1%\nNNT = 1 / 0.01 = 100\nNeed to treat 100 patients to prevent 1 death"}], "simple": "Absolute risk reduction is the difference between two event rates. Number needed to treat is one divided by it, rounded up. Two subtractions and one division, and yet these are among the most reliably dropped marks in the paper."}, {"n": "5.2", "t": "Rrr Calculations", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "15", "stem": "From the stroke trial above (CER 8%, EER 5%, ARR 3%), what is the RRR?", "opts": [["A", "3%"], ["B", "5%"], ["C", "37.5%"], ["D", "62.5%"], ["E", "160%"]], "a": "C) 37.5%", "e": "WORKING:\nRRR = ARR / CER\nRRR = 0.03 / 0.08 = 0.375 = 37.5%\nThe drug reduces RELATIVE risk by 37.5%\nNote: '37.5% risk reduction' sounds more impressive than '3 percentage point reduction'\nAlways report ARR alongside RRR for complete picture"}], "simple": "Relative risk reduction is the absolute reduction expressed as a proportion of the control rate. It is always the bigger-sounding number, which is why drug companies quote it and why you should always ask for the absolute one alongside."}, {"n": "5.3", "t": "Relative Risk (Rr)", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "16", "stem": "Event rate is 30% in exposed group and 10% in unexposed. What is the relative risk?", "opts": [["A", "0.33"], ["B", "0.67"], ["C", "2.0"], ["D", "3.0"], ["E", "20%"]], "a": "D) 3.0", "e": "WORKING:\nEER (Exposed Event Rate) = 30% = 0.30\nCER (Control/Unexposed Event Rate) = 10% = 0.10\nRR = EER / CER = 0.30 / 0.10 = 3.0\nExposed group has 3× the risk of the outcome\nRR > 1 indicates increased risk (harmful exposure)"}], "simple": "Relative risk is the risk in the exposed divided by the risk in the unexposed. A value of one means no association, above one means increased risk, below one means protection. Calculate it directly from the table."}, {"n": "6.1", "t": "Standard Error", "concepts": [{"t": "📝 WORKED EXAMPLE: SD = 15, sample size n = 225. Calculate SE.", "b": ["Step 1: SE = SD / √n", "Step 2: SE = 15 / √225", "Step 3: SE = 15 / 15", "Step 4: SE = 1", "Step 5: The standard error is 1"]}], "hy": [], "tables": [], "mcqs": [{"n": "17", "stem": "A study has SD = 20 and n = 100. What is the SE?", "opts": [["A", "0.2"], ["B", "2"], ["C", "5"], ["D", "10"], ["E", "20"]], "a": "B) 2", "e": "WORKING:\nSE = SD / √n\nSE = 20 / √100\nSE = 20 / 10\nSE = 2\nSE is always smaller than SD"}, {"n": "18", "stem": "To HALVE the standard error, you must:", "opts": [["A", "Double the sample size"], ["B", "Halve the SD"], ["C", "Quadruple the sample size"], ["D", "Square the sample size"], ["E", "Halve the sample size"]], "a": "C) Quadruple the sample size", "e": "WORKING:\nSE = SD / √n\nTo halve SE: need to double √n\nIf √n doubles, then n must quadruple (2² = 4)\nExample: If n=100, SE = SD/10. To get SE = SD/20, need √n = 20, so n = 400\nThis is why large samples are expensive but improve precision"}], "simple": "Standard error is the standard deviation divided by the square root of the sample size. That square root is why quadrupling your sample only halves your standard error, and why very large trials get expensive for diminishing returns."}, {"n": "6.2", "t": "Confidence Intervals", "concepts": [{"t": "📝 WORKED EXAMPLE: Mean = 50, SE = 5. Calculate 95% CI.", "b": ["Step 1: Margin of error = 1.96 × SE = 1.96 × 5 = 9.8", "Step 2: Lower limit = Mean − 9.8 = 50 − 9.8 = 40.2", "Step 3: Upper limit = Mean + 9.8 = 50 + 9.8 = 59.8", "Step 4: 95% CI = (40.2 to 59.8)", "Step 5: We are 95% confident true mean lies between 40.2 and 59.8"]}], "hy": [], "tables": [], "mcqs": [{"n": "19", "stem": "Mean difference = 10, 95% CI = (2 to 18). This result is:", "opts": [["A", "Not statistically significant"], ["B", "Statistically significant at p < 0.05"], ["C", "Clinically significant but not statistically"], ["D", "Cannot be determined"], ["E", "Significant at p < 0.01"]], "a": "B) Statistically significant at p < 0.05", "e": "WORKING:\nFor differences: line of no effect = 0\nThe 95% CI (2 to 18) does NOT include 0\nTherefore the result IS statistically significant\nIf CI had been (-3 to 23), it would include 0 → NOT significant\nThis is equivalent to p < 0.05"}, {"n": "20", "stem": "OR = 2.5 with 95% CI (0.8 to 7.8). This result is:", "opts": [["A", "Statistically significant at p < 0.05"], ["B", "Not statistically significant"], ["C", "Protective"], ["D", "Highly significant"], ["E", "Cannot interpret without p-value"]], "a": "B) Not statistically significant", "e": "WORKING:\nFor ratios (OR, RR, HR): line of no effect = 1\nThe 95% CI (0.8 to 7.8) INCLUDES 1\nTherefore the result is NOT statistically significant\nWe cannot exclude OR = 1 (no effect)\nThis is equivalent to p > 0.05"}], "simple": "A ninety-five per cent confidence interval is the estimate plus or minus 1.96 standard errors. That 1.96 is worth memorising as a number rather than looking up as a concept."}, {"n": "7.1", "t": "The 68-95-99.7 Rule", "concepts": [], "hy": [], "tables": [{"cap": "Normal Distribution Percentages (MUST MEMORIZE)", "rows": [["Range", "% WITHIN", "% OUTSIDE", "Outside Each Tail"], ["±1 SD", "68%", "32%", "16%"], ["±1.96 SD", "95%", "5%", "2.5%"], ["±2 SD", "95.4%", "4.6%", "2.3%"], ["±3 SD", "99.7%", "0.3%", "0.15%"]]}], "mcqs": [{"n": "21", "stem": "The percentage of scores that fall OUTSIDE ±1 SD in a normal distribution is:", "opts": [["A", "16%"], ["B", "32%"], ["C", "34%"], ["D", "68%"], ["E", "95%"]], "a": "B) 32%", "e": "WORKING:\n68% of values fall WITHIN ±1 SD\nTherefore, 100% − 68% = 32% fall OUTSIDE ±1 SD\nThis is split evenly: 16% below −1 SD, 16% above +1 SD\nCOMMON TRAP: Don't confuse 'outside' (32%) with 'within' (68%)"}, {"n": "22", "stem": "In a normal distribution, what percentage of values lie ABOVE +2 SD?", "opts": [["A", "2.5%"], ["B", "5%"], ["C", "16%"], ["D", "32%"], ["E", "47.5%"]], "a": "A) 2.5%", "e": "WORKING:\n95% of values lie within ±2 SD (actually ±1.96 SD)\nTherefore 5% lie outside ±2 SD\nThis 5% is split equally between two tails\nAbove +2 SD: 2.5%  |  Below −2 SD: 2.5%"}], "simple": "Sixty-eight, ninety-five, ninety-nine point seven. Within one, two and three standard deviations of the mean. These three numbers, plus the fact that 1.96 rather than 2 gives exactly ninety-five per cent, answer a surprising proportion of the statistics questions in this paper."}, {"n": "7.2", "t": "Z-Score Calculations", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "23", "stem": "Population mean IQ = 100, SD = 15. A person scores 130. Their Z-score is:", "opts": [["A", "+1"], ["B", "+2"], ["C", "+3"], ["D", "+30"], ["E", "+8.67"]], "a": "B) +2", "e": "WORKING:\nZ = (X − μ) / σ\nZ = (130 − 100) / 15\nZ = 30 / 15\nZ = +2\nThis person is 2 standard deviations ABOVE the mean"}, {"n": "24", "stem": "Mean = 50, SD = 10. What percentage of people score above 70?", "opts": [["A", "2.5%"], ["B", "5%"], ["C", "16%"], ["D", "32%"], ["E", "50%"]], "a": "A) 2.5%", "e": "WORKING:\nZ = (70 − 50) / 10 = 20 / 10 = +2\n70 is 2 SD above the mean\nOnly 2.5% of values lie above +2 SD (upper tail)\nThis is from the 5% outside ±2 SD, split between tails"}], "simple": "A z-score says how many standard deviations a value sits from the mean. Once you have it, the normal distribution percentages tell you what proportion of people are above or below."}, {"n": "8.1", "t": "Power Calculations", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "25", "stem": "A study has power of 80%. What is the probability of Type II error?", "opts": [["A", "5%"], ["B", "20%"], ["C", "80%"], ["D", "95%"], ["E", "Cannot be determined"]], "a": "B) 20%", "e": "WORKING:\nPower = 1 − β\n0.80 = 1 − β\nβ = 1 − 0.80 = 0.20 = 20%\nType II error (β) = probability of missing a real effect\n80% power means 20% chance of Type II error"}, {"n": "26", "stem": "If Type II error rate is 10%, what is the power?", "opts": [["A", "10%"], ["B", "80%"], ["C", "90%"], ["D", "95%"], ["E", "100%"]], "a": "C) 90%", "e": "WORKING:\nβ = 10% = 0.10\nPower = 1 − β\nPower = 1 − 0.10 = 0.90 = 90%\nHigh power (90%) = low chance of missing real effect (10%)"}], "simple": "Power calculations ask how many people you need. The four ingredients are the significance level, the power you want, the effect size you are looking for, and the variability of the outcome. Smaller effects and noisier outcomes both demand more people."}, {"n": "8.2", "t": "Standardized Difference", "concepts": [], "hy": [], "tables": [{"cap": "Standardized Difference Interpretation", "rows": [["Value", "Effect Size", "Sample Size Needed"], ["0.2", "Small", "Very large"], ["0.5", "Medium", "Moderate"], ["0.8", "Large", "Smaller"]]}], "mcqs": [{"n": "27", "stem": "Expected mean difference is 10 points, SD is 25. What standardized difference is used for Altman's nomogram?", "opts": [["A", "0.25"], ["B", "0.4"], ["C", "2.5"], ["D", "15"], ["E", "250"]], "a": "B) 0.4", "e": "WORKING:\nStandardized difference = Expected difference / SD\n= 10 / 25 = 0.4\nThis is used in Altman's nomogram for sample size calculation\nSmaller standardized difference → larger sample needed"}], "simple": "Standardised difference expresses a difference in units of standard deviation, which lets you compare across studies that used different scales. It is the same idea as Cohen's d."}, {"n": "9.1", "t": "Kaplan-Meier Calculations", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "28", "stem": "A Kaplan-Meier curve shows 75% survival at 40 months. What is the event rate at 40 months?", "opts": [["A", "25%"], ["B", "40%"], ["C", "60%"], ["D", "75%"], ["E", "100%"]], "a": "A) 25%", "e": "WORKING:\nSurvival probability = 75% = 0.75\nEvent rate = 1 − Survival probability\nEvent rate = 1 − 0.75 = 0.25 = 25%\nIf 75% survived, then 25% had the event (death/relapse)"}, {"n": "29", "stem": "Median survival is read from Kaplan-Meier curve where survival probability crosses:", "opts": [["A", "25%"], ["B", "50%"], ["C", "75%"], ["D", "95%"], ["E", "100%"]], "a": "B) 50%", "e": "WORKING:\nMedian = 50th percentile = point where 50% have survived\nOn K-M curve: find where Y-axis = 0.50 (50%)\nDraw horizontal line to curve, then down to X-axis\nThe X-axis value is the median survival time"}], "simple": "Kaplan-Meier is calculated step by step: at each event, the proportion surviving that moment is multiplied into the running total. Censored patients leave the denominator without counting as events."}, {"n": "9.2", "t": "Hazard Ratio Interpretation", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "30", "stem": "HR = 0.7 (95% CI: 0.5-0.9) for treatment vs placebo. This means:", "opts": [["A", "Treatment increases hazard by 70%"], ["B", "Treatment reduces hazard by 30%"], ["C", "Treatment has no significant effect"], ["D", "70% of patients survived"], ["E", "Result is not statistically significant"]], "a": "B) Treatment reduces hazard by 30%", "e": "WORKING:\nHR = 0.7 means treatment group has 70% the hazard of control\nHazard reduction = 1 − 0.7 = 0.30 = 30% reduction\nCI (0.5-0.9) excludes 1, so result IS significant\nHR < 1 = protective effect (beneficial treatment)"}, {"n": "31", "stem": "HR = 1.5 (95% CI: 1.2-1.9) for smoking vs non-smoking. This indicates:", "opts": [["A", "Smoking is protective"], ["B", "Smoking increases hazard by 50%"], ["C", "No significant association"], ["D", "Smoking reduces hazard by 50%"], ["E", "15% of smokers had the event"]], "a": "B) Smoking increases hazard by 50%", "e": "WORKING:\nHR = 1.5 means smokers have 1.5× (150%) the hazard of non-smokers\nExcess hazard = 1.5 − 1 = 0.5 = 50% increased hazard\nCI (1.2-1.9) excludes 1, so result IS significant\nHR > 1 = harmful exposure"}], "simple": "A hazard ratio of one means no difference. Below one favours the intervention, above one favours the control. The confidence interval tells you whether the difference is real, and the width tells you how confident you should be about its size."}, {"n": "10.1", "t": "Heterogeneity (I²)", "concepts": [], "hy": [], "tables": [], "mcqs": [{"n": "32", "stem": "A meta-analysis reports I² = 75%. This indicates:", "opts": [["A", "75% of studies agree with pooled estimate"], ["B", "Low heterogeneity"], ["C", "High heterogeneity"], ["D", "75% statistical power"], ["E", "Effect size of 0.75"]], "a": "C) High heterogeneity", "e": "WORKING:\nI² = percentage of variability due to true heterogeneity (not chance)\nI² = 25%: Low heterogeneity\nI² = 50%: Moderate heterogeneity\nI² = 75%: HIGH heterogeneity\nHigh I² suggests studies are measuring different effects - investigate why"}], "simple": "I-squared is the percentage of variation between studies that is due to real differences rather than to chance. Twenty-five is low, fifty is moderate, seventy-five is high, and high heterogeneity is a reason to question the pooling itself."}, {"n": "10.2", "t": "Forest Plot Interpretation", "concepts": [], "hy": ["FAGAN'S: Pre-test odds × LR = Post-test odds. Always convert probability ↔ odds!"], "tables": [{"cap": "Probability & Odds", "rows": [["Conversion", "Formula"], ["Probability → Odds", "Odds = P / (1 − P)"], ["Odds → Probability", "P = Odds / (1 + Odds)"], ["Post-test Odds", "Pre-test Odds × LR"]]}, {"cap": "Diagnostic Test Measures", "rows": [["Measure", "Formula"], ["Sensitivity", "TP / (TP + FN)"], ["Specificity", "TN / (TN + FP)"], ["PPV", "TP / (TP + FP)"], ["NPV", "TN / (TN + FN)"], ["LR+", "Sensitivity / (1 − Specificity)"], ["LR−", "(1 − Sensitivity) / Specificity"]]}, {"cap": "Treatment Effects", "rows": [["Measure", "Formula"], ["ARR", "CER − EER"], ["RRR", "ARR / CER"], ["NNT", "1 / ARR"], ["RR", "EER / CER"], ["NNH", "1 / ARI"]]}, {"cap": "Statistics", "rows": [["Measure", "Formula"], ["Standard Error", "SD / √n"], ["95% CI", "Mean ± (1.96 × SE)"], ["Z-score", "(X − μ) / σ"], ["Power", "1 − β"], ["Standardized difference", "Expected difference / SD"]]}, {"cap": "Key Numbers to MEMORIZE", "rows": [["Concept", "Value"], ["% outside ±1 SD", "32%"], ["% outside ±2 SD", "5%"], ["Power (standard)", "80%"], ["Type I error (α)", "5%"], ["Type II error (β)", "20%"], ["LR+ conclusive", "> 10"], ["LR− conclusive", "< 0.1"], ["I² high heterogeneity", "> 75%"]]}], "mcqs": [{"n": "33", "stem": "In a forest plot of RRs, a study shows RR = 0.6 with 95% CI (0.3 to 1.2). This study:", "opts": [["A", "Shows significant protective effect"], ["B", "Shows significant harmful effect"], ["C", "Crosses the line of no effect (not significant)"], ["D", "Has the largest sample size"], ["E", "Is an outlier that should be excluded"]], "a": "C) Crosses the line of no effect (not significant)", "e": "WORKING:\nFor RR: line of no effect = 1\nCI (0.3 to 1.2) INCLUDES 1\nTherefore result is NOT statistically significant\nOn forest plot: horizontal line crosses vertical line at 1"}, {"n": "34", "stem": "In a forest plot, Study A has a large square and short horizontal line. Study B has a small square and long horizontal line. Which is more precise?", "opts": [["A", "Study B"], ["B", "Study A"], ["C", "Both equally precise"], ["D", "Cannot determine from forest plot"], ["E", "Precision is shown by diamond shape"]], "a": "B) Study A", "e": "WORKING:\nSquare SIZE = study weight (larger = more participants)\nLine LENGTH = confidence interval (shorter = more PRECISE)\nStudy A: Large square + short line = large sample, high precision\nStudy B: Small square + long line = small sample, low precision\nStudy A contributes more to the pooled estimate"}], "simple": "Reading a forest plot for marks: find the line of no effect, see which confidence intervals cross it, look at the weights, and read the diamond. Then check the heterogeneity statistics before you believe any of it."}]}]}, {"p": "E", "name": "Advanced Topics", "sub": "Health economics, qualitative methods, and the topics that get left out.", "themes": [{"t": "Advanced Topics", "topics": [{"n": "1.1", "t": "Types Of Economic Evaluation", "concepts": [], "hy": ["Cost-UTILITY uses QALYs. Cost-EFFECTIVENESS uses natural units. Cost-BENEFIT monetises everything."], "tables": [{"cap": "Types of Economic Evaluation (MUST KNOW)", "rows": [["Type", "Costs Measured", "Outcomes Measured", "Result", "When Used"], ["Cost-Minimisation", "Money (£)", "Assumed EQUAL", "Cheapest option", "When outcomes identical"], ["Cost-Effectiveness (CEA)", "Money (£)", "Natural units (lives saved, BP reduction)", "Cost per unit gained", "Single outcome measure"], ["Cost-Utility (CUA)", "Money (£)", "QALYs", "Cost per QALY", "Comparing across diseases"], ["Cost-Benefit (CBA)", "Money (£)", "Money (£)", "Net benefit (£)", "All outcomes monetised"]]}], "mcqs": [{"n": "1", "stem": "A study compares two antidepressants measuring cost and depression-free days. This is:", "opts": [["A", "Cost-minimisation analysis"], ["B", "Cost-effectiveness analysis"], ["C", "Cost-utility analysis"], ["D", "Cost-benefit analysis"], ["E", "Budget impact analysis"]], "a": "B) Cost-effectiveness analysis", "e": "Depression-free days is a NATURAL UNIT outcome (not QALYs, not money). Cost-effectiveness analysis measures costs in money and outcomes in natural clinical units. The result would be 'cost per depression-free day'."}, {"n": "2", "stem": "Which economic evaluation measures outcomes in QALYs?", "opts": [["A", "Cost-minimisation analysis"], ["B", "Cost-effectiveness analysis"], ["C", "Cost-utility analysis"], ["D", "Cost-benefit analysis"], ["E", "Break-even analysis"]], "a": "C) Cost-utility analysis", "e": "Cost-UTILITY analysis (CUA) specifically uses Quality-Adjusted Life Years (QALYs) as the outcome measure. This allows comparison across different diseases and interventions. NICE uses CUA for most technology appraisals."}, {"n": "3", "stem": "Two drugs have been shown to have identical efficacy and safety profiles in head-to-head trials. The most appropriate economic analysis is:", "opts": [["A", "Cost-minimisation analysis"], ["B", "Cost-effectiveness analysis"], ["C", "Cost-utility analysis"], ["D", "Cost-benefit analysis"], ["E", "Markov modelling"]], "a": "A) Cost-minimisation analysis", "e": "When outcomes are IDENTICAL (equal efficacy and safety), the only relevant comparison is cost. Cost-minimisation simply identifies the cheapest option. This is the simplest form of economic evaluation."}], "simple": "Four types of economic evaluation, and the difference between them is entirely about how the outcome is measured. Money on both sides is cost-benefit. Natural units are cost-effectiveness. Quality-adjusted life years are cost-utility. Equal outcomes assumed is cost-minimisation."}, {"n": "1.2", "t": "Qalys (Quality-Adjusted Life Years)", "concepts": [{"t": "QALY CALCULATION", "b": ["QALY = Years of life × Quality of life (utility)", "Utility ranges from 0 (dead) to 1 (perfect health)", "Some states can be <0 (worse than death)", "1 QALY = 1 year in perfect health", "Example: 5 years at utility 0.8 = 5 × 0.8 = 4 QALYs"]}], "hy": [], "tables": [{"cap": "", "rows": [["📋 QALY Calculation Scenario", "📋 QALY Calculation Scenario", "📋 QALY Calculation Scenario", "📋 QALY Calculation Scenario"], ["Treatment", "Life Years Gained", "Utility Score", "QALYs Gained"], ["Drug A", "5", "0.8", "?"], ["Drug B", "8", "0.5", "?"], ["Drug C", "4", "1.0", "?"]]}], "mcqs": [{"n": "4", "stem": "A patient lives 10 years with a utility score of 0.7. How many QALYs does this represent?", "opts": [["A", "0.7 QALYs"], ["B", "7 QALYs"], ["C", "10 QALYs"], ["D", "10.7 QALYs"], ["E", "70 QALYs"]], "a": "B) 7 QALYs", "e": "WORKING:\nQALY = Years × Utility\nQALY = 10 years × 0.7\nQALY = 7\nThis is equivalent to 7 years in perfect health"}, {"n": "5", "stem": "Using the table above, which treatment provides the MOST QALYs?", "opts": [["A", "Drug A (4 QALYs)"], ["B", "Drug B (4 QALYs)"], ["C", "Drug C (4 QALYs)"], ["D", "All provide equal QALYs"], ["E", "Cannot be determined"]], "a": "D) All provide equal QALYs", "e": "WORKING:\nDrug A: 5 years × 0.8 = 4 QALYs\nDrug B: 8 years × 0.5 = 4 QALYs\nDrug C: 4 years × 1.0 = 4 QALYs\nAll three provide exactly 4 QALYs\nThis illustrates the trade-off between quantity and quality of life"}], "simple": "A quality-adjusted life year is one year of perfect health. Two years at half quality is one QALY. It exists so that a hip replacement and an antidepressant can be compared on the same scale, which is uncomfortable and unavoidable."}, {"n": "1.3", "t": "Icer (Incremental Cost-Effectiveness Ratio)", "concepts": [{"t": "ICER INTERPRETATION", "b": ["ICER = cost per additional unit of benefit", "Lower ICER = more cost-effective", "NICE threshold: £20,000-30,000 per QALY", "ICER below threshold → cost-effective → APPROVE", "ICER above threshold → not cost-effective → may REJECT", "Negative ICER can mean dominant (better AND cheaper)"]}], "hy": [], "tables": [{"cap": "", "rows": [["📋 Drug Comparison Data", "📋 Drug Comparison Data", "📋 Drug Comparison Data"], ["Treatment", "Total Cost (£)", "Total QALYs"], ["Standard care", "10,000", "5.0"], ["New drug", "25,000", "6.5"]]}, {"cap": "", "rows": [["📋 Three Treatment Comparison", "📋 Three Treatment Comparison", "📋 Three Treatment Comparison", "📋 Three Treatment Comparison"], ["Treatment", "Cost (£)", "QALYs", "ICER vs Standard"], ["Standard", "5,000", "4.0", "—"], ["Drug X", "15,000", "5.0", "?"], ["Drug Y", "35,000", "5.5", "?"], ["Drug Z", "3,000", "4.5", "?"]]}], "mcqs": [{"n": "6", "stem": "Using the table above, calculate the ICER for the new drug vs standard care:", "opts": [["A", "£2,500 per QALY"], ["B", "£10,000 per QALY"], ["C", "£15,000 per QALY"], ["D", "£25,000 per QALY"], ["E", "£100,000 per QALY"]], "a": "B) £10,000 per QALY", "e": "WORKING:\nICER = (Cost_new − Cost_standard) / (QALY_new − QALY_standard)\nICER = (£25,000 − £10,000) / (6.5 − 5.0)\nICER = £15,000 / 1.5 QALYs\nICER = £10,000 per QALY\nThis is BELOW NICE threshold (£20-30K) → likely cost-effective"}, {"n": "7", "stem": "Using the table above, which drug is DOMINANT (better outcomes AND lower cost)?", "opts": [["A", "Drug X"], ["B", "Drug Y"], ["C", "Drug Z"], ["D", "Standard care"], ["E", "None - no drug is dominant"]], "a": "C) Drug Z", "e": "WORKING:\nDominant = MORE effective AND LESS costly than comparator\nDrug Z: Costs £3,000 (LESS than Standard £5,000)\nDrug Z: Gives 4.5 QALYs (MORE than Standard 4.0)\nDrug Z is both cheaper AND more effective → DOMINANT\nThis means Drug Z should always be preferred over Standard"}, {"n": "8", "stem": "Calculate the ICER for Drug X vs Standard care:", "opts": [["A", "£1,000 per QALY"], ["B", "£5,000 per QALY"], ["C", "£10,000 per QALY"], ["D", "£15,000 per QALY"], ["E", "£30,000 per QALY"]], "a": "C) £10,000 per QALY", "e": "WORKING:\nICER = (Cost_X − Cost_Standard) / (QALY_X − QALY_Standard)\nICER = (£15,000 − £5,000) / (5.0 − 4.0)\nICER = £10,000 / 1.0 QALY\nICER = £10,000 per QALY\nBelow NICE threshold → cost-effective"}], "simple": "The incremental cost-effectiveness ratio is the extra cost divided by the extra benefit of one option over another. It is the number NICE uses, and the threshold it is compared against is a policy decision, not a scientific one."}, {"n": "1.4", "t": "Cost Types & Perspectives", "concepts": [{"t": "ECONOMIC PERSPECTIVES", "b": ["NHS/PAYER: Only NHS costs (most NICE appraisals)", "HEALTHCARE: All healthcare costs regardless of payer", "SOCIETAL: All costs including productivity losses", "PATIENT: Out-of-pocket costs to patient", "Wider perspective = more comprehensive but more complex"]}], "hy": [], "tables": [{"cap": "Types of Costs in Economic Evaluation", "rows": [["Cost Type", "Definition", "Examples"], ["Direct Medical", "Healthcare resources used", "Drugs, tests, hospital stays, staff time"], ["Direct Non-Medical", "Other resources for care", "Transport to hospital, home modifications"], ["Indirect", "Productivity losses", "Time off work, early retirement, premature death"], ["Intangible", "Pain and suffering", "Quality of life impact (usually not monetised)"]]}], "mcqs": [{"n": "9", "stem": "A patient taking time off work due to depression represents which type of cost?", "opts": [["A", "Direct medical cost"], ["B", "Direct non-medical cost"], ["C", "Indirect cost"], ["D", "Intangible cost"], ["E", "Fixed cost"]], "a": "C) Indirect cost", "e": "Productivity losses (time off work, reduced work capacity, early retirement) are INDIRECT costs. Direct medical costs are healthcare resources. Direct non-medical are other direct costs like transport. Intangible costs are pain/suffering."}, {"n": "10", "stem": "NICE technology appraisals typically use which perspective?", "opts": [["A", "Patient perspective"], ["B", "Societal perspective"], ["C", "NHS and Personal Social Services perspective"], ["D", "Global perspective"], ["E", "Hospital perspective"]], "a": "C) NHS and Personal Social Services perspective", "e": "NICE primarily uses the NHS and Personal Social Services (PSS) perspective, focusing on costs falling on the healthcare system. Wider societal costs (like productivity) may be considered in some circumstances but are not the default."}], "simple": "Costs come in kinds, and which ones you count depends on whose point of view you take. A treatment that saves the NHS money by shifting care onto families is not saving society anything. Perspective decides the answer before the arithmetic starts."}, {"n": "1.5", "t": "Discounting", "concepts": [{"t": "DISCOUNTING IN ECONOMIC EVALUATION", "b": ["Future costs and benefits are worth LESS than present ones", "Time preference: people prefer benefits NOW, costs LATER", "Standard discount rate: 3.5% per year (NICE)", "Applied to both costs AND outcomes (QALYs)", "Without discounting, future benefits are overvalued", "Makes treatments with upfront costs look worse"]}], "hy": ["Discounting rate in UK = 3.5% per year for both costs and benefits."], "tables": [], "mcqs": [{"n": "11", "stem": "In economic evaluation, discounting is applied to:", "opts": [["A", "Costs only"], ["B", "Benefits only"], ["C", "Both costs and benefits"], ["D", "Neither costs nor benefits"], ["E", "Only costs in the first year"]], "a": "C) Both costs and benefits", "e": "Discounting is applied to BOTH costs and benefits (including QALYs) to account for time preference. The UK standard rate is 3.5% per year. This reflects that £1 today is worth more than £1 in 10 years."}], "simple": "A pound today is worth more than a pound in ten years, and so is a year of health. Discounting adjusts future costs and benefits to present value, and it matters enormously for prevention, where the costs are now and the benefits are decades away."}, {"n": "1.6", "t": "Sensitivity Analysis", "concepts": [{"t": "SENSITIVITY ANALYSIS", "b": ["Tests how ROBUST results are to uncertainty", "ONE-WAY: Vary single parameter, hold others constant", "MULTI-WAY: Vary multiple parameters simultaneously", "PROBABILISTIC (PSA): Monte Carlo simulation, all parameters vary", "Results presented on cost-effectiveness plane or CEAC", "Essential for decision-making under uncertainty"]}], "hy": [], "tables": [], "mcqs": [{"n": "12", "stem": "A researcher varies the drug cost from £100 to £500 while holding all other parameters constant. This is:", "opts": [["A", "Probabilistic sensitivity analysis"], ["B", "One-way sensitivity analysis"], ["C", "Multi-way sensitivity analysis"], ["D", "Threshold analysis"], ["E", "Scenario analysis"]], "a": "B) One-way sensitivity analysis", "e": "Varying ONE parameter while holding others constant is ONE-WAY sensitivity analysis. It tests how sensitive results are to changes in that single parameter. Probabilistic sensitivity analysis varies ALL parameters simultaneously using distributions."}], "simple": "Every economic evaluation rests on assumptions that could be wrong. Sensitivity analysis changes them one at a time, or all at once, and asks whether the conclusion survives. If it does not, the conclusion was never really about the evidence."}, {"n": "2.1", "t": "Screening Biases", "concepts": [{"t": "LEAD-TIME BIAS", "b": ["Screening detects disease EARLIER", "Survival appears LONGER (from diagnosis to death)", "But actual lifespan may be UNCHANGED", "Earlier diagnosis ≠ longer life", "The 'extra' survival time is just earlier detection", "Example: Screen-detected cancer vs symptomatic cancer"]}, {"t": "LENGTH-TIME BIAS", "b": ["Screening preferentially detects SLOW-GROWING tumours", "Slow tumours have longer PRE-CLINICAL phase", "More time to be detected by screening", "Aggressive tumours progress quickly, less likely caught by screening", "Screen-detected cancers appear to have better prognosis", "May not reflect screening benefit - just different biology"]}], "hy": ["Lead-time bias: Screening makes survival APPEAR longer by detecting disease earlier, not by extending life.", "Length-time bias: Screening catches slow tumours (good prognosis) more than aggressive ones."], "tables": [], "mcqs": [{"n": "13", "stem": "A new screening test detects pancreatic cancer 2 years earlier than symptoms. 5-year survival appears to improve from 5% to 15%. This could be explained by:", "opts": [["A", "Selection bias"], ["B", "Lead-time bias"], ["C", "Length-time bias"], ["D", "Information bias"], ["E", "True survival benefit"]], "a": "B) Lead-time bias", "e": "Lead-time bias occurs when earlier detection APPEARS to improve survival simply by moving the start point earlier. If the patient dies at the same time regardless of when diagnosed, the screen-detected case has 'longer survival' only because diagnosis was earlier."}, {"n": "14", "stem": "In a breast cancer screening programme, screen-detected cancers have better survival than interval cancers (appearing between screens). This may be due to:", "opts": [["A", "Selection bias"], ["B", "Lead-time bias"], ["C", "Length-time bias"], ["D", "Observer bias"], ["E", "All of the above except D"]], "a": "E) All of the above except D", "e": "Both lead-time AND length-time bias contribute. Lead-time: earlier detection inflates survival. Length-time: slow-growing tumours more likely caught by screening. Selection bias: those who attend screening may be healthier. All three explain apparently better outcomes."}], "simple": "Screening can appear to save lives without saving any. Lead-time bias moves the diagnosis earlier without moving the death. Length-time bias catches the slow-growing cancers preferentially. Overdiagnosis finds disease that would never have caused harm."}, {"n": "2.2", "t": "Case-Control Biases", "concepts": [{"t": "BERKSON'S BIAS (Admission Rate Bias)", "b": ["Occurs when BOTH exposure AND disease affect hospitalisation", "Hospital-based case-control studies affected", "Controls from hospital may have higher exposure rates", "Creates SPURIOUS association", "Example: Hospital cases of lung cancer and hospital controls", "Solution: Population-based controls"]}, {"t": "NEYMAN BIAS (Prevalence-Incidence Bias / Survival Bias)", "b": ["Cases in case-control study are PREVALENT (surviving) cases", "Misses cases who died quickly", "Association appears different than true causal effect", "Exposures associated with rapid death are UNDERESTIMATED", "Exposures associated with survival are OVERESTIMATED", "Solution: Use incident (new) cases"]}], "hy": ["Berkson's bias: Hospital controls may have different exposure rates than population. Use population-based controls.", "Neyman bias: Prevalent cases miss those who died quickly. May miss associations with fatal exposures."], "tables": [{"cap": "Screening & Selection Biases Summary", "rows": [["Bias", "Mechanism", "Direction of Effect"], ["Lead-time", "Earlier detection, not longer life", "Overestimates survival benefit"], ["Length-time", "Slow tumours caught more often", "Overestimates survival benefit"], ["Berkson's", "Hospital controls have different exposures", "Spurious association"], ["Neyman", "Survivors only, miss fatal cases", "Underestimates exposure effect"]]}], "mcqs": [{"n": "15", "stem": "A case-control study uses hospital patients as controls. Smokers are over-represented among controls because smoking causes many conditions leading to hospitalisation. This is:", "opts": [["A", "Selection bias"], ["B", "Berkson's bias"], ["C", "Neyman bias"], ["D", "Recall bias"], ["E", "Confounding"]], "a": "B) Berkson's bias", "e": "Berkson's bias (admission rate bias) occurs in hospital-based studies when exposure (smoking) affects hospitalisation of controls. Hospital controls have higher exposure rates than the general population, creating spurious or attenuated associations."}, {"n": "16", "stem": "A case-control study of myocardial infarction (MI) only includes survivors. An exposure that causes immediate death from MI would appear:", "opts": [["A", "Strongly associated with MI"], ["B", "Protective against MI"], ["C", "Unassociated or weakly associated with MI"], ["D", "A confounder"], ["E", "To increase survival"]], "a": "C) Unassociated or weakly associated with MI", "e": "Neyman bias (survival bias). If an exposure causes immediately fatal MI, those cases die and are not available to be 'cases'. The study only sees survivors, so the association is underestimated or missed entirely."}], "simple": "Case-control studies have their own family of traps. Recall bias, because ill people search their memories harder. Berkson's bias, because hospital controls are not ordinary people. Choosing the control group is where most case-control studies are won or lost."}, {"n": "3.1", "t": "Cohen'S D (Effect Size)", "concepts": [], "hy": [], "tables": [{"cap": "Cohen's d Interpretation (MEMORISE)", "rows": [["Cohen's d", "Effect Size", "Meaning"], ["0.2", "SMALL", "Difficult to see with naked eye"], ["0.5", "MEDIUM", "Visible to careful observer"], ["0.8", "LARGE", "Obvious to any observer"]]}, {"cap": "", "rows": [["📋 Treatment Trial Data", "📋 Treatment Trial Data", "📋 Treatment Trial Data", "📋 Treatment Trial Data"], ["Group", "Mean Score", "SD", "n"], ["Treatment", "75", "10", "50"], ["Control", "70", "10", "50"]]}], "mcqs": [{"n": "17", "stem": "A study reports Cohen's d = 0.3 for difference between treatment and control. This represents:", "opts": [["A", "No effect"], ["B", "Small effect"], ["C", "Medium effect"], ["D", "Large effect"], ["E", "Very large effect"]], "a": "B) Small effect", "e": "Cohen's conventions: d = 0.2 is small, d = 0.5 is medium, d = 0.8 is large. A d of 0.3 falls in the small effect range. Effect size is independent of sample size and statistical significance."}, {"n": "18", "stem": "Using the table above, calculate Cohen's d:", "opts": [["A", "0.2"], ["B", "0.5"], ["C", "0.8"], ["D", "5.0"], ["E", "50"]], "a": "B) 0.5", "e": "WORKING:\nCohen's d = (Mean₁ − Mean₂) / Pooled SD\nSince both SDs are equal (10), pooled SD = 10\nd = (75 − 70) / 10\nd = 5 / 10 = 0.5\nThis is a MEDIUM effect size"}], "simple": "Cohen's d expresses a difference in standard deviations. Point two is small, point five is medium, point eight is large. Three numbers, and they let you judge whether a statistically significant finding is worth anything."}, {"n": "3.2", "t": "Degrees Of Freedom", "concepts": [], "hy": [], "tables": [{"cap": "Degrees of Freedom Formulas (MUST KNOW)", "rows": [["Test", "Formula", "Example"], ["One-sample t-test", "df = n − 1", "n=30 → df=29"], ["Independent t-test", "df = n₁ + n₂ − 2", "n₁=20, n₂=20 → df=38"], ["Paired t-test", "df = n (pairs) − 1", "15 pairs → df=14"], ["Chi-square", "df = (rows−1)(cols−1)", "2×3 table → df=2"], ["One-way ANOVA (between)", "df = k − 1", "4 groups → df=3"], ["One-way ANOVA (within)", "df = N − k", "40 total, 4 groups → df=36"], ["Pearson correlation", "df = n − 2", "n=52 → df=50"]]}], "mcqs": [{"n": "19", "stem": "A study compares 3 groups with 20 participants each (N=60). For one-way ANOVA, the BETWEEN-groups df is:", "opts": [["A", "2"], ["B", "3"], ["C", "57"], ["D", "59"], ["E", "60"]], "a": "A) 2", "e": "WORKING:\nBetween-groups df = k − 1 (where k = number of groups)\ndf = 3 − 1 = 2\nWithin-groups df = N − k = 60 − 3 = 57\nTotal df = N − 1 = 59"}, {"n": "20", "stem": "A chi-square test is performed on a 3×4 contingency table. The df is:", "opts": [["A", "6"], ["B", "7"], ["C", "11"], ["D", "12"], ["E", "3"]], "a": "A) 6", "e": "WORKING:\nChi-square df = (rows − 1) × (columns − 1)\ndf = (3 − 1) × (4 − 1)\ndf = 2 × 3 = 6\nThis applies to all chi-square tests of independence"}, {"n": "21", "stem": "A paired t-test is performed on 25 pairs of observations. The df is:", "opts": [["A", "23"], ["B", "24"], ["C", "25"], ["D", "48"], ["E", "49"]], "a": "B) 24", "e": "WORKING:\nPaired t-test df = n − 1 (where n = number of pairs)\ndf = 25 − 1 = 24\nNote: This is the same as one-sample t-test on differences\nNOT 48 (which would be for independent t-test with n₁=n₂=25)"}], "simple": "Degrees of freedom for each test, as a list. There is no insight to be had here and no benefit in understanding it deeply. Learn the formulas, get the marks, move on."}, {"n": "4.1", "t": "2×2 Table Calculations", "concepts": [], "hy": [], "tables": [{"cap": "", "rows": [["Screening Test Results", "Screening Test Results", "Screening Test Results", "Screening Test Results"], ["", "", "DISEASE", "DISEASE"], ["", "", "Present (+)", "Absent (−)"], ["TEST", "Pos (+)", "45", "15"], ["TEST", "Neg (−)", "5", "135"]]}], "mcqs": [{"n": "22", "stem": "Using the table above, calculate the SENSITIVITY:", "opts": [["A", "75%"], ["B", "90%"], ["C", "97%"], ["D", "25%"], ["E", "45%"]], "a": "B) 90%", "e": "WORKING:\nSensitivity = TP / (TP + FN)\nSensitivity = 45 / (45 + 5)\nSensitivity = 45 / 50 = 0.90 = 90%\n90% of people WITH disease test positive"}, {"n": "23", "stem": "Using the same table, calculate the SPECIFICITY:", "opts": [["A", "75%"], ["B", "90%"], ["C", "97%"], ["D", "10%"], ["E", "27%"]], "a": "B) 90%", "e": "WORKING:\nSpecificity = TN / (TN + FP)\nSpecificity = 135 / (135 + 15)\nSpecificity = 135 / 150 = 0.90 = 90%\n90% of people WITHOUT disease test negative"}, {"n": "24", "stem": "Using the same table, calculate the POSITIVE PREDICTIVE VALUE:", "opts": [["A", "75%"], ["B", "90%"], ["C", "97%"], ["D", "10%"], ["E", "50%"]], "a": "A) 75%", "e": "WORKING:\nPPV = TP / (TP + FP)\nPPV = 45 / (45 + 15)\nPPV = 45 / 60 = 0.75 = 75%\n75% of positive tests are TRUE positives"}, {"n": "25", "stem": "Calculate the NEGATIVE PREDICTIVE VALUE:", "opts": [["A", "75%"], ["B", "90%"], ["C", "96%"], ["D", "97%"], ["E", "50%"]], "a": "D) 97%", "e": "WORKING:\nNPV = TN / (TN + FN)\nNPV = 135 / (135 + 5)\nNPV = 135 / 140 = 0.964 ≈ 97%\n97% of negative tests are TRUE negatives"}, {"n": "26", "stem": "Calculate the LR+ for this test:", "opts": [["A", "4.5"], ["B", "9"], ["C", "0.9"], ["D", "0.11"], ["E", "3"]], "a": "B) 9", "e": "WORKING:\nLR+ = Sensitivity / (1 − Specificity)\nLR+ = 0.90 / (1 − 0.90)\nLR+ = 0.90 / 0.10 = 9\nA positive test increases odds of disease by factor of 9"}], "simple": "Given a filled-in two by two table, produce every measure that can be derived from it. This is the single most efficient thing you can practise, because one table can generate a dozen different exam questions."}, {"n": "4.2", "t": "Different 2×2 Table", "concepts": [], "hy": [], "tables": [{"cap": "", "rows": [["New Diagnostic Test", "New Diagnostic Test", "New Diagnostic Test", "New Diagnostic Test"], ["", "", "DISEASE", "DISEASE"], ["", "", "Present (+)", "Absent (−)"], ["TEST", "Pos (+)", "80", "40"], ["TEST", "Neg (−)", "20", "160"]]}], "mcqs": [{"n": "27", "stem": "Calculate the PREVALENCE of disease in this sample:", "opts": [["A", "20%"], ["B", "27%"], ["C", "33%"], ["D", "40%"], ["E", "67%"]], "a": "C) 33%", "e": "WORKING:\nPrevalence = All with disease / Total sample\nAll with disease = TP + FN = 80 + 20 = 100\nTotal sample = 80 + 40 + 20 + 160 = 300\nPrevalence = 100 / 300 = 0.333 = 33%"}, {"n": "28", "stem": "Calculate the ACCURACY of this test:", "opts": [["A", "67%"], ["B", "75%"], ["C", "80%"], ["D", "85%"], ["E", "90%"]], "a": "C) 80%", "e": "WORKING:\nAccuracy = (TP + TN) / Total\nAccuracy = (80 + 160) / 300\nAccuracy = 240 / 300 = 0.80 = 80%\n80% of all results (positive or negative) are correct"}], "simple": "The same skill against a different table, because the numbers move and the layout sometimes changes. The discipline is always to label the table before touching a formula."}, {"n": "5.1", "t": "Anova Output Interpretation", "concepts": [], "hy": [], "tables": [{"cap": "", "rows": [["📋 ANOVA Results: Treatment Groups", "📋 ANOVA Results: Treatment Groups", "📋 ANOVA Results: Treatment Groups", "📋 ANOVA Results: Treatment Groups", "📋 ANOVA Results: Treatment Groups", "📋 ANOVA Results: Treatment Groups"], ["Source", "SS", "df", "MS", "F", "p-value"], ["Between Groups", "120", "2", "60", "15.0", "0.001"], ["Within Groups", "180", "45", "4", "—", "—"], ["Total", "300", "47", "—", "—", "—"]]}], "mcqs": [{"n": "29", "stem": "Based on the ANOVA table above, how many groups are being compared?", "opts": [["A", "2"], ["B", "3"], ["C", "45"], ["D", "47"], ["E", "48"]], "a": "B) 3", "e": "WORKING:\nBetween-groups df = k − 1 (where k = number of groups)\ndf = 2, so k − 1 = 2\nk = 3 groups\nAlso: Total N = df_total + 1 = 47 + 1 = 48 participants"}, {"n": "30", "stem": "The ANOVA is significant (p=0.001). The next step should be:", "opts": [["A", "Accept the null hypothesis"], ["B", "Conclude all groups differ from each other"], ["C", "Perform post-hoc tests to identify which groups differ"], ["D", "Repeat the study with larger sample"], ["E", "Report only the largest difference"]], "a": "C) Perform post-hoc tests to identify which groups differ", "e": "ANOVA tells us that AT LEAST two groups differ, but not WHICH ones. Post-hoc tests (Tukey, Bonferroni, Scheffé) are needed to make pairwise comparisons while controlling for multiple testing."}], "simple": "ANOVA output has a fixed shape: sums of squares, degrees of freedom, mean squares, an F statistic and a p value. You will not be asked to calculate it. You will be asked to read it and say what it means."}, {"n": "5.2", "t": "Post-Hoc Tests", "concepts": [], "hy": [], "tables": [{"cap": "Post-Hoc Test Selection", "rows": [["Test", "When to Use", "Features"], ["Tukey's HSD", "All pairwise comparisons, equal n", "Most common, balanced design"], ["Bonferroni", "Few planned comparisons", "Conservative, any design"], ["Scheffé", "Complex comparisons", "Most conservative"], ["Dunnett", "Compare all to control only", "Efficient for control comparisons"], ["Games-Howell", "Unequal variances", "Does not assume equal variance"]]}], "mcqs": [{"n": "31", "stem": "A researcher plans to make 10 comparisons using Bonferroni correction at overall α = 0.05. The adjusted α for each comparison is:", "opts": [["A", "0.50"], ["B", "0.05"], ["C", "0.005"], ["D", "0.10"], ["E", "0.025"]], "a": "C) 0.005", "e": "WORKING:\nBonferroni correction: α_adjusted = α / number of comparisons\nα_adjusted = 0.05 / 10 = 0.005\nEach comparison must be significant at p < 0.005\nThis maintains overall Type I error at 5%"}], "simple": "An ANOVA tells you something differs but not what. Post-hoc tests find the specific pairs, and different tests make different trade-offs between finding real differences and generating false ones."}, {"n": "5.3", "t": "Statistical Assumptions", "concepts": [], "hy": [], "tables": [{"cap": "Testing Statistical Assumptions", "rows": [["Assumption", "Test", "If Violated"], ["Normality", "Shapiro-Wilk, Kolmogorov-Smirnov", "Use non-parametric test"], ["Homoscedasticity (equal variances)", "Levene's test", "Use Welch's t-test or transform"], ["Independence", "Study design", "Use paired/repeated measures"], ["Linearity", "Scatter plot, residual plot", "Transform or use non-linear"]]}], "mcqs": [{"n": "32", "stem": "Levene's test gives p = 0.02. This indicates:", "opts": [["A", "Variances are equal, proceed with standard t-test"], ["B", "Variances are unequal, use Welch's t-test"], ["C", "Data is normally distributed"], ["D", "Data is not normally distributed"], ["E", "The main hypothesis is significant"]], "a": "B) Variances are unequal, use Welch's t-test", "e": "Levene's test checks HOMOSCEDASTICITY (equal variances). Significant p-value (p < 0.05) means variances are UNEQUAL. Use Welch's t-test instead of Student's t-test, as Welch's doesn't assume equal variances."}, {"n": "33", "stem": "Shapiro-Wilk test gives p = 0.35 for your dependent variable. This suggests:", "opts": [["A", "Data is significantly non-normal"], ["B", "Data can be assumed normally distributed"], ["C", "Variances are equal"], ["D", "Use non-parametric test"], ["E", "Sample size is too small"]], "a": "B) Data can be assumed normally distributed", "e": "Shapiro-Wilk tests normality. Non-significant p-value (p > 0.05) means we FAIL to reject normality - data can be assumed normal. If p < 0.05, normality is violated and non-parametric alternatives should be considered."}], "simple": "Every test carries assumptions, and each assumption has a test of its own. Knowing which check goes with which assumption is a small table that reliably earns marks."}, {"n": "6.1", "t": "Analysis Methods", "concepts": [{"t": "FRAMEWORK ANALYSIS (5 STAGES)", "b": ["1. FAMILIARISATION: Immersion in the data", "2. IDENTIFYING FRAMEWORK: Develop thematic framework", "3. INDEXING: Apply framework systematically to data", "4. CHARTING: Create matrix (cases × themes)", "5. MAPPING & INTERPRETATION: Identify patterns, explain"]}], "hy": ["Framework analysis: 5 stages, matrix-based, often used in applied policy research. More structured than thematic analysis."], "tables": [{"cap": "Qualitative Analysis Methods", "rows": [["Method", "Description", "Key Features"], ["Thematic Analysis", "Identify themes/patterns", "Flexible, common, inductive or deductive"], ["Content Analysis", "Systematic analysis of text/media", "Can be quantitative (counting)"], ["Grounded Theory", "Theory emerges from data", "Constant comparison, saturation"], ["Framework Analysis", "Matrix-based, policy research", "5 stages, structured, transparent"], ["Discourse Analysis", "Language, power, social context", "How language constructs reality"], ["IPA", "Individual lived experience", "Phenomenological, idiographic"], ["Narrative Analysis", "Stories and storytelling", "Temporal, biographical"]]}], "mcqs": [{"n": "34", "stem": "A qualitative study creates a matrix with participants as rows and themes as columns, systematically charting data. This is characteristic of:", "opts": [["A", "Grounded theory"], ["B", "Thematic analysis"], ["C", "Framework analysis"], ["D", "Discourse analysis"], ["E", "Content analysis"]], "a": "C) Framework analysis", "e": "Framework analysis uses a MATRIX approach (cases × themes) to organise data systematically. It has 5 defined stages and is more structured/transparent than thematic analysis. Often used in applied health research and policy evaluation."}, {"n": "35", "stem": "A researcher examines how psychiatric diagnoses are constructed through professional language and power dynamics. This approach is:", "opts": [["A", "Thematic analysis"], ["B", "Content analysis"], ["C", "Grounded theory"], ["D", "Discourse analysis"], ["E", "Framework analysis"]], "a": "D) Discourse analysis", "e": "Discourse analysis examines how LANGUAGE constructs social reality, including power dynamics, social contexts, and how meaning is created. It's particularly relevant for examining how diagnoses and professional categories are constructed."}], "simple": "The qualitative analysis methods side by side, because in the exam they are almost always tested as a discrimination rather than in isolation. Which method, which purpose, which output."}, {"n": "7.1", "t": "Integrated Scenarios", "concepts": [], "hy": [], "tables": [{"cap": "", "rows": [["📋 PHQ-9 Screening in Primary Care", "📋 PHQ-9 Screening in Primary Care", "📋 PHQ-9 Screening in Primary Care"], ["PHQ-9 Score", "Depressed (n=200)", "Not Depressed (n=800)"], ["≥5", "190", "320"], ["≥10", "170", "120"], ["≥15", "120", "40"], ["≥20", "60", "8"]]}], "mcqs": [{"n": "36", "stem": "At cut-off ≥10, what is the SENSITIVITY for detecting depression?", "opts": [["A", "60%"], ["B", "75%"], ["C", "85%"], ["D", "90%"], ["E", "95%"]], "a": "C) 85%", "e": "WORKING:\nAt ≥10: 170 depressed patients screen positive\nTotal depressed = 200\nSensitivity = 170/200 = 0.85 = 85%\n85% of depressed patients are detected"}, {"n": "37", "stem": "At cut-off ≥10, what is the SPECIFICITY?", "opts": [["A", "60%"], ["B", "75%"], ["C", "85%"], ["D", "90%"], ["E", "95%"]], "a": "C) 85%", "e": "WORKING:\nAt ≥10: 120 not-depressed screen positive (FP)\nTherefore: 800 − 120 = 680 screen negative (TN)\nSpecificity = TN / (TN + FP) = 680/800 = 0.85 = 85%\n85% of non-depressed correctly test negative"}, {"n": "38", "stem": "Comparing cut-offs ≥10 and ≥15, which statement is TRUE?", "opts": [["A", "≥15 has higher sensitivity than ≥10"], ["B", "≥15 has lower specificity than ≥10"], ["C", "≥15 has higher specificity than ≥10"], ["D", "Both have equal sensitivity"], ["E", "PPV is unchanged between cut-offs"]], "a": "C) ≥15 has higher specificity than ≥10", "e": "WORKING:\nAt ≥15: Sens = 120/200 = 60%, Spec = 760/800 = 95%\nAt ≥10: Sens = 85%, Spec = 85%\nHIGHER cut-off → LOWER sensitivity, HIGHER specificity\nThis is the fundamental sensitivity-specificity trade-off"}], "simple": "Integrated scenarios put several skills into one question: read the table, calculate the measure, interpret the confidence interval, and say what you would do. This is what the real paper looks like."}, {"n": "7.2", "t": "Treatment Comparison", "concepts": [], "hy": ["NICE threshold: £20,000-30,000 per QALY. ICER below threshold = cost-effective. Discount rate = 3.5%."], "tables": [{"cap": "", "rows": [["📋 Relapse Prevention Trial Results", "📋 Relapse Prevention Trial Results", "📋 Relapse Prevention Trial Results", "📋 Relapse Prevention Trial Results", "📋 Relapse Prevention Trial Results"], ["Treatment", "n", "Relapsed", "Relapse Rate", "Cost (£)"], ["Placebo", "100", "40", "40%", "500"], ["Drug A", "100", "30", "30%", "2,500"], ["Drug B", "100", "20", "20%", "5,000"], ["Drug C", "100", "35", "35%", "1,000"]]}, {"cap": "", "rows": [["Mental Health Assessment Tool", "Mental Health Assessment Tool", "Mental Health Assessment Tool", "Mental Health Assessment Tool"], ["", "", "DISEASE", "DISEASE"], ["", "", "Present (+)", "Absent (−)"], ["TEST", "Pos (+)", "72", "18"], ["TEST", "Neg (−)", "8", "102"]]}, {"cap": "", "rows": [["📋 Cost-Utility Analysis Summary", "📋 Cost-Utility Analysis Summary", "📋 Cost-Utility Analysis Summary", "📋 Cost-Utility Analysis Summary", "📋 Cost-Utility Analysis Summary", "📋 Cost-Utility Analysis Summary"], ["Strategy", "Cost", "QALYs", "Incremental Cost", "Incremental QALYs", "ICER"], ["No treatment", "£0", "10.0", "—", "—", "—"], ["Drug X", "£10,000", "11.5", "£10,000", "1.5", "£6,667"], ["Drug Y", "£30,000", "12.0", "£20,000", "0.5", "£40,000"], ["Drug Z", "£50,000", "12.2", "£20,000", "0.2", "£100,000"]]}, {"cap": "Economic Evaluation Summary", "rows": [["Analysis Type", "Outcome Measure", "Result"], ["Cost-minimisation", "Assumed equal", "Cheapest option"], ["Cost-effectiveness", "Natural units", "Cost per unit"], ["Cost-utility", "QALYs", "Cost per QALY (ICER)"], ["Cost-benefit", "Money (£)", "Net benefit"]]}, {"cap": "Bias Summary", "rows": [["Bias", "Key Point"], ["Lead-time", "Earlier detection ≠ longer life"], ["Length-time", "Screening catches slow tumours"], ["Berkson's", "Hospital controls differ from population"], ["Neyman", "Survivors only, miss fatal cases"]]}, {"cap": "Effect Size (Cohen's d)", "rows": [["Value", "Interpretation"], ["0.2", "Small effect"], ["0.5", "Medium effect"], ["0.8", "Large effect"]]}], "mcqs": [{"n": "39", "stem": "Calculate the NNT for Drug B vs Placebo:", "opts": [["A", "2"], ["B", "5"], ["C", "10"], ["D", "20"], ["E", "50"]], "a": "B) 5", "e": "WORKING:\nARR = Placebo rate − Drug B rate = 40% − 20% = 20%\nNNT = 1/ARR = 1/0.20 = 5\nTreat 5 patients with Drug B to prevent 1 relapse\nvs placebo"}, {"n": "40", "stem": "Which drug has the LOWEST cost per relapse prevented vs placebo?", "opts": [["A", "Drug A"], ["B", "Drug B"], ["C", "Drug C"], ["D", "All have equal cost-effectiveness"], ["E", "Cannot be determined"]], "a": "C) Drug C", "e": "WORKING:\nDrug A: NNT = 1/(40%-30%) = 10, Cost = 10 × £2,500 = £25,000 per relapse prevented\nDrug B: NNT = 5, Cost = 5 × £5,000 = £25,000 per relapse prevented\nDrug C: NNT = 1/(40%-35%) = 20, Cost = 20 × £1,000 = £20,000 per relapse prevented\nDrug C is most cost-effective despite higher NNT"}, {"n": "41", "stem": "Calculate ALL measures for the table above:", "opts": [], "a": "See calculations below:", "e": "WORKING:\nSensitivity = 72/(72+8) = 72/80 = 90%\nSpecificity = 102/(102+18) = 102/120 = 85%\nPPV = 72/(72+18) = 72/90 = 80%\nNPV = 102/(102+8) = 102/110 = 93%\nLR+ = 0.90/0.15 = 6.0\nLR− = 0.10/0.85 = 0.12\nPrevalence = 80/200 = 40%\nAccuracy = (72+102)/200 = 87%"}, {"n": "42", "stem": "Using the test above with prevalence 40%, if a patient tests POSITIVE, post-test probability of disease is approximately:", "opts": [["A", "40%"], ["B", "60%"], ["C", "80%"], ["D", "90%"], ["E", "95%"]], "a": "C) 80%", "e": "WORKING:\nThis is just the PPV! PPV = 72/90 = 80%\nOR use Fagan: Pre-test odds = 0.4/0.6 = 0.67\nPost-test odds = 0.67 × 6.0 = 4.0\nPost-test prob = 4.0/5.0 = 0.80 = 80%\nBoth methods give 80%"}, {"n": "43", "stem": "Using NICE threshold of £20,000-30,000 per QALY, which treatments would be considered cost-effective?", "opts": [["A", "Drug X only"], ["B", "Drugs X and Y"], ["C", "Drugs X, Y, and Z"], ["D", "No treatment only"], ["E", "All options are cost-effective"]], "a": "A) Drug X only", "e": "WORKING:\nDrug X: ICER £6,667/QALY - BELOW threshold ✓\nDrug Y: ICER £40,000/QALY - ABOVE threshold ✗\nDrug Z: ICER £100,000/QALY - Well ABOVE threshold ✗\nOnly Drug X would be approved at standard NICE threshold"}], "simple": "Comparing treatments across a set of tables, which is the hardest format in the paper because there is nowhere to hide. Everything you have learned in Parts A to E arrives at once."}]}]}];
